final_template:
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 2)
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw"
  }
}

resource "aws_subnet" "public" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_subnet" "private" {
  count = 2

  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(local.vpc_cidr, 8, count.index + 10)
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "private-subnet-${count.index}"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  depends_on = [aws_internet_gateway.main]

  tags = {
    Name = "main-nat"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "public-route-table"
  }
}

resource "aws_route_table_association" "public" {
  count = 2

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "private-route-table"
  }
}

resource "aws_route_table_association" "private" {
  count = 2

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "alb" {
  name        = "alb"
  description = "Security group for the Application Load Balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "Allow inbound HTTP traffic from any IP address"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Allow outbound traffic only within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "alb"
  }
}

resource "aws_security_group" "allow_alb" {
  name        = "allow_alb"
  description = "Security group for backend EC2 instances allowing traffic from the ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Allow inbound HTTP exclusively from the ALB security group"
    from_port       = 80
    to_port         = 80
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Allow outbound traffic only within the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "allow_alb"
  }
}

data "aws_ami" "amazon_linux" {
  most_recent = true
  owners      = ["amazon"]

  filter {
    name   = "name"
    values = ["al2023-ami-*-x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }
}

resource "tls_private_key" "alb" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "alb" {
  private_key_pem = tls_private_key.alb.private_key_pem

  subject {
    common_name  = "internal-alb.local"
    organization = "internal"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "alb" {
  certificate_body = tls_self_signed_cert.alb.cert_pem
  private_key      = tls_private_key.alb.private_key_pem

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_launch_template" "backend" {
  name_prefix   = "backend-"
  image_id      = data.aws_ami.amazon_linux.id
  instance_type = "t3.micro"

  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 1
  }

  user_data = base64encode(<<-EOT
    #!/bin/bash
    dnf install -y httpd
    systemctl enable --now httpd
    echo "OK" > /var/www/html/index.html
  EOT
  )

  tag_specifications {
    resource_type = "instance"

    tags = {
      Name = "backend-instance"
    }
  }
}

resource "aws_instance" "backend" {
  count = 2

  subnet_id              = aws_subnet.private[count.index].id
  vpc_security_group_ids = [aws_security_group.allow_alb.id]

  launch_template {
    id      = aws_launch_template.backend.id
    version = "$Latest"
  }

  root_block_device {
    volume_size = 30
    volume_type = "gp3"
    encrypted   = true
  }

  tags = {
    Name = "backend-instance"
  }
}

resource "aws_lb" "main" {
  name                       = "main-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.private[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "main-alb"
  }
}

resource "aws_lb_target_group" "backend" {
  name     = "backend-tg"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    protocol            = "HTTP"
    matcher             = "200"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 2
    unhealthy_threshold = 2
  }

  tags = {
    Name = "backend-tg"
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_lb_target_group_attachment" "backend" {
  count = 2

  target_group_arn = aws_lb_target_group.backend.arn
  target_id        = aws_instance.backend[count.index].id
  port             = 80
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.alb.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.backend.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.main.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  name_prefix         = "net-test"
  vpc_cidr            = "10.0.0.0/16"
  public_subnet_cidr  = "10.0.1.0/24"
  private_subnet_cidr = "10.0.2.0/24"
  ipv4_anywhere       = "0.0.0.0/0"
  ipv6_anywhere       = "::/0"
}

resource "aws_vpc" "main" {
  cidr_block                       = local.vpc_cidr
  assign_generated_ipv6_cidr_block = true
  enable_dns_support               = true
  enable_dns_hostnames             = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "public" {
  vpc_id                          = aws_vpc.main.id
  cidr_block                      = local.public_subnet_cidr
  ipv6_cidr_block                 = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 0)
  availability_zone               = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch         = false
  assign_ipv6_address_on_creation = false

  tags = {
    Name = "${local.name_prefix}-public-subnet"
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidr
  ipv6_cidr_block   = cidrsubnet(aws_vpc.main.ipv6_cidr_block, 8, 1)
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = {
    Name = "${local.name_prefix}-private-subnet"
    Tier = "private"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route" "public_ipv4_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = local.ipv4_anywhere
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6_internet" {
  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = local.ipv6_anywhere
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region in which the networking stack is deployed."
  type        = string
  default     = "us-east-1"
}

variable "vpc_cidr" {
  description = "CIDR block assigned to the main VPC."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrnetmask(var.vpc_cidr))
    error_message = "The vpc_cidr value must be a valid IPv4 CIDR block (e.g. 10.0.0.0/16)."
  }
}

variable "availability_zones" {
  description = "Explicit list of availability zones to spread subnets across. When empty, the first two available AZs in the region are used."
  type        = list(string)
  default     = []
}

variable "subnet_cidrs" {
  description = "CIDR blocks assigned to the subnets, indexed positionally against the selected availability zones."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]

  validation {
    condition     = length(var.subnet_cidrs) > 0
    error_message = "At least one subnet CIDR block must be provided."
  }
}

variable "tags" {
  description = "Additional tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

locals {
  # Use the caller-supplied AZ list when provided, otherwise fall back to the
  # first two available (non opt-in) availability zones in the region.
  availability_zones = length(var.availability_zones) > 0 ? var.availability_zones : slice(data.aws_availability_zones.available.names, 0, 2)

  # One subnet per selected AZ; CIDRs are consumed positionally and wrap around
  # if fewer CIDRs than AZs are supplied.
  subnet_count = length(local.availability_zones)

  common_tags = merge(
    {
      ManagedBy = "Terraform"
      Region    = var.aws_region
    },
    var.tags
  )
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "main-vpc"
    }
  )
}

resource "aws_subnet" "main" {
  count = local.subnet_count

  vpc_id                  = aws_vpc.main.id
  cidr_block              = element(var.subnet_cidrs, count.index)
  availability_zone       = local.availability_zones[count.index]
  map_public_ip_on_launch = false

  tags = merge(
    local.common_tags,
    {
      Name = "main-subnet-${count.index}"
    }
  )
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(
    local.common_tags,
    {
      Name = "main-igw"
    }
  )
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "main-public-rt"
    }
  )
}

resource "aws_route_table_association" "public" {
  count = local.subnet_count

  subnet_id      = aws_subnet.main[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_default_security_group" "main" {
  vpc_id = aws_vpc.main.id

  ingress = []

  tags = merge(
    local.common_tags,
    {
      Name = "main-default-sg"
    }
  )
}

output "vpc_id" {
  description = "Identifier of the main VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the main VPC."
  value       = aws_vpc.main.cidr_block
}

output "subnet_ids" {
  description = "Identifiers of the subnets created in the VPC, ordered by availability zone."
  value       = aws_subnet.main[*].id
}

output "subnet_cidr_blocks" {
  description = "CIDR blocks of the subnets created in the VPC."
  value       = aws_subnet.main[*].cidr_block
}

output "availability_zones" {
  description = "Availability zones used by the subnets."
  value       = local.availability_zones
}

output "internet_gateway_id" {
  description = "Identifier of the internet gateway attached to the VPC."
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "Identifier of the public route table associated with the subnets."
  value       = aws_route_table.public.id
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

################################################################################
# Inputs
################################################################################

variable "monitoring_account_ids" {
  description = "AWS account IDs that host the Amazon Managed Grafana workspace(s) permitted to assume the Grafana data source role. When left empty, the account this configuration is deployed in is used."
  type        = list(string)
  default     = []

  validation {
    condition     = alltrue([for account_id in var.monitoring_account_ids : can(regex("^[0-9]{12}$", account_id))])
    error_message = "Every monitoring account ID must be a 12-digit AWS account ID."
  }
}

################################################################################
# Locals
################################################################################

locals {
  grafana_workspace_name = "Grafana"
  role_name              = "grafana-amp-cloudwatch-data-source"
  policy_name            = "grafana-amp-cloudwatch-data-source"

  partition = data.aws_partition.current.partition

  # Accounts permitted to assume the role: the explicitly supplied monitoring
  # accounts, or the account this configuration is deployed in when none are
  # supplied.
  monitoring_account_ids = length(var.monitoring_account_ids) > 0 ? distinct(var.monitoring_account_ids) : [data.aws_caller_identity.current.account_id]

  # Confused deputy protection: only Amazon Managed Grafana resources that
  # live in the monitoring accounts may use this role.
  grafana_source_arns = [
    for account_id in local.monitoring_account_ids :
    "arn:${local.partition}:grafana:*:${account_id}:*"
  ]
}

################################################################################
# Trust policy - only Amazon Managed Grafana in the monitoring accounts
################################################################################

data "aws_iam_policy_document" "grafana_assume_role" {
  statement {
    sid     = "AllowAmazonManagedGrafanaToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["grafana.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = local.monitoring_account_ids
    }

    condition {
      test     = "StringLike"
      variable = "aws:SourceArn"
      values   = local.grafana_source_arns
    }
  }
}

resource "aws_iam_role" "grafana_data_source" {
  name                 = local.role_name
  description          = "Assumed by the Amazon Managed Grafana workspace ${local.grafana_workspace_name} to query Amazon Managed Service for Prometheus and CloudWatch metrics."
  assume_role_policy   = data.aws_iam_policy_document.grafana_assume_role.json
  max_session_duration = 3600

  tags = {
    Name             = local.role_name
    GrafanaWorkspace = local.grafana_workspace_name
    ManagedBy        = "terraform"
  }
}

################################################################################
# Permissions policy - Amazon Managed Service for Prometheus + CloudWatch
################################################################################

data "aws_iam_policy_document" "grafana_data_source" {
  statement {
    sid    = "AllowQueryAmazonManagedServiceForPrometheus"
    effect = "Allow"

    actions = [
      "aps:DescribeWorkspace",
      "aps:GetLabels",
      "aps:GetMetricMetadata",
      "aps:GetSeries",
      "aps:ListWorkspaces",
      "aps:QueryMetrics"
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowReadCloudWatchMetricsAndAlarms"
    effect = "Allow"

    actions = [
      "cloudwatch:DescribeAlarmHistory",
      "cloudwatch:DescribeAlarms",
      "cloudwatch:DescribeAlarmsForMetric",
      "cloudwatch:GetMetricData",
      "cloudwatch:GetMetricStatistics",
      "cloudwatch:ListMetrics",
      "cloudwatch:ListTagsForResource"
    ]

    resources = ["*"]
  }
}

resource "aws_iam_policy" "grafana_data_source" {
  name        = local.policy_name
  description = "Grants the Amazon Managed Grafana workspace ${local.grafana_workspace_name} read access to Amazon Managed Service for Prometheus and CloudWatch metrics."
  policy      = data.aws_iam_policy_document.grafana_data_source.json

  tags = {
    Name             = local.policy_name
    GrafanaWorkspace = local.grafana_workspace_name
    ManagedBy        = "terraform"
  }
}

resource "aws_iam_role_policy_attachment" "grafana_data_source" {
  role       = aws_iam_role.grafana_data_source.name
  policy_arn = aws_iam_policy.grafana_data_source.arn
}

################################################################################
# Outputs
################################################################################

output "grafana_data_source_role_arn" {
  description = "ARN of the IAM role assumed by Amazon Managed Grafana to read Prometheus and CloudWatch metrics."
  value       = aws_iam_role.grafana_data_source.arn
}

output "grafana_data_source_policy_arn" {
  description = "ARN of the custom IAM policy attached to the Grafana data source role."
  value       = aws_iam_policy.grafana_data_source.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_cidr = "10.0.0.0/16"
  azs      = slice(data.aws_availability_zones.available.names, 0, 2)

  public_subnet_cidrs  = [cidrsubnet(local.vpc_cidr, 8, 0), cidrsubnet(local.vpc_cidr, 8, 1)]
  private_subnet_cidrs = [cidrsubnet(local.vpc_cidr, 8, 10), cidrsubnet(local.vpc_cidr, 8, 11)]

  name_prefix        = "app"
  namespace_name     = "service.local"
  container_ports    = [3000, 5432]
  standard_web_ports = [80, 443]
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${local.name_prefix}-vpc"
  }
}

resource "aws_subnet" "public" {
  count = length(local.azs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.public_subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.name_prefix}-public-${local.azs[count.index]}"
    Tier = "public"
  }
}

resource "aws_subnet" "private" {
  count = length(local.azs)

  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name = "${local.name_prefix}-private-${local.azs[count.index]}"
    Tier = "private"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${local.name_prefix}-igw"
  }
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = {
    Name = "${local.name_prefix}-nat-eip"
  }
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public[0].id

  tags = {
    Name = "${local.name_prefix}-nat"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count = length(aws_subnet.public)

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = {
    Name = "${local.name_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count = length(aws_subnet.private)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "app" {
  name        = "${local.name_prefix}-app-sg"
  description = "Security group for containerized applications"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from within the VPC CIDR only"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [local.vpc_cidr]
  }

  dynamic "ingress" {
    for_each = local.standard_web_ports
    content {
      description = "Web traffic on port ${ingress.value}"
      from_port   = ingress.value
      to_port     = ingress.value
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }

  dynamic "ingress" {
    for_each = local.container_ports
    content {
      description = "Application traffic on port ${ingress.value}"
      from_port   = ingress.value
      to_port     = ingress.value
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = {
    Name = "${local.name_prefix}-app-sg"
  }
}

resource "aws_service_discovery_private_dns_namespace" "service_local" {
  name        = local.namespace_name
  description = "Private service discovery namespace for containerized applications"
  vpc         = aws_vpc.main.id

  tags = {
    Name = local.namespace_name
  }
}

locals {
  name_prefix = "app-cognito"

  common_tags = {
    Project   = local.name_prefix
    ManagedBy = "terraform"
  }

  cognito_sync_client_actions = [
    "cognito-sync:DescribeDataset",
    "cognito-sync:DescribeIdentityUsage",
    "cognito-sync:ListDatasets",
    "cognito-sync:ListRecords",
    "cognito-sync:QueryRecords",
    "cognito-sync:RegisterDevice",
    "cognito-sync:SubscribeToDataset",
    "cognito-sync:UnsubscribeFromDataset",
    "cognito-sync:UpdateRecords",
  ]

  mobile_analytics_client_actions = [
    "mobileanalytics:PutEvents",
  ]
}

# ---------------------------------------------------------------------------
# Cognito User Pool + App Client
# ---------------------------------------------------------------------------

resource "aws_cognito_user_pool" "main" {
  name = "${local.name_prefix}-user-pool"

  username_attributes      = ["email"]
  auto_verified_attributes = ["email"]

  mfa_configuration = "OPTIONAL"

  software_token_mfa_configuration {
    enabled = true
  }

  password_policy {
    minimum_length                   = 12
    require_lowercase                = true
    require_numbers                  = true
    require_symbols                  = true
    require_uppercase                = true
    temporary_password_validity_days = 7
  }

  account_recovery_setting {
    recovery_mechanism {
      name     = "verified_email"
      priority = 1
    }
  }

  admin_create_user_config {
    allow_admin_create_user_only = false
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-user-pool"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cognito_user_pool_client" "app" {
  name         = "${local.name_prefix}-app-client"
  user_pool_id = aws_cognito_user_pool.main.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_REFRESH_TOKEN_AUTH",
  ]

  prevent_user_existence_errors = "ENABLED"
  enable_token_revocation       = true
  supported_identity_providers  = ["COGNITO"]

  access_token_validity  = 60
  id_token_validity      = 60
  refresh_token_validity = 30

  token_validity_units {
    access_token  = "minutes"
    id_token      = "minutes"
    refresh_token = "days"
  }
}

# ---------------------------------------------------------------------------
# Cognito Identity Pool (linked to the User Pool app client)
# ---------------------------------------------------------------------------

resource "aws_cognito_identity_pool" "main" {
  identity_pool_name               = "${local.name_prefix}_identity_pool"
  allow_unauthenticated_identities = false

  cognito_identity_providers {
    client_id               = aws_cognito_user_pool_client.app.id
    provider_name           = aws_cognito_user_pool.main.endpoint
    server_side_token_check = true
  }

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-identity-pool"
  })
}

# ---------------------------------------------------------------------------
# IAM role assumed by authenticated identities
# ---------------------------------------------------------------------------

data "aws_iam_policy_document" "authenticated_assume_role" {
  statement {
    sid     = "AllowCognitoAuthenticatedIdentities"
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]

    principals {
      type        = "Federated"
      identifiers = ["cognito-identity.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "cognito-identity.amazonaws.com:aud"
      values   = [aws_cognito_identity_pool.main.id]
    }

    condition {
      test     = "ForAnyValue:StringLike"
      variable = "cognito-identity.amazonaws.com:amr"
      values   = ["authenticated"]
    }
  }
}

resource "aws_iam_role" "authenticated" {
  name                 = "${local.name_prefix}-authenticated-role"
  description          = "Role assumed by authenticated Cognito identities"
  assume_role_policy   = data.aws_iam_policy_document.authenticated_assume_role.json
  max_session_duration = 3600

  tags = merge(local.common_tags, {
    Name = "${local.name_prefix}-authenticated-role"
  })
}

data "aws_iam_policy_document" "authenticated_permissions" {
  statement {
    sid       = "CognitoSyncClientAccess"
    effect    = "Allow"
    actions   = local.cognito_sync_client_actions
    resources = ["*"]
  }

  statement {
    sid       = "MobileAnalyticsEventAccess"
    effect    = "Allow"
    actions   = local.mobile_analytics_client_actions
    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "authenticated" {
  name   = "${local.name_prefix}-authenticated-policy"
  role   = aws_iam_role.authenticated.id
  policy = data.aws_iam_policy_document.authenticated_permissions.json
}

resource "aws_cognito_identity_pool_roles_attachment" "main" {
  identity_pool_id = aws_cognito_identity_pool.main.id

  roles = {
    authenticated = aws_iam_role.authenticated.arn
  }
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------

output "user_pool_id" {
  description = "ID of the Cognito User Pool"
  value       = aws_cognito_user_pool.main.id
}

output "user_pool_endpoint" {
  description = "Endpoint of the Cognito User Pool"
  value       = aws_cognito_user_pool.main.endpoint
}

output "user_pool_client_id" {
  description = "ID of the Cognito User Pool app client"
  value       = aws_cognito_user_pool_client.app.id
}

output "identity_pool_id" {
  description = "ID of the Cognito Identity Pool"
  value       = aws_cognito_identity_pool.main.id
}

output "authenticated_role_arn" {
  description = "ARN of the IAM role assumed by authenticated identities"
  value       = aws_iam_role.authenticated.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 6.0.0, < 7.0"
    }
  }
}

###############################################################################
# Versatile AWS KMS Module
#
# Supports the mutually exclusive creation modes:
#   - create                 (standard customer-managed key, AWS key material)
#   - create_external        (external key with imported base64 key material)
#   - create_replica         (multi-region replica of a primary key ARN)
#   - create_replica_external(replica external key with custom key material)
#
# Also provisions dynamically generated key policies, aliases and grants.
###############################################################################

###############################################################################
# Static / provider metadata lookups only
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

###############################################################################
# Input variables
###############################################################################

variable "create" {
  description = "Create a standard customer-managed KMS key using AWS-provided key material."
  type        = bool
  default     = true
}

variable "create_external" {
  description = "Create an external KMS key using imported base64 key material."
  type        = bool
  default     = false
}

variable "create_replica" {
  description = "Create a standard multi-region replica key referencing a primary key ARN."
  type        = bool
  default     = false
}

variable "create_replica_external" {
  description = "Create a replica external key with custom key material and a primary external key ARN."
  type        = bool
  default     = false
}

variable "description" {
  description = "Description of the KMS key."
  type        = string
  default     = "Managed by Terraform - centralized KMS encryption key"
}

variable "deletion_window_in_days" {
  description = "Number of days before the key is deleted after destruction (7-30)."
  type        = number
  default     = 30
}

variable "enable_key_rotation" {
  description = "Enable automatic annual rotation for the standard symmetric key."
  type        = bool
  default     = true
}

variable "multi_region" {
  description = "Create the standard/external key as a multi-region primary key."
  type        = bool
  default     = false
}

variable "key_usage" {
  description = "KMS key usage: ENCRYPT_DECRYPT, SIGN_VERIFY, GENERATE_VERIFY_MAC or KEY_AGREEMENT."
  type        = string
  default     = "ENCRYPT_DECRYPT"
}

variable "customer_master_key_spec" {
  description = "Key spec: SYMMETRIC_DEFAULT, RSA_2048, RSA_3072, RSA_4096, ECC_*, HMAC_*."
  type        = string
  default     = "SYMMETRIC_DEFAULT"
}

variable "key_material_base64" {
  description = "Base64-encoded 256-bit symmetric key material used for external keys."
  type        = string
  default     = null
  sensitive   = true
}

variable "primary_key_arn" {
  description = "ARN of the primary multi-region key that this replica key references."
  type        = string
  default     = null
}

variable "primary_external_key_arn" {
  description = "ARN of the primary multi-region external key that this replica external key references."
  type        = string
  default     = null
}

###############################################################################
# Policy inputs
###############################################################################

variable "policy_override" {
  description = "Full KMS key policy JSON document that overrides the generated policy."
  type        = string
  default     = null
}

variable "key_owners" {
  description = "List of IAM principal ARNs considered owners of the key (full key management)."
  type        = list(string)
  default     = []
}

variable "key_administrators" {
  description = "List of IAM principal ARNs allowed to administer the key."
  type        = list(string)
  default     = []
}

variable "key_users" {
  description = "List of IAM principal ARNs allowed to use the key for standard cryptographic operations."
  type        = list(string)
  default     = []
}

variable "service_users" {
  description = "List of AWS service principals allowed to use the key."
  type        = list(string)
  default     = []
}

variable "autoscaling_roles" {
  description = "List of IAM role ARNs for EC2 Auto Scaling that are allowed to use the key."
  type        = list(string)
  default     = []
}

variable "symmetric_crypto_users" {
  description = "List of IAM principal ARNs allowed symmetric encrypt/decrypt operations."
  type        = list(string)
  default     = []
}

variable "hmac_crypto_users" {
  description = "List of IAM principal ARNs allowed HMAC generate/verify operations."
  type        = list(string)
  default     = []
}

variable "asymmetric_public_encrypt_users" {
  description = "List of IAM principal ARNs allowed asymmetric public-key encryption operations."
  type        = list(string)
  default     = []
}

variable "asymmetric_sign_verify_users" {
  description = "List of IAM principal ARNs allowed asymmetric sign/verify operations."
  type        = list(string)
  default     = []
}

variable "enable_route53_dnssec" {
  description = "Grant the Route 53 DNSSEC signing service permission to use the key."
  type        = bool
  default     = false
}

variable "custom_policy_statements" {
  description = "Additional raw KMS key policy statements appended to the generated policy."
  type        = list(any)
  default     = []
}

###############################################################################
# Aliases and grants
###############################################################################

variable "aliases" {
  description = "List of KMS aliases. Each entry provides either 'name' or 'name_prefix'."
  type        = list(any)
  default     = []
}

variable "grants" {
  description = "List of KMS grant definitions (name, grantee_principal, operations, retiring_principal, encryption_context_equals, encryption_context_subset)."
  type        = list(any)
  default     = []
}

variable "tags" {
  description = "Tags applied to all created resources."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals: identity, action sets and dynamically generated key policy
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  region     = data.aws_region.current.region

  root_principal = "arn:${local.partition}:iam::${local.account_id}:root"

  creation_flags_count = (
    (var.create ? 1 : 0) +
    (var.create_external ? 1 : 0) +
    (var.create_replica ? 1 : 0) +
    (var.create_replica_external ? 1 : 0)
  )

  # ---- Permission action sets -------------------------------------------------

  key_management_actions = [
    "kms:Create*",
    "kms:Describe*",
    "kms:Enable*",
    "kms:List*",
    "kms:Put*",
    "kms:Update*",
    "kms:Revoke*",
    "kms:Disable*",
    "kms:Get*",
    "kms:Delete*",
    "kms:TagResource",
    "kms:UntagResource",
    "kms:ScheduleKeyDeletion",
    "kms:CancelKeyDeletion",
    "kms:ReplicateKey",
  ]

  cryptographic_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncrypt*",
    "kms:GenerateDataKey*",
    "kms:DescribeKey",
  ]

  symmetric_crypto_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncrypt*",
    "kms:GenerateDataKey*",
    "kms:GenerateDataKeyWithoutPlaintext",
    "kms:GenerateRandom",
    "kms:DescribeKey",
  ]

  hmac_crypto_actions = [
    "kms:GenerateMac",
    "kms:VerifyMac",
    "kms:DescribeKey",
  ]

  asymmetric_public_encrypt_actions = [
    "kms:Encrypt",
    "kms:GetPublicKey",
    "kms:DescribeKey",
  ]

  asymmetric_sign_verify_actions = [
    "kms:Sign",
    "kms:Verify",
    "kms:GetPublicKey",
    "kms:DescribeKey",
  ]

  autoscaling_actions = [
    "kms:Encrypt",
    "kms:Decrypt",
    "kms:ReEncrypt*",
    "kms:GenerateDataKey*",
    "kms:DescribeKey",
    "kms:CreateGrant",
    "kms:ListGrants",
    "kms:RevokeGrant",
  ]

  # ---- Dynamic policy statements ---------------------------------------------

  statement_default_root = [{
    Sid       = "DefaultRootPolicy"
    Effect    = "Allow"
    Principal = { AWS = local.root_principal }
    Action    = "kms:*"
    Resource  = "*"
  }]

  statement_key_owners = length(var.key_owners) > 0 ? [{
    Sid       = "KeyOwners"
    Effect    = "Allow"
    Principal = { AWS = var.key_owners }
    Action    = local.key_management_actions
    Resource  = "*"
  }] : []

  statement_key_administrators = length(var.key_administrators) > 0 ? [{
    Sid       = "KeyAdministrators"
    Effect    = "Allow"
    Principal = { AWS = var.key_administrators }
    Action    = local.key_management_actions
    Resource  = "*"
  }] : []

  statement_key_users = length(var.key_users) > 0 ? [{
    Sid       = "KeyUsers"
    Effect    = "Allow"
    Principal = { AWS = var.key_users }
    Action    = local.cryptographic_actions
    Resource  = "*"
  }] : []

  statement_service_users = length(var.service_users) > 0 ? [{
    Sid       = "ServiceUsers"
    Effect    = "Allow"
    Principal = { Service = var.service_users }
    Action    = local.cryptographic_actions
    Resource  = "*"
  }] : []

  statement_autoscaling = length(var.autoscaling_roles) > 0 ? [{
    Sid       = "AutoScalingRoles"
    Effect    = "Allow"
    Principal = { AWS = var.autoscaling_roles }
    Action    = local.autoscaling_actions
    Resource  = "*"
    Condition = {
      StringEquals = {
        "kms:CallerAccount" = local.account_id
        "kms:ViaService"    = "autoscaling.${local.region}.amazonaws.com"
      }
    }
  }] : []

  statement_symmetric_crypto = length(var.symmetric_crypto_users) > 0 ? [{
    Sid       = "SymmetricCryptoUsers"
    Effect    = "Allow"
    Principal = { AWS = var.symmetric_crypto_users }
    Action    = local.symmetric_crypto_actions
    Resource  = "*"
  }] : []

  statement_hmac_crypto = length(var.hmac_crypto_users) > 0 ? [{
    Sid       = "HmacCryptoUsers"
    Effect    = "Allow"
    Principal = { AWS = var.hmac_crypto_users }
    Action    = local.hmac_crypto_actions
    Resource  = "*"
  }] : []

  statement_asymmetric_public_encrypt = length(var.asymmetric_public_encrypt_users) > 0 ? [{
    Sid       = "AsymmetricPublicEncryptUsers"
    Effect    = "Allow"
    Principal = { AWS = var.asymmetric_public_encrypt_users }
    Action    = local.asymmetric_public_encrypt_actions
    Resource  = "*"
  }] : []

  statement_asymmetric_sign_verify = length(var.asymmetric_sign_verify_users) > 0 ? [{
    Sid       = "AsymmetricSignVerifyUsers"
    Effect    = "Allow"
    Principal = { AWS = var.asymmetric_sign_verify_users }
    Action    = local.asymmetric_sign_verify_actions
    Resource  = "*"
  }] : []

  statement_route53_dnssec = var.enable_route53_dnssec ? [{
    Sid       = "AllowRoute53DnssecSigning"
    Effect    = "Allow"
    Principal = { Service = "dnssec-route53.amazonaws.com" }
    Action = [
      "kms:DescribeKey",
      "kms:GetPublicKey",
      "kms:Sign",
    ]
    Resource = "*"
    Condition = {
      StringEquals = {
        "aws:SourceAccount" = local.account_id
      }
      ArnLike = {
        "aws:SourceArn" = "arn:${local.partition}:route53:::hostedzone/*"
      }
    }
  }] : []

  generated_policy_statements = concat(
    local.statement_default_root,
    local.statement_key_owners,
    local.statement_key_administrators,
    local.statement_key_users,
    local.statement_service_users,
    local.statement_autoscaling,
    local.statement_symmetric_crypto,
    local.statement_hmac_crypto,
    local.statement_asymmetric_public_encrypt,
    local.statement_asymmetric_sign_verify,
    local.statement_route53_dnssec,
    var.custom_policy_statements,
  )

  generated_policy_document = {
    Version   = "2012-10-17"
    Id        = "kms-key-policy"
    Statement = local.generated_policy_statements
  }

  key_policy = (
    var.policy_override != null && var.policy_override != ""
    ? var.policy_override
    : jsonencode(local.generated_policy_document)
  )
}

###############################################################################
# Key resources (mutually exclusive creation modes)
###############################################################################

resource "aws_kms_key" "standard" {
  count = var.create ? 1 : 0

  description              = var.description
  deletion_window_in_days  = var.deletion_window_in_days
  enable_key_rotation      = var.enable_key_rotation
  key_usage                = var.key_usage
  customer_master_key_spec = var.customer_master_key_spec
  multi_region             = var.multi_region
  policy                   = local.key_policy
  tags                     = var.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = local.creation_flags_count == 1
      error_message = "Exactly one of create, create_external, create_replica or create_replica_external must be set to true."
    }
  }
}

resource "aws_kms_external_key" "external" {
  count = var.create_external ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  enabled                 = true
  key_material_base64     = var.key_material_base64
  key_usage               = var.key_usage
  key_spec                = var.customer_master_key_spec
  multi_region            = var.multi_region
  policy                  = local.key_policy
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = local.creation_flags_count == 1
      error_message = "Exactly one of create, create_external, create_replica or create_replica_external must be set to true."
    }
  }
}

resource "aws_kms_replica_key" "replica" {
  count = var.create_replica ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  primary_key_arn         = var.primary_key_arn
  policy                  = local.key_policy
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = local.creation_flags_count == 1
      error_message = "Exactly one of create, create_external, create_replica or create_replica_external must be set to true."
    }
  }
}

resource "aws_kms_replica_external_key" "replica_external" {
  count = var.create_replica_external ? 1 : 0

  description             = var.description
  deletion_window_in_days = var.deletion_window_in_days
  primary_key_arn         = var.primary_external_key_arn
  key_material_base64     = var.key_material_base64
  enabled                 = true
  policy                  = local.key_policy
  tags                    = var.tags

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = local.creation_flags_count == 1
      error_message = "Exactly one of create, create_external, create_replica or create_replica_external must be set to true."
    }
  }
}

###############################################################################
# Resolve the active key
###############################################################################

locals {
  target_key_id = one(concat(
    aws_kms_key.standard[*].key_id,
    aws_kms_external_key.external[*].key_id,
    aws_kms_replica_key.replica[*].key_id,
    aws_kms_replica_external_key.replica_external[*].key_id,
  ))

  target_key_arn = one(concat(
    aws_kms_key.standard[*].arn,
    aws_kms_external_key.external[*].arn,
    aws_kms_replica_key.replica[*].arn,
    aws_kms_replica_external_key.replica_external[*].arn,
  ))
}

###############################################################################
# Aliases
###############################################################################

resource "aws_kms_alias" "this" {
  for_each = {
    for idx, a in var.aliases :
    (
      try(a.name, null) != null && try(a.name, null) != ""
      ? a.name
      : "${coalesce(try(a.name_prefix, null), "alias/kms")}-${idx}"
    ) => a
  }

  name          = try(each.value.name, null) != null && try(each.value.name, null) != "" ? each.value.name : null
  name_prefix   = try(each.value.name, null) == null || try(each.value.name, null) == "" ? coalesce(try(each.value.name_prefix, null), "alias/kms") : null
  target_key_id = local.target_key_id
}

###############################################################################
# Grants
###############################################################################

resource "aws_kms_grant" "this" {
  for_each = {
    for idx, g in var.grants :
    coalesce(try(g.name, null), "grant-${idx}") => g
  }

  name               = try(each.value.name, null)
  key_id             = local.target_key_id
  grantee_principal  = each.value.grantee_principal
  operations         = each.value.operations
  retiring_principal = try(each.value.retiring_principal, null)

  dynamic "constraints" {
    for_each = (
      try(each.value.encryption_context_equals, null) != null ||
      try(each.value.encryption_context_subset, null) != null
    ) ? [1] : []

    content {
      encryption_context_equals = try(each.value.encryption_context_equals, null)
      encryption_context_subset = try(each.value.encryption_context_subset, null)
    }
  }
}

###############################################################################
# Outputs
###############################################################################

output "key_id" {
  description = "ID of the created KMS key."
  value       = local.target_key_id
}

output "key_arn" {
  description = "ARN of the created KMS key."
  value       = local.target_key_arn
}

output "key_policy" {
  description = "The effective KMS key policy applied to the key."
  value       = local.key_policy
}

output "alias_names" {
  description = "Names of the created KMS aliases."
  value       = [for a in aws_kms_alias.this : a.name]
}

output "alias_arns" {
  description = "ARNs of the created KMS aliases."
  value       = [for a in aws_kms_alias.this : a.arn]
}

output "grant_ids" {
  description = "IDs of the created KMS grants."
  value       = [for g in aws_kms_grant.this : g.grant_id]
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name = "multi-cluster-k8s-networking"
  vpc_cidr = "10.0.0.0/16"

  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  # /20 private subnets derived from a prefix-length extension of 4 (netnums 0, 1, 2)
  private_subnets = [for netnum in range(3) : cidrsubnet(local.vpc_cidr, 4, netnum)]

  # /24 public subnets derived from a prefix-length extension of 8 starting at offset 48 (netnums 48, 49, 50)
  public_subnets = [for netnum in range(3) : cidrsubnet(local.vpc_cidr, 8, netnum + 48)]

  tags = {
    Blueprint  = local.vpc_name
    GithubRepo = "github.com/aws-ia/terraform-aws-eks-blueprints"
  }
}

module "vpc" {
  source  = "terraform-aws-modules/vpc/aws"
  version = "~> 5.0"

  name = local.vpc_name
  cidr = local.vpc_cidr

  azs             = local.azs
  private_subnets = local.private_subnets
  public_subnets  = local.public_subnets

  enable_nat_gateway     = true
  single_nat_gateway     = true
  one_nat_gateway_per_az = false

  enable_dns_support   = true
  enable_dns_hostnames = true

  public_subnet_tags = {
    "kubernetes.io/role/elb" = 1
  }

  private_subnet_tags = {
    "kubernetes.io/role/internal-elb" = 1
  }

  tags = local.tags
}

resource "aws_security_group" "cluster1_additional" {
  name        = "cluster1_additional_sg"
  description = "Additional security group for cluster1 allowing cross-cluster communication with cluster2"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, { Name = "cluster1_additional_sg" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "cluster2_additional" {
  name        = "cluster2_additional_sg"
  description = "Additional security group for cluster2 allowing cross-cluster communication with cluster1"
  vpc_id      = module.vpc.vpc_id

  tags = merge(local.tags, { Name = "cluster2_additional_sg" })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_ingress_rule" "cluster1_from_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional.id
  description                  = "Allow all protocols from cluster2 additional security group"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.cluster2_additional.id

  tags = local.tags
}

resource "aws_vpc_security_group_egress_rule" "cluster1_to_cluster2" {
  security_group_id            = aws_security_group.cluster1_additional.id
  description                  = "Allow all protocols to cluster2 additional security group"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.cluster2_additional.id

  tags = local.tags
}

resource "aws_vpc_security_group_ingress_rule" "cluster2_from_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional.id
  description                  = "Allow all protocols from cluster1 additional security group"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.cluster1_additional.id

  tags = local.tags
}

resource "aws_vpc_security_group_egress_rule" "cluster2_to_cluster1" {
  security_group_id            = aws_security_group.cluster2_additional.id
  description                  = "Allow all protocols to cluster1 additional security group"
  ip_protocol                  = "-1"
  referenced_security_group_id = aws_security_group.cluster1_additional.id

  tags = local.tags
}

###############################################################################
# Terraform & Provider Requirements
###############################################################################

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  # Well-known CloudFront hosted zone ID used for Cognito custom domain aliases.
  cloudfront_hosted_zone_id = "Z2FDTNDATAQYW2"

  # Normalize the client list into a map keyed by client name for stable for_each.
  clients = { for client in var.clients : client.name => client }
}

###############################################################################
# Variables
###############################################################################

variable "pool_name" {
  description = "Name of the Cognito User Pool."
  type        = string
  default     = "Pool name"
}

variable "alias_attributes" {
  description = "Attributes supported as an alias for the user pool (email, phone_number, preferred_username)."
  type        = list(string)
  default     = ["email", "phone_number"]
}

variable "auto_verified_attributes" {
  description = "Attributes to be auto-verified (email, phone_number)."
  type        = list(string)
  default     = []
}

variable "email_verification_message" {
  description = "Verification message for the email attribute."
  type        = string
  default     = "Some message {####}"
}

variable "email_verification_subject" {
  description = "Verification subject for the email attribute."
  type        = string
  default     = "Some subject"
}

variable "mfa_configuration" {
  description = "Multi-factor authentication configuration: OFF, ON or OPTIONAL."
  type        = string
  default     = "OPTIONAL"

  validation {
    condition     = contains(["OFF", "ON", "OPTIONAL"], var.mfa_configuration)
    error_message = "mfa_configuration must be one of OFF, ON or OPTIONAL."
  }
}

variable "sms_authentication_message" {
  description = "SMS authentication message."
  type        = string
  default     = "SMS authentication message {####}"
}

variable "sms_verification_message" {
  description = "SMS verification message."
  type        = string
  default     = "SMS verification message {####}"
}

variable "verification_message_template" {
  description = "Verification message template, including the by-link variants."
  type = object({
    default_email_option  = optional(string, "CONFIRM_WITH_CODE")
    email_message_by_link = optional(string, "Please click the link {##Verify Email##} to verify your email address.")
    email_subject_by_link = optional(string, "Verify your email address")
  })
  default = {}

  validation {
    condition     = contains(["CONFIRM_WITH_CODE", "CONFIRM_WITH_LINK"], var.verification_message_template.default_email_option)
    error_message = "default_email_option must be one of CONFIRM_WITH_CODE or CONFIRM_WITH_LINK."
  }
}

variable "sms_configuration" {
  description = "SMS configuration for the user pool. The block is created only when both external_id and sns_caller_arn are non-empty."
  type = object({
    external_id    = string
    sns_caller_arn = string
  })
  default = {
    external_id    = ""
    sns_caller_arn = ""
  }
}

variable "account_recovery_mechanisms" {
  description = "List of account recovery mechanisms."
  type = list(object({
    name     = string
    priority = number
  }))
  default = [
    {
      name     = "verified_email"
      priority = 2
    },
    {
      name     = "verified_phone_number"
      priority = 1
    }
  ]
}

variable "invite_message_template" {
  description = "Invite message templates sent when an administrator creates a user."
  type = object({
    email_message = optional(string, "Your username is {username} and temporary password is {####}.")
    email_subject = optional(string, "Your temporary password")
    sms_message   = optional(string, "Your username is {username} and temporary password is {####}.")
  })
  default = {}
}

variable "admin_create_user_only" {
  description = "Set to true to allow only administrators to create users."
  type        = bool
  default     = false
}

variable "software_token_mfa_enabled" {
  description = "Whether software token (TOTP) MFA is enabled."
  type        = bool
  default     = true
}

variable "case_sensitive" {
  description = "Whether usernames are case sensitive. Set to null to leave unconfigured."
  type        = bool
  default     = null
}

variable "device_configuration" {
  description = "Device (remembered device) configuration. Set to null to leave unconfigured."
  type = object({
    challenge_required_on_new_device      = optional(bool, false)
    device_only_remembered_on_user_prompt = optional(bool, true)
  })
  default = null
}

variable "lambda_config" {
  description = "Map of Lambda trigger name to Lambda function ARN."
  type        = map(string)
  default     = {}
}

variable "custom_email_sender" {
  description = "Custom email sender Lambda configuration."
  type = object({
    lambda_arn     = string
    lambda_version = optional(string, "V1_0")
  })
  default = null
}

variable "schema" {
  description = "List of schema attributes for the user pool."
  type = list(object({
    attribute_data_type      = string
    developer_only_attribute = optional(bool, false)
    mutable                  = optional(bool, true)
    name                     = string
    required                 = optional(bool, false)
    string_attribute_constraints = optional(object({
      min_length = number
      max_length = number
    }))
    number_attribute_constraints = optional(object({
      min_value = number
      max_value = number
    }))
  }))
  default = [
    {
      attribute_data_type      = "String"
      developer_only_attribute = false
      mutable                  = true
      name                     = "email"
      required                 = true
      string_attribute_constraints = {
        min_length = 0
        max_length = 2048
      }
    }
  ]
}

variable "clients" {
  description = "List of Cognito User Pool Clients (client apps) to create."
  type = list(object({
    name                           = string
    generate_secret                = optional(bool, false)
    access_token_validity          = optional(number, 120)
    id_token_validity              = optional(number, 120)
    refresh_token_validity         = optional(number, 7)
    token_validity_units = optional(object({
      access_token  = optional(string, "minutes")
      id_token      = optional(string, "minutes")
      refresh_token = optional(string, "days")
    }), {})
    allowed_oauth_user_pool_client = optional(bool, false)
    enable_token_revocation        = optional(bool, true)
    explicit_auth_flows            = optional(list(string), ["ALLOW_REFRESH_TOKEN_AUTH", "ALLOW_USER_PASSWORD_AUTH", "ALLOW_USER_SRP_AUTH"])
    prevent_user_existence_errors  = optional(string, "LEGACY")
    read_attributes                = optional(list(string), [])
    write_attributes               = optional(list(string), [])
    callback_urls                  = optional(list(string), [])
    logout_urls                    = optional(list(string), [])
    allowed_oauth_flows            = optional(list(string), [])
    allowed_oauth_scopes           = optional(list(string), [])
    supported_identity_providers   = optional(list(string), [])
  }))
  default = []

  validation {
    condition     = length(distinct([for c in var.clients : c.name])) == length(var.clients)
    error_message = "Each Cognito User Pool Client must have a unique name."
  }
}

variable "group_name" {
  description = "Name of the Cognito User Group. When empty no group is created."
  type        = string
  default     = ""
}

variable "group_precedence" {
  description = "Precedence of the Cognito User Group."
  type        = number
  default     = 0
}

variable "group_role_arn" {
  description = "ARN of the IAM role to associate with the Cognito User Group."
  type        = string
  default     = ""
}

variable "group_description" {
  description = "Description of the Cognito User Group."
  type        = string
  default     = ""
}

variable "domain" {
  description = "Cognito User Pool custom domain. When empty no domain is created."
  type        = string
  default     = ""
}

variable "certificate_arn" {
  description = "ACM certificate ARN for the Cognito custom domain."
  type        = string
  default     = ""
}

variable "create_route53_record" {
  description = "Whether to create a Route 53 alias record for the custom domain."
  type        = bool
  default     = false
}

variable "route53_zone_id" {
  description = "Route 53 hosted zone ID for the alias record."
  type        = string
  default     = ""
}

variable "route53_record_name" {
  description = "Record name for the Route 53 alias record. Defaults to the custom domain."
  type        = string
  default     = ""
}

###############################################################################
# Cognito User Pool
###############################################################################

resource "aws_cognito_user_pool" "pool" {
  name = var.pool_name

  alias_attributes         = length(var.alias_attributes) > 0 ? var.alias_attributes : null
  auto_verified_attributes = length(var.auto_verified_attributes) > 0 ? var.auto_verified_attributes : null

  mfa_configuration = var.mfa_configuration

  sms_authentication_message = var.sms_authentication_message

  # ---------------------------------------------------------------------------
  # Admin create user configuration
  # ---------------------------------------------------------------------------
  admin_create_user_config {
    allow_admin_create_user_only = var.admin_create_user_only

    invite_message_template {
      email_message = var.invite_message_template.email_message
      email_subject = var.invite_message_template.email_subject
      sms_message   = var.invite_message_template.sms_message
    }
  }

  # ---------------------------------------------------------------------------
  # Account recovery
  # ---------------------------------------------------------------------------
  dynamic "account_recovery_setting" {
    for_each = length(var.account_recovery_mechanisms) > 0 ? [1] : []

    content {
      dynamic "recovery_mechanism" {
        for_each = var.account_recovery_mechanisms

        content {
          name     = recovery_mechanism.value.name
          priority = recovery_mechanism.value.priority
        }
      }
    }
  }

  # ---------------------------------------------------------------------------
  # Verification message template (including by-link variants).
  # NOTE: sms_verification_message (top-level) conflicts with this block's
  # sms_message, so the SMS verification message is applied ONLY here.
  # ---------------------------------------------------------------------------
  verification_message_template {
    default_email_option  = var.verification_message_template.default_email_option
    email_message         = var.email_verification_message
    email_subject         = var.email_verification_subject
    email_message_by_link = var.verification_message_template.email_message_by_link
    email_subject_by_link = var.verification_message_template.email_subject_by_link
    sms_message           = var.sms_verification_message
  }

  # ---------------------------------------------------------------------------
  # SMS configuration (only when both external ID and SNS caller ARN are set)
  # ---------------------------------------------------------------------------
  dynamic "sms_configuration" {
    for_each = (
      var.sms_configuration.external_id != "" &&
      var.sms_configuration.sns_caller_arn != ""
    ) ? [var.sms_configuration] : []

    content {
      external_id    = sms_configuration.value.external_id
      sns_caller_arn = sms_configuration.value.sns_caller_arn
    }
  }

  # ---------------------------------------------------------------------------
  # Username case sensitivity (only when explicitly configured)
  # ---------------------------------------------------------------------------
  dynamic "username_configuration" {
    for_each = var.case_sensitive != null ? [var.case_sensitive] : []

    content {
      case_sensitive = username_configuration.value
    }
  }

  # ---------------------------------------------------------------------------
  # Device configuration (only when explicitly configured)
  # ---------------------------------------------------------------------------
  dynamic "device_configuration" {
    for_each = var.device_configuration != null ? [var.device_configuration] : []

    content {
      challenge_required_on_new_device      = device_configuration.value.challenge_required_on_new_device
      device_only_remembered_on_user_prompt = device_configuration.value.device_only_remembered_on_user_prompt
    }
  }

  # ---------------------------------------------------------------------------
  # Software token (TOTP) MFA
  # ---------------------------------------------------------------------------
  dynamic "software_token_mfa_configuration" {
    for_each = var.software_token_mfa_enabled != null ? [var.software_token_mfa_enabled] : []

    content {
      enabled = software_token_mfa_configuration.value
    }
  }

  # ---------------------------------------------------------------------------
  # Lambda triggers (generic triggers + custom email sender)
  # ---------------------------------------------------------------------------
  dynamic "lambda_config" {
    for_each = (length(var.lambda_config) > 0 || var.custom_email_sender != null) ? [1] : []

    content {
      create_auth_challenge          = lookup(var.lambda_config, "create_auth_challenge", null)
      custom_message                 = lookup(var.lambda_config, "custom_message", null)
      define_auth_challenge          = lookup(var.lambda_config, "define_auth_challenge", null)
      post_authentication            = lookup(var.lambda_config, "post_authentication", null)
      post_confirmation              = lookup(var.lambda_config, "post_confirmation", null)
      pre_authentication             = lookup(var.lambda_config, "pre_authentication", null)
      pre_sign_up                    = lookup(var.lambda_config, "pre_sign_up", null)
      pre_token_generation           = lookup(var.lambda_config, "pre_token_generation", null)
      user_migration                 = lookup(var.lambda_config, "user_migration", null)
      verify_auth_challenge_response = lookup(var.lambda_config, "verify_auth_challenge_response", null)
      kms_key_id                     = lookup(var.lambda_config, "kms_key_id", null)

      dynamic "custom_email_sender" {
        for_each = var.custom_email_sender != null ? [var.custom_email_sender] : []

        content {
          lambda_arn     = custom_email_sender.value.lambda_arn
          lambda_version = custom_email_sender.value.lambda_version
        }
      }
    }
  }

  # ---------------------------------------------------------------------------
  # Custom schema attributes (with or without min/max constraints)
  # ---------------------------------------------------------------------------
  dynamic "schema" {
    for_each = var.schema
    iterator = attribute

    content {
      attribute_data_type      = attribute.value.attribute_data_type
      developer_only_attribute = attribute.value.developer_only_attribute
      mutable                  = attribute.value.mutable
      name                     = attribute.value.name
      required                 = attribute.value.required

      dynamic "string_attribute_constraints" {
        for_each = attribute.value.string_attribute_constraints != null ? [attribute.value.string_attribute_constraints] : []

        content {
          min_length = string_attribute_constraints.value.min_length
          max_length = string_attribute_constraints.value.max_length
        }
      }

      dynamic "number_attribute_constraints" {
        for_each = attribute.value.number_attribute_constraints != null ? [attribute.value.number_attribute_constraints] : []

        content {
          min_value = number_attribute_constraints.value.min_value
          max_value = number_attribute_constraints.value.max_value
        }
      }
    }
  }

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Cognito User Pool Clients
###############################################################################

resource "aws_cognito_user_pool_client" "client" {
  for_each = local.clients

  name         = each.value.name
  user_pool_id = aws_cognito_user_pool.pool.id

  generate_secret = each.value.generate_secret

  access_token_validity  = each.value.access_token_validity
  id_token_validity      = each.value.id_token_validity
  refresh_token_validity = each.value.refresh_token_validity

  token_validity_units {
    access_token  = coalesce(try(each.value.token_validity_units.access_token, null), "minutes")
    id_token      = coalesce(try(each.value.token_validity_units.id_token, null), "minutes")
    refresh_token = coalesce(try(each.value.token_validity_units.refresh_token, null), "days")
  }

  allowed_oauth_flows_user_pool_client = each.value.allowed_oauth_user_pool_client
  enable_token_revocation              = each.value.enable_token_revocation
  explicit_auth_flows                  = each.value.explicit_auth_flows
  prevent_user_existence_errors        = each.value.prevent_user_existence_errors

  read_attributes      = length(each.value.read_attributes) > 0 ? each.value.read_attributes : null
  write_attributes     = length(each.value.write_attributes) > 0 ? each.value.write_attributes : null
  callback_urls        = length(each.value.callback_urls) > 0 ? each.value.callback_urls : null
  logout_urls          = length(each.value.logout_urls) > 0 ? each.value.logout_urls : null
  allowed_oauth_flows  = length(each.value.allowed_oauth_flows) > 0 ? each.value.allowed_oauth_flows : null
  allowed_oauth_scopes = length(each.value.allowed_oauth_scopes) > 0 ? each.value.allowed_oauth_scopes : null

  supported_identity_providers = length(each.value.supported_identity_providers) > 0 ? each.value.supported_identity_providers : null
}

###############################################################################
# Cognito User Group (conditional)
###############################################################################

resource "aws_cognito_user_group" "group" {
  count = var.group_name != "" ? 1 : 0

  name         = var.group_name
  user_pool_id = aws_cognito_user_pool.pool.id
  precedence   = var.group_precedence
  role_arn     = var.group_role_arn != "" ? var.group_role_arn : null
  description  = var.group_description != "" ? var.group_description : null
}

###############################################################################
# Cognito User Pool Domain (conditional)
###############################################################################

resource "aws_cognito_user_pool_domain" "domain" {
  count = var.domain != "" ? 1 : 0

  domain          = var.domain
  user_pool_id    = aws_cognito_user_pool.pool.id
  certificate_arn = var.certificate_arn != "" ? var.certificate_arn : null
}

###############################################################################
# Route 53 alias record pointing at the Cognito CloudFront distribution
###############################################################################

resource "aws_route53_record" "cognito" {
  count = (
    var.create_route53_record &&
    var.route53_zone_id != "" &&
    var.domain != ""
  ) ? 1 : 0

  zone_id = var.route53_zone_id
  name    = var.route53_record_name != "" ? var.route53_record_name : var.domain
  type    = "A"

  alias {
    name                   = aws_cognito_user_pool_domain.domain[0].cloudfront_distribution_arn
    zone_id                = local.cloudfront_hosted_zone_id
    evaluate_target_health = false
  }
}

###############################################################################
# Outputs
###############################################################################

output "user_pool_id" {
  description = "ID of the Cognito User Pool."
  value       = aws_cognito_user_pool.pool.id
}

output "user_pool_arn" {
  description = "ARN of the Cognito User Pool."
  value       = aws_cognito_user_pool.pool.arn
}

output "user_pool_endpoint" {
  description = "Endpoint of the Cognito User Pool."
  value       = aws_cognito_user_pool.pool.endpoint
}

output "user_pool_client_ids" {
  description = "Map of client name to Cognito User Pool Client ID."
  value       = { for name, client in aws_cognito_user_pool_client.client : name => client.id }
}

output "user_pool_client_secrets" {
  description = "Map of client name to Cognito User Pool Client secret."
  value       = { for name, client in aws_cognito_user_pool_client.client : name => client.client_secret }
  sensitive   = true
}

output "user_pool_domain" {
  description = "Cognito User Pool custom domain (if created)."
  value       = try(aws_cognito_user_pool_domain.domain[0].domain, null)
}

output "user_pool_domain_cloudfront_distribution_arn" {
  description = "CloudFront distribution ARN backing the Cognito custom domain (if created)."
  value       = try(aws_cognito_user_pool_domain.domain[0].cloudfront_distribution_arn, null)
}

output "user_group_name" {
  description = "Name of the Cognito User Group (if created)."
  value       = try(aws_cognito_user_group.group[0].name, null)
}

output "route53_record_fqdn" {
  description = "FQDN of the Route 53 alias record (if created)."
  value       = try(aws_route53_record.cognito[0].fqdn, null)
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC"
  type        = string
  default     = "10.0.0.0/16"
}

variable "vpc_name" {
  description = "Name tag for the VPC"
  type        = string
  default     = "DevOps-Project-VPC"
}

variable "igw_name" {
  description = "Name tag for the Internet Gateway"
  type        = string
  default     = "devops-project-igw"
}

variable "route_table_name" {
  description = "Name tag for the public route table"
  type        = string
  default     = "DevOps-project-RT"
}

variable "public_subnet_id_name" {
  description = "Identifier name associated with the public subnet"
  type        = string
  default     = "subnet_a"
}

variable "nat_gw_name" {
  description = "Name tag for the NAT Gateway"
  type        = string
  default     = "DevOps-NAT-GW"
}

variable "public_ipv4_pool" {
  description = "Public IPv4 pool from which the Elastic IP is drawn"
  type        = string
  default     = "amazon"
}

variable "subnet_a_cidr" {
  description = "CIDR block for Subnet A (public)"
  type        = string
  default     = "10.0.1.0/24"
}

variable "subnet_a_az_index" {
  description = "Index of the availability zone for Subnet A"
  type        = number
  default     = 0
}

variable "subnet_a_map_public_ip" {
  description = "Assign public IP on launch for Subnet A"
  type        = bool
  default     = false
}

variable "subnet_a_name" {
  description = "Name tag for Subnet A"
  type        = string
  default     = "Subnet-A-Public"
}

variable "subnet_b_cidr" {
  description = "CIDR block for Subnet B (private)"
  type        = string
  default     = "10.0.2.0/24"
}

variable "subnet_b_az_index" {
  description = "Index of the availability zone for Subnet B"
  type        = number
  default     = 1
}

variable "subnet_b_map_public_ip" {
  description = "Assign public IP on launch for Subnet B"
  type        = bool
  default     = false
}

variable "subnet_b_name" {
  description = "Name tag for Subnet B"
  type        = string
  default     = "Subnet-B-Private"
}

variable "subnet_c_cidr" {
  description = "CIDR block for Subnet C (private)"
  type        = string
  default     = "10.0.3.0/24"
}

variable "subnet_c_az_index" {
  description = "Index of the availability zone for Subnet C"
  type        = number
  default     = 2
}

variable "subnet_c_map_public_ip" {
  description = "Assign public IP on launch for Subnet C"
  type        = bool
  default     = false
}

variable "subnet_c_name" {
  description = "Name tag for Subnet C"
  type        = string
  default     = "Subnet-C-Private"
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs               = data.aws_availability_zones.available.names
  subnet_a_az       = local.azs[var.subnet_a_az_index]
  subnet_b_az       = local.azs[var.subnet_b_az_index]
  subnet_c_az       = local.azs[var.subnet_c_az_index]
  security_group_name = "DefaultSecurityGroup"
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.igw_name
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_a_cidr
  availability_zone       = local.subnet_a_az
  map_public_ip_on_launch = var.subnet_a_map_public_ip

  tags = {
    Name = var.subnet_a_name
    Type = var.public_subnet_id_name
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_b_cidr
  availability_zone       = local.subnet_b_az
  map_public_ip_on_launch = var.subnet_b_map_public_ip

  tags = {
    Name = var.subnet_b_name
    Type = "private"
  }
}

resource "aws_subnet" "subnet_c" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_c_cidr
  availability_zone       = local.subnet_c_az
  map_public_ip_on_launch = var.subnet_c_map_public_ip

  tags = {
    Name = var.subnet_c_name
    Type = "private"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = var.route_table_name
  }
}

resource "aws_route" "internet_access" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "subnet_a" {
  subnet_id      = aws_subnet.subnet_a.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain   = "vpc"
  public_ipv4_pool = var.public_ipv4_pool

  tags = {
    Name = "${var.nat_gw_name}-eip"
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.subnet_b.id

  tags = {
    Name = var.nat_gw_name
  }

  depends_on = [aws_internet_gateway.main]
}

resource "aws_security_group" "default" {
  name        = local.security_group_name
  description = "Default security group permitting outbound egress within the VPC CIDR only"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = local.security_group_name
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_vpc_security_group_egress_rule" "vpc_cidr" {
  security_group_id = aws_security_group.default.id
  cidr_ipv4         = var.vpc_cidr
  ip_protocol       = "-1"

  description = "Allow outbound egress within the VPC CIDR"
}

output "nat_gateway_public_ip" {
  description = "Public IP address of the NAT Gateway Elastic IP"
  value       = aws_eip.nat.public_ip
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "create" {
  description = "Controls whether a new Transit Gateway is created. When false, an existing Transit Gateway is looked up using `id` or the `tag:Name` filter derived from `name`."
  type        = bool
  default     = true
}

variable "id" {
  description = "ID of an existing Transit Gateway to use when `create` is false. When null, the Transit Gateway is looked up using a `tag:Name` filter."
  type        = string
  default     = null
}

variable "name" {
  description = "Name of the Transit Gateway. Used as the `tag:Name` lookup filter when `create` is false and as the default Name tag for every resource created by this configuration."
  type        = string
  default     = null
}

variable "amazon_side_asn" {
  description = "Private Autonomous System Number (ASN) for the Amazon side of a BGP session."
  type        = number
  default     = 65200

  validation {
    condition = (
      (var.amazon_side_asn >= 64512 && var.amazon_side_asn <= 65534) ||
      (var.amazon_side_asn >= 4200000000 && var.amazon_side_asn <= 4294967294)
    )
    error_message = "amazon_side_asn must be a private 16-bit ASN (64512-65534) or a private 32-bit ASN (4200000000-4294967294)."
  }
}

variable "auto_accept_shared_attachments" {
  description = "Whether to automatically accept cross-account VPC attachments that are shared with this Transit Gateway through AWS RAM."
  type        = string
  default     = "disable"

  validation {
    condition     = contains(["enable", "disable"], var.auto_accept_shared_attachments)
    error_message = "auto_accept_shared_attachments must be either \"enable\" or \"disable\"."
  }
}

variable "dns_support" {
  description = "Whether DNS support is enabled on the Transit Gateway."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.dns_support)
    error_message = "dns_support must be either \"enable\" or \"disable\"."
  }
}

variable "vpn_ecmp_support" {
  description = "Whether Equal Cost Multipath (ECMP) support is enabled for VPN attachments on the Transit Gateway."
  type        = string
  default     = "enable"

  validation {
    condition     = contains(["enable", "disable"], var.vpn_ecmp_support)
    error_message = "vpn_ecmp_support must be either \"enable\" or \"disable\"."
  }
}

variable "transit_gateway_cidr_blocks" {
  description = "One or more IPv4 or IPv6 CIDR blocks used to create a Connect attachment for appliance mode."
  type        = list(string)
  default     = []

  validation {
    condition = alltrue([
      for cidr in var.transit_gateway_cidr_blocks : can(cidrhost(cidr, 0))
    ])
    error_message = "Every entry of transit_gateway_cidr_blocks must be a valid IPv4 or IPv6 CIDR block."
  }
}

variable "route_tables" {
  description = <<-EOT
    Map of Transit Gateway route tables to create or to look up. The map key is the
    logical name of the route table. Each entry supports:
      - name:   Optional name; falls back to `name` and then to the map key.
      - create: Whether to create the route table (true) or look it up (false).
      - tags:   Route table specific tags merged on top of the global tags.
  EOT
  type = map(object({
    name   = optional(string, null)
    create = optional(bool, true)
    tags   = optional(map(string), {})
  }))
  default = {}
}

variable "shared_principals" {
  description = "Map of principals (AWS account IDs, organizational unit ARNs, or organization ARNs) to associate with the AWS RAM resource share that shares the Transit Gateway. Keys are arbitrary identifiers, values are the principals."
  type        = map(string)
  default     = {}
}

variable "ram_resource_share_name" {
  description = "Name of the AWS RAM resource share used to share the Transit Gateway. Defaults to `name` when null."
  type        = string
  default     = null
}

variable "tags" {
  description = "Global tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  transit_gateway_id  = var.create ? aws_ec2_transit_gateway.this[0].id : data.aws_ec2_transit_gateway.this[0].id
  transit_gateway_arn = var.create ? aws_ec2_transit_gateway.this[0].arn : data.aws_ec2_transit_gateway.this[0].arn

  transit_gateway_name = coalesce(var.name, "transit-gateway")

  # Resolved Name for every route table: explicit name -> main resource name -> map key.
  route_table_names = {
    for table_name, table in var.route_tables : table_name => coalesce(try(table.name, null), var.name, table_name)
  }

  route_tables_to_create = {
    for table_name, table in var.route_tables : table_name => table if try(table.create, true)
  }

  route_tables_to_lookup = {
    for table_name, table in var.route_tables : table_name => table if !try(table.create, true)
  }

  create_ram_share = length(var.shared_principals) > 0

  ram_resource_share_name = coalesce(var.ram_resource_share_name, var.name, "transit-gateway-share")

  route_table_ids = merge(
    { for table_name, table in aws_ec2_transit_gateway_route_table.this : table_name => table.id },
    { for table_name, table in data.aws_ec2_transit_gateway_route_table.this : table_name => table.id },
  )
}

###############################################################################
# Existing Transit Gateway lookup (create = false)
###############################################################################

data "aws_ec2_transit_gateway" "this" {
  count = var.create ? 0 : 1

  id = var.id

  dynamic "filter" {
    for_each = var.id == null && var.name != null ? [1] : []
    content {
      name   = "tag:Name"
      values = [var.name]
    }
  }

  lifecycle {
    precondition {
      condition     = var.id != null || var.name != null
      error_message = "When create is false you must supply either `id` or `name` so an existing Transit Gateway can be located."
    }
  }
}

###############################################################################
# Transit Gateway
###############################################################################

resource "aws_ec2_transit_gateway" "this" {
  count = var.create ? 1 : 0

  amazon_side_asn                 = var.amazon_side_asn
  auto_accept_shared_attachments  = var.auto_accept_shared_attachments
  default_route_table_association = "disable"
  default_route_table_propagation = "disable"
  dns_support                     = var.dns_support
  vpn_ecmp_support                = var.vpn_ecmp_support
  transit_gateway_cidr_blocks     = var.transit_gateway_cidr_blocks

  tags = merge(var.tags, { Name = local.transit_gateway_name })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Transit Gateway route tables
###############################################################################

resource "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.route_tables_to_create

  transit_gateway_id = local.transit_gateway_id

  tags = merge(
    var.tags,
    try(each.value.tags, {}),
    { Name = local.route_table_names[each.key] }
  )
}

data "aws_ec2_transit_gateway_route_table" "this" {
  for_each = local.route_tables_to_lookup

  filter {
    name   = "transit-gateway-id"
    values = [local.transit_gateway_id]
  }

  filter {
    name   = "tag:Name"
    values = [local.route_table_names[each.key]]
  }
}

###############################################################################
# Cross-account sharing through AWS RAM
###############################################################################

resource "aws_ram_resource_share" "this" {
  count = local.create_ram_share ? 1 : 0

  name                      = local.ram_resource_share_name
  allow_external_principals = true

  tags = merge(var.tags, { Name = local.ram_resource_share_name })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ram_resource_association" "this" {
  count = local.create_ram_share ? 1 : 0

  resource_arn       = local.transit_gateway_arn
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

resource "aws_ram_principal_association" "this" {
  for_each = var.shared_principals

  principal          = each.value
  resource_share_arn = aws_ram_resource_share.this[0].arn
}

###############################################################################
# Outputs
###############################################################################

output "transit_gateway_id" {
  description = "ID of the Transit Gateway that was created or looked up."
  value       = local.transit_gateway_id
}

output "transit_gateway_arn" {
  description = "ARN of the Transit Gateway that was created or looked up."
  value       = local.transit_gateway_arn
}

output "transit_gateway_name" {
  description = "Resolved Name of the Transit Gateway."
  value       = local.transit_gateway_name
}

output "transit_gateway_route_table_ids" {
  description = "Map of logical route table name to Transit Gateway route table ID (created and looked up)."
  value       = local.route_table_ids
}

output "ram_resource_share_arn" {
  description = "ARN of the AWS RAM resource share that shares the Transit Gateway, if one was created."
  value       = try(aws_ram_resource_share.this[0].arn, null)
}

output "ram_resource_share_id" {
  description = "ID of the AWS RAM resource share that shares the Transit Gateway, if one was created."
  value       = try(aws_ram_resource_share.this[0].id, null)
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5"
    }
  }
}

# ----------------------------------------------------------------------------
# Input variables
# ----------------------------------------------------------------------------

variable "bucket_name" {
  description = "Name of the S3 bucket. If null, defaults to 'corebucket-' plus a 4-byte random hex string."
  type        = string
  default     = null
}

variable "prefix" {
  description = "When true, appends an additional random string suffix to the resolved bucket name."
  type        = bool
  default     = false
}

variable "request_payer" {
  description = "Specifies who should bear the cost of Amazon S3 data transfer (BucketOwner or Requester)."
  type        = string
  default     = "BucketOwner"

  validation {
    condition     = contains(["BucketOwner", "Requester"], var.request_payer)
    error_message = "request_payer must be either 'BucketOwner' or 'Requester'."
  }
}

variable "encryption" {
  description = "Enable server-side encryption for the bucket. Encryption always uses the aws:kms algorithm."
  type        = bool
  default     = true
}

variable "kms_key" {
  description = "ARN of an externally managed KMS key. When empty, the module creates its own rotating customer-managed KMS key."
  type        = string
  default     = ""
}

variable "versioning" {
  description = "Enable bucket versioning."
  type        = bool
  default     = false
}

variable "mfa_delete" {
  description = "Enable MFA delete on the bucket. Requires versioning to be enabled."
  type        = bool
  default     = false
}

variable "force_destroy" {
  description = "Allow the bucket to be destroyed even when it contains objects."
  type        = bool
  default     = false
}

variable "tags" {
  description = "Map of tags applied to all resources created by the module."
  type        = map(string)
  default     = {}
}

variable "acl" {
  description = "Canned ACL to apply to the bucket. Set to null to leave unset."
  type        = string
  default     = null
}

variable "grants" {
  description = "List of fine-grained ACL grants applied through an access control policy."
  type = list(object({
    id         = optional(string)
    type       = string
    uri        = optional(string)
    permission = string
  }))
  default = []
}

variable "policy" {
  description = "JSON policy document to attach to the bucket."
  type        = string
  default     = null
}

variable "acceleration_status" {
  description = "Transfer acceleration status ('Enabled', 'Suspended' or null to leave unset)."
  type        = string
  default     = null

  validation {
    condition     = var.acceleration_status == null ? true : contains(["Enabled", "Suspended"], var.acceleration_status)
    error_message = "acceleration_status must be 'Enabled', 'Suspended' or null."
  }
}

variable "logging" {
  description = "Access logging configuration for the bucket."
  type = object({
    target_bucket = string
    target_prefix = optional(string, "")
  })
  default = null
}

variable "website" {
  description = "Static website hosting configuration for the bucket."
  type = object({
    index_document           = optional(string)
    error_document           = optional(string)
    redirect_all_requests_to = optional(string)
  })
  default = null
}

variable "cors_rule" {
  description = "List of CORS rules applied to the bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "lifecycle_rule" {
  description = "List of lifecycle rules applied to the bucket."
  type = list(object({
    id                                     = optional(string)
    enabled                                = optional(bool, true)
    prefix                                 = optional(string)
    tags                                   = optional(map(string))
    abort_incomplete_multipart_upload_days = optional(number)
    expiration = optional(object({
      days                         = optional(number)
      date                         = optional(string)
      expired_object_delete_marker = optional(bool)
    }))
    noncurrent_version_expiration = optional(object({
      days                      = optional(number)
      newer_noncurrent_versions = optional(number)
    }))
    noncurrent_version_transition = optional(list(object({
      days                      = optional(number)
      storage_class             = string
      newer_noncurrent_versions = optional(number)
    })), [])
    transition = optional(list(object({
      days          = optional(number)
      date          = optional(string)
      storage_class = string
    })), [])
  }))
  default = []
}

variable "object_lock_configuration" {
  description = "Object lock configuration for the bucket."
  type = object({
    mode  = string
    days  = optional(number)
    years = optional(number)
  })
  default = null

  validation {
    condition     = var.object_lock_configuration == null ? true : contains(["COMPLIANCE", "GOVERNANCE"], var.object_lock_configuration.mode)
    error_message = "object_lock_configuration.mode must be 'COMPLIANCE' or 'GOVERNANCE'."
  }
}

variable "replication_role" {
  description = "ARN of an externally managed IAM role used for replication. When null, the module creates a dedicated role."
  type        = string
  default     = null
}

variable "replication_rules" {
  description = "List of cross-region replication rules. When supplied, replication is configured on the bucket."
  type = list(object({
    id                               = optional(string)
    status                           = optional(string, "Enabled")
    priority                         = optional(number)
    delete_marker_replication_status = optional(string)
    filter = optional(object({
      prefix = optional(string)
      tags   = optional(map(string))
    }))
    destination = object({
      bucket             = string
      storage_class      = optional(string)
      replica_kms_key_id = optional(string)
      account_id         = optional(string)
      access_control_translation = optional(object({
        owner = string
      }))
      metrics = optional(object({
        status          = optional(string, "Enabled")
        event_threshold = optional(object({
          minutes = optional(number)
        }))
      }))
      replication_time = optional(object({
        status = optional(string, "Enabled")
        time = optional(object({
          minutes = optional(number)
        }))
      }))
    })
    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects = optional(object({
        status = string
      }))
    }))
  }))
  default = []
}

# ----------------------------------------------------------------------------
# Data sources and random name generation
# ----------------------------------------------------------------------------

data "aws_canonical_user_id" "current" {}

resource "random_id" "bucket_suffix" {
  byte_length = 4
}

resource "random_id" "prefix_suffix" {
  byte_length = 4
}

locals {
  base_name   = var.bucket_name != null ? var.bucket_name : "corebucket-${random_id.bucket_suffix.hex}"
  bucket_name = var.prefix ? "${local.base_name}-${random_id.prefix_suffix.hex}" : local.base_name

  tags = merge(
    var.tags,
    {
      Name = local.bucket_name
    }
  )

  create_kms_key = var.encryption && var.kms_key == ""
  kms_key_arn    = var.kms_key != "" ? var.kms_key : try(aws_kms_key.this[0].arn, null)

  create_replication_role = length(var.replication_rules) > 0 && var.replication_role == null
  replication_role_arn    = var.replication_role != null ? var.replication_role : try(aws_iam_role.replication[0].arn, null)

  enable_versioning = var.versioning || length(var.replication_rules) > 0 || var.object_lock_configuration != null
}

# ----------------------------------------------------------------------------
# Customer-managed KMS key (created only when no external key is supplied)
# ----------------------------------------------------------------------------

resource "aws_kms_key" "this" {
  count = local.create_kms_key ? 1 : 0

  description             = "Customer managed key for S3 bucket ${local.bucket_name}"
  deletion_window_in_days = 10
  enable_key_rotation     = true
  is_enabled              = true

  tags = local.tags
}

resource "aws_kms_alias" "this" {
  count = local.create_kms_key ? 1 : 0

  name          = "alias/${local.bucket_name}"
  target_key_id = aws_kms_key.this[0].key_id
}

# ----------------------------------------------------------------------------
# S3 bucket and its feature configuration
# ----------------------------------------------------------------------------

resource "aws_s3_bucket" "this" {
  bucket              = local.bucket_name
  force_destroy       = var.force_destroy
  object_lock_enabled = var.object_lock_configuration != null

  tags = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  count = (var.acl != null || length(var.grants) > 0) ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = (var.acl != null || length(var.grants) > 0) ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.acl

  dynamic "access_control_policy" {
    for_each = length(var.grants) > 0 ? [1] : []

    content {
      owner {
        id = data.aws_canonical_user_id.current.id
      }

      dynamic "grant" {
        for_each = var.grants

        content {
          permission = grant.value.permission

          grantee {
            id   = grant.value.id
            type = grant.value.type
            uri  = grant.value.uri
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

resource "aws_s3_bucket_request_payment_configuration" "this" {
  bucket = aws_s3_bucket.this.id
  payer  = var.request_payer
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  count = var.encryption ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = local.kms_key_arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "this" {
  count = local.enable_versioning ? 1 : 0

  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status     = "Enabled"
    mfa_delete = var.mfa_delete ? "Enabled" : "Disabled"
  }
}

resource "aws_s3_bucket_policy" "this" {
  count = var.policy != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  policy = var.policy
}

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.acceleration_status != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.acceleration_status
}

resource "aws_s3_bucket_logging" "this" {
  count = var.logging != null ? 1 : 0

  bucket        = aws_s3_bucket.this.id
  target_bucket = var.logging.target_bucket
  target_prefix = var.logging.target_prefix
}

resource "aws_s3_bucket_website_configuration" "this" {
  count = var.website != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "index_document" {
    for_each = try(var.website.index_document, null) != null ? [1] : []

    content {
      suffix = var.website.index_document
    }
  }

  dynamic "error_document" {
    for_each = try(var.website.error_document, null) != null ? [1] : []

    content {
      key = var.website.error_document
    }
  }

  dynamic "redirect_all_requests_to" {
    for_each = try(var.website.redirect_all_requests_to, null) != null ? [1] : []

    content {
      host_name = var.website.redirect_all_requests_to
    }
  }
}

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rule

    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = length(var.lifecycle_rule) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rule

    content {
      id     = try(rule.value.id, null)
      status = try(rule.value.enabled, true) ? "Enabled" : "Disabled"

      dynamic "filter" {
        for_each = (try(rule.value.prefix, null) != null || try(rule.value.tags, null) != null) ? [1] : []

        content {
          prefix = try(rule.value.prefix, null)

          dynamic "and" {
            for_each = try(rule.value.tags, null) != null ? [1] : []

            content {
              tags = rule.value.tags
            }
          }
        }
      }

      dynamic "expiration" {
        for_each = try(rule.value.expiration, null) != null ? [rule.value.expiration] : []

        content {
          days                         = try(expiration.value.days, null)
          date                         = try(expiration.value.date, null)
          expired_object_delete_marker = try(expiration.value.expired_object_delete_marker, null)
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = try(rule.value.noncurrent_version_expiration, null) != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days           = try(noncurrent_version_expiration.value.days, null)
          newer_noncurrent_versions = try(noncurrent_version_expiration.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = try(rule.value.noncurrent_version_transition, [])

        content {
          noncurrent_days           = try(noncurrent_version_transition.value.days, null)
          storage_class             = noncurrent_version_transition.value.storage_class
          newer_noncurrent_versions = try(noncurrent_version_transition.value.newer_noncurrent_versions, null)
        }
      }

      dynamic "transition" {
        for_each = try(rule.value.transition, [])

        content {
          days          = try(transition.value.days, null)
          date          = try(transition.value.date, null)
          storage_class = transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = try(rule.value.abort_incomplete_multipart_upload_days, null) != null ? [rule.value.abort_incomplete_multipart_upload_days] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_configuration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_configuration.mode
      days  = try(var.object_lock_configuration.days, null)
      years = try(var.object_lock_configuration.years, null)
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# ----------------------------------------------------------------------------
# Replication IAM role (created only when no external role is supplied)
# ----------------------------------------------------------------------------

resource "aws_iam_role" "replication" {
  count = local.create_replication_role ? 1 : 0

  name = "CoreS3ReplicationRole_${local.bucket_name}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "replication" {
  count = local.create_replication_role ? 1 : 0

  name = "CoreS3ReplicationPolicy_${local.bucket_name}"
  role = aws_iam_role.replication[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SourceBucketPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetReplicationConfiguration",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.this.arn
        ]
      },
      {
        Sid    = "SourceObjectPermissions"
        Effect = "Allow"
        Action = [
          "s3:GetObjectVersion",
          "s3:GetObjectVersionForReplication",
          "s3:GetObjectVersionAcl",
          "s3:GetObjectVersionTagging"
        ]
        Resource = [
          "${aws_s3_bucket.this.arn}/*"
        ]
      },
      {
        Sid    = "DestinationObjectPermissions"
        Effect = "Allow"
        Action = [
          "s3:ReplicateObject",
          "s3:ReplicateDelete",
          "s3:ReplicateTags"
        ]
        Resource = [
          "${aws_s3_bucket.this.arn}/*"
        ]
      }
    ]
  })
}

# ----------------------------------------------------------------------------
# Cross-region replication configuration
# ----------------------------------------------------------------------------

resource "aws_s3_bucket_replication_configuration" "this" {
  count = length(var.replication_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = local.replication_role_arn

  dynamic "rule" {
    for_each = var.replication_rules

    content {
      id       = try(rule.value.id, null)
      status   = try(rule.value.status, "Enabled")
      priority = try(rule.value.priority, null)

      dynamic "delete_marker_replication" {
        for_each = try(rule.value.delete_marker_replication_status, null) != null ? [rule.value.delete_marker_replication_status] : []

        content {
          status = delete_marker_replication.value
        }
      }

      dynamic "filter" {
        for_each = try(rule.value.filter, null) != null ? [rule.value.filter] : []

        content {
          prefix = try(filter.value.prefix, null)

          dynamic "and" {
            for_each = try(filter.value.tags, null) != null ? [1] : []

            content {
              tags = filter.value.tags
            }
          }
        }
      }

      destination {
        bucket        = rule.value.destination.bucket
        storage_class = try(rule.value.destination.storage_class, null)
        account       = try(rule.value.destination.account_id, null)

        dynamic "encryption_configuration" {
          for_each = try(rule.value.destination.replica_kms_key_id, null) != null ? [1] : []

          content {
            replica_kms_key_id = rule.value.destination.replica_kms_key_id
          }
        }

        dynamic "access_control_translation" {
          for_each = try(rule.value.destination.access_control_translation, null) != null ? [rule.value.destination.access_control_translation] : []

          content {
            owner = access_control_translation.value.owner
          }
        }

        dynamic "metrics" {
          for_each = try(rule.value.destination.metrics, null) != null ? [rule.value.destination.metrics] : []

          content {
            status = try(metrics.value.status, "Enabled")

            dynamic "event_threshold" {
              for_each = try(metrics.value.event_threshold, null) != null ? [metrics.value.event_threshold] : []

              content {
                minutes = try(event_threshold.value.minutes, null)
              }
            }
          }
        }

        dynamic "replication_time" {
          for_each = try(rule.value.destination.replication_time, null) != null ? [rule.value.destination.replication_time] : []

          content {
            status = try(replication_time.value.status, "Enabled")

            time {
              minutes = try(replication_time.value.time.minutes, null)
            }
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = try(rule.value.source_selection_criteria, null) != null ? [rule.value.source_selection_criteria] : []

        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = try(source_selection_criteria.value.sse_kms_encrypted_objects, null) != null ? [source_selection_criteria.value.sse_kms_encrypted_objects] : []

            content {
              status = sse_kms_encrypted_objects.value.status
            }
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

# ----------------------------------------------------------------------------
# Outputs
# ----------------------------------------------------------------------------

output "bucket_id" {
  description = "The name (ID) of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_name" {
  description = "The resolved name of the S3 bucket."
  value       = aws_s3_bucket.this.bucket
}

output "bucket_domain_name" {
  description = "The bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

output "bucket_regional_domain_name" {
  description = "The region-specific bucket domain name."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for bucket encryption."
  value       = local.kms_key_arn
}

output "kms_key_id" {
  description = "ID of the module-created KMS key, if any."
  value       = try(aws_kms_key.this[0].key_id, null)
}

output "replication_role_arn" {
  description = "ARN of the IAM role used for bucket replication."
  value       = local.replication_role_arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "awsRegion" {
  description = "AWS region used for the network stack."
  type        = string
  default     = "us-east-1"
}

variable "projectPrefix" {
  description = "Prefix applied to every resource name/Name tag."
  type        = string
  default     = "f5-dcec"
}

variable "resourceOwner" {
  description = "Owner of the resources, used for the Owner tag."
  type        = string
  default     = "f5-user"
}

variable "buildSuffix" {
  description = "Suffix appended to resource names to distinguish builds."
  type        = string
  default     = "YY"
}

variable "map_public_ip_on_launch" {
  description = "Whether instances launched in public subnets receive a public IP."
  type        = bool
  default     = false
}

variable "awsAz1" {
  description = "Optional first availability zone. Defaults to the first available AZ in the region."
  type        = string
  default     = null
}

variable "awsAz2" {
  description = "Optional second availability zone. Defaults to awsAz1 when awsAz1 is specified, otherwise the second available AZ."
  type        = string
  default     = null
}

variable "vpcMainCidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.1.0.0/16"
}

variable "vpcMainSubPubACidr" {
  description = "CIDR block for the public subnet in the first availability zone."
  type        = string
  default     = "10.1.10.0/24"
}

variable "vpcMainSubPubBCidr" {
  description = "CIDR block for the public subnet in the second availability zone."
  type        = string
  default     = "10.1.110.0/24"
}

variable "vpcMainSubMgmtACidr" {
  description = "CIDR block for the management subnet in the first availability zone."
  type        = string
  default     = "10.1.1.0/24"
}

variable "vpcMainSubMgmtBCidr" {
  description = "CIDR block for the management subnet in the second availability zone."
  type        = string
  default     = "10.1.101.0/24"
}

variable "vpcMainSubPrivACidr" {
  description = "CIDR block for the private subnet in the first availability zone."
  type        = string
  default     = "10.1.20.0/24"
}

variable "vpcMainSubPrivBCidr" {
  description = "CIDR block for the private subnet in the second availability zone."
  type        = string
  default     = "10.1.120.0/24"
}

###############################################################################
# Data sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  # First AZ: explicit variable, otherwise the first available AZ in the region.
  aws_az_1 = var.awsAz1 != null ? var.awsAz1 : data.aws_availability_zones.available.names[0]

  # Second AZ: explicit variable, otherwise fall back to awsAz1 when it was
  # specified, otherwise the second available AZ in the region.
  aws_az_2 = var.awsAz2 != null ? var.awsAz2 : (
    var.awsAz1 != null ? var.awsAz1 : try(data.aws_availability_zones.available.names[1], data.aws_availability_zones.available.names[0])
  )

  name_prefix = "${var.projectPrefix}-${var.buildSuffix}"

  common_tags = {
    Project     = var.projectPrefix
    Owner       = var.resourceOwner
    BuildSuffix = var.buildSuffix
    Region      = var.awsRegion
    ManagedBy   = "Terraform"
  }
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "vpc_main" {
  cidr_block           = var.vpcMainCidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-vpc"
    }
  )
}

###############################################################################
# Subnets - public
###############################################################################

resource "aws_subnet" "vpc_main_sub_pub_a" {
  vpc_id                  = aws_vpc.vpc_main.id
  cidr_block              = var.vpcMainSubPubACidr
  availability_zone       = local.aws_az_1
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-sub-pub-a"
      Tier = "public"
    }
  )
}

resource "aws_subnet" "vpc_main_sub_pub_b" {
  vpc_id                  = aws_vpc.vpc_main.id
  cidr_block              = var.vpcMainSubPubBCidr
  availability_zone       = local.aws_az_2
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-sub-pub-b"
      Tier = "public"
    }
  )
}

###############################################################################
# Subnets - management
###############################################################################

resource "aws_subnet" "vpc_main_sub_mgmt_a" {
  vpc_id            = aws_vpc.vpc_main.id
  cidr_block        = var.vpcMainSubMgmtACidr
  availability_zone = local.aws_az_1

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-sub-mgmt-a"
      Tier = "management"
    }
  )
}

resource "aws_subnet" "vpc_main_sub_mgmt_b" {
  vpc_id            = aws_vpc.vpc_main.id
  cidr_block        = var.vpcMainSubMgmtBCidr
  availability_zone = local.aws_az_2

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-sub-mgmt-b"
      Tier = "management"
    }
  )
}

###############################################################################
# Subnets - private
###############################################################################

resource "aws_subnet" "vpc_main_sub_priv_a" {
  vpc_id            = aws_vpc.vpc_main.id
  cidr_block        = var.vpcMainSubPrivACidr
  availability_zone = local.aws_az_1

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-sub-priv-a"
      Tier = "private"
    }
  )
}

resource "aws_subnet" "vpc_main_sub_priv_b" {
  vpc_id            = aws_vpc.vpc_main.id
  cidr_block        = var.vpcMainSubPrivBCidr
  availability_zone = local.aws_az_2

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-sub-priv-b"
      Tier = "private"
    }
  )
}

###############################################################################
# Internet gateway
###############################################################################

resource "aws_internet_gateway" "vpc_main_igw" {
  vpc_id = aws_vpc.vpc_main.id

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-igw"
    }
  )
}

###############################################################################
# Route table + default route to the internet gateway
###############################################################################

resource "aws_route_table" "vpc_main_rt" {
  vpc_id = aws_vpc.vpc_main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.vpc_main_igw.id
  }

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-rt-main"
    }
  )
}

resource "aws_main_route_table_association" "vpc_main_rt_assoc" {
  vpc_id         = aws_vpc.vpc_main.id
  route_table_id = aws_route_table.vpc_main_rt.id
}

variable "region" {
  description = "AWS region to deploy the benchmark network and load balancer into."
  type        = string
  default     = "us-east-1"
}

variable "name" {
  description = "Base name applied to all named resources."
  type        = string
  default     = "benchmark"
}

variable "listener_rule_count" {
  description = "Number of path-based listener rules to create (each matches /static-N/*)."
  type        = number
  default     = 1
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 2)

  tags = {
    Name = var.name
  }
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    Name = var.name
  })
}

resource "aws_subnet" "main" {
  count = 2

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  availability_zone = local.azs[count.index]

  tags = merge(local.tags, {
    Name = "${var.name}-subnet-${count.index}"
  })
}

resource "aws_security_group" "alb" {
  name        = "${var.name}-alb"
  description = "Allow all traffic within the VPC CIDR for the internal ${var.name} ALB."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "All traffic from within the VPC CIDR."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "All traffic to within the VPC CIDR."
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, {
    Name = "${var.name}-alb-sg"
  })
}

resource "tls_private_key" "self_signed" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "self_signed" {
  private_key_pem = tls_private_key.self_signed.private_key_pem

  subject {
    common_name  = "${var.name}.internal"
    organization = "Benchmark"
  }

  validity_period_hours = 8760

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "self_signed" {
  certificate_body  = tls_self_signed_cert.self_signed.cert_pem
  private_key       = tls_private_key.self_signed.private_key_pem
  certificate_chain = tls_self_signed_cert.self_signed.cert_pem

  lifecycle {
    create_before_destroy = true
  }

  tags = merge(local.tags, {
    Name = "${var.name}-self-signed"
  })
}

resource "aws_lb_target_group" "main" {
  name     = var.name
  port     = 8080
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    enabled             = true
    protocol            = "HTTP"
    port                = "8081"
    path                = "/health"
    interval            = 60
    timeout             = 3
    matcher             = "200-299"
    healthy_threshold   = 3
    unhealthy_threshold = 3
  }

  tags = merge(local.tags, {
    Name = var.name
  })
}

resource "aws_lb" "main" {
  name                       = var.name
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.main[*].id
  drop_invalid_header_fields = true

  tags = merge(local.tags, {
    Name = var.name
  })
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.main.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = aws_acm_certificate.self_signed.arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  tags = merge(local.tags, {
    Name = "${var.name}-https-listener"
  })
}

resource "aws_lb_listener_rule" "static" {
  count = var.listener_rule_count

  listener_arn = aws_lb_listener.https.arn
  priority     = 100 + count.index

  action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.main.arn
  }

  condition {
    path_pattern {
      values = ["/static-${count.index}/*"]
    }
  }

  tags = merge(local.tags, {
    Name = "${var.name}-static-${count.index}"
  })
}

###############################################################################
# Variables
###############################################################################

variable "region" {
  description = "AWS region in which the networking infrastructure is deployed."
  type        = string
  default     = "us-east-1"
}

variable "name_prefix" {
  description = "Prefix applied to the Name tag of every resource created by this stack."
  type        = string
  default     = "tfm-aws"
}

variable "instance_tenancy" {
  description = "Tenancy option for instances launched into the VPC."
  type        = string
  default     = "default"
}

variable "enable_dns_support" {
  description = "Whether DNS resolution is supported in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_hostnames" {
  description = "Whether instances launched in the VPC receive DNS hostnames."
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "Main IPv4 CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnets" {
  description = "List of CIDR blocks used for the private subnets (one per AZ)."
  type        = list(string)
  default     = ["10.0.2.0/24", "10.0.3.0/24"]
}

variable "public_inbound_acl_rules" {
  description = "Inbound (ingress) rules applied to the shared network ACL attached to the private subnets."
  type        = list(map(string))
  default = [
    {
      rule_number = "100"
      rule_action = "allow"
      protocol    = "tcp"
      from_port   = "1024"
      to_port     = "65535"
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

variable "public_outbound_acl_rules" {
  description = "Outbound (egress) rules applied to the shared network ACL attached to the private subnets."
  type        = list(map(string))
  default = [
    {
      rule_number = "100"
      rule_action = "allow"
      protocol    = "tcp"
      from_port   = "443"
      to_port     = "443"
      cidr_block  = "0.0.0.0/0"
    }
  ]
}

###############################################################################
# Locals
###############################################################################

locals {
  tags = {
    Project   = var.name_prefix
    ManagedBy = "Terraform"
  }
}

###############################################################################
# Data Sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"

  filter {
    name   = "opt-in-status"
    values = ["opt-in-not-required"]
  }
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "this" {
  cidr_block           = var.vpc_cidr
  instance_tenancy     = var.instance_tenancy
  enable_dns_support   = var.enable_dns_support
  enable_dns_hostnames = var.enable_dns_hostnames

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-vpc"
  })
}

###############################################################################
# Private Subnets
###############################################################################

resource "aws_subnet" "private" {
  count = length(var.private_subnets)

  vpc_id                  = aws_vpc.this.id
  cidr_block              = var.private_subnets[count.index]
  availability_zone       = data.aws_availability_zones.available.names[count.index]
  map_public_ip_on_launch = false

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-private-${data.aws_availability_zones.available.names[count.index]}"
    Tier = "private"
  })
}

###############################################################################
# Private Route Tables
###############################################################################

resource "aws_route_table" "private" {
  count = length(var.private_subnets)

  vpc_id = aws_vpc.this.id

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-private-${data.aws_availability_zones.available.names[count.index]}"
  })
}

resource "aws_route_table_association" "private" {
  count = length(var.private_subnets)

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

###############################################################################
# S3 Gateway VPC Endpoint
###############################################################################

resource "aws_vpc_endpoint" "s3" {
  vpc_id            = aws_vpc.this.id
  service_name      = "com.amazonaws.${data.aws_region.current.name}.s3"
  vpc_endpoint_type = "Gateway"
  route_table_ids   = aws_route_table.private[*].id

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-s3-gateway-endpoint"
  })
}

###############################################################################
# Shared Network ACL for the Private Subnets
###############################################################################

resource "aws_network_acl" "private" {
  vpc_id     = aws_vpc.this.id
  subnet_ids = aws_subnet.private[*].id

  tags = merge(local.tags, {
    Name = "${var.name_prefix}-private-nacl"
  })
}

resource "aws_network_acl_rule" "private_inbound" {
  count = length(var.public_inbound_acl_rules)

  network_acl_id = aws_network_acl.private.id
  egress         = false
  rule_number    = var.public_inbound_acl_rules[count.index]["rule_number"]
  rule_action    = lookup(var.public_inbound_acl_rules[count.index], "rule_action", "allow")
  protocol       = lookup(var.public_inbound_acl_rules[count.index], "protocol", "-1")

  from_port  = lookup(var.public_inbound_acl_rules[count.index], "from_port", null)
  to_port    = lookup(var.public_inbound_acl_rules[count.index], "to_port", null)
  cidr_block = lookup(var.public_inbound_acl_rules[count.index], "cidr_block", null)

  icmp_type = lookup(var.public_inbound_acl_rules[count.index], "icmp_type", null)
  icmp_code = lookup(var.public_inbound_acl_rules[count.index], "icmp_code", null)
}

resource "aws_network_acl_rule" "private_outbound" {
  count = length(var.public_outbound_acl_rules)

  network_acl_id = aws_network_acl.private.id
  egress         = true
  rule_number    = var.public_outbound_acl_rules[count.index]["rule_number"]
  rule_action    = lookup(var.public_outbound_acl_rules[count.index], "rule_action", "allow")
  protocol       = lookup(var.public_outbound_acl_rules[count.index], "protocol", "-1")

  from_port  = lookup(var.public_outbound_acl_rules[count.index], "from_port", null)
  to_port    = lookup(var.public_outbound_acl_rules[count.index], "to_port", null)
  cidr_block = lookup(var.public_outbound_acl_rules[count.index], "cidr_block", null)

  icmp_type = lookup(var.public_outbound_acl_rules[count.index], "icmp_type", null)
  icmp_code = lookup(var.public_outbound_acl_rules[count.index], "icmp_code", null)
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the created VPC."
  value       = aws_vpc.this.id
}

output "vpc_cidr_block" {
  description = "Primary CIDR block of the created VPC."
  value       = aws_vpc.this.cidr_block
}

output "availability_zones" {
  description = "Availability zones used for the private subnets."
  value       = slice(data.aws_availability_zones.available.names, 0, length(var.private_subnets))
}

output "private_subnet_ids" {
  description = "IDs of the private subnets."
  value       = aws_subnet.private[*].id
}

output "private_route_table_ids" {
  description = "IDs of the private route tables."
  value       = aws_route_table.private[*].id
}

output "s3_vpc_endpoint_id" {
  description = "ID of the S3 gateway VPC endpoint."
  value       = aws_vpc_endpoint.s3.id
}

output "private_network_acl_id" {
  description = "ID of the shared network ACL associated with the private subnets."
  value       = aws_network_acl.private.id
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

################################################################################
# Account / Region / Partition metadata (static provider metadata — greenfield-safe)
################################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

################################################################################
# Variables
################################################################################

variable "create" {
  description = "Controls whether the primary SQS queue (and related resources) should be created"
  type        = bool
  default     = true
}

variable "name" {
  description = "Name of the primary queue. Mutually exclusive with name_prefix. A '.fifo' suffix is appended automatically for FIFO queues."
  type        = string
  default     = null
}

variable "name_prefix" {
  description = "Prefix for the primary queue name. Mutually exclusive with name. A '.fifo' suffix is appended automatically for FIFO queues."
  type        = string
  default     = null
}

variable "fifo_queue" {
  description = "Whether the queues should be created as FIFO queues. A '.fifo' suffix is appended to the name automatically."
  type        = bool
  default     = false
}

variable "content_based_deduplication" {
  description = "Enables content-based deduplication. Only applies to FIFO queues."
  type        = bool
  default     = false
}

variable "deduplication_scope" {
  description = "Specifies whether message deduplication occurs at the message group or queue level. Valid values are 'messageGroup' and 'queue'. Only applies to FIFO queues."
  type        = string
  default     = null
}

variable "fifo_throughput_limit" {
  description = "Specifies whether the FIFO queue throughput quota applies to the entire queue or per message group. Valid values are 'perQueue' and 'perMessageGroupId'. Only applies to FIFO queues."
  type        = string
  default     = null
}

variable "delay_seconds" {
  description = "The time in seconds that the delivery of all messages in the queue is delayed."
  type        = number
  default     = 0
}

variable "max_message_size" {
  description = "The limit of how many bytes a message can contain before Amazon SQS rejects it."
  type        = number
  default     = 262144
}

variable "message_retention_seconds" {
  description = "The number of seconds Amazon SQS retains a message."
  type        = number
  default     = 345600
}

variable "receive_wait_time_seconds" {
  description = "The time for which a ReceiveMessage call will wait for a message to arrive (long polling)."
  type        = number
  default     = 0
}

variable "visibility_timeout_seconds" {
  description = "The visibility timeout for the queue."
  type        = number
  default     = 30
}

variable "sqs_managed_sse_enabled" {
  description = "Enables SQS-managed server-side encryption. Applied automatically whenever kms_master_key_id is not provided."
  type        = bool
  default     = true
}

variable "kms_master_key_id" {
  description = "The ID of an AWS-managed customer master key (CMK) for Amazon SQS or a custom CMK. When omitted, SQS-managed SSE is used."
  type        = string
  default     = null
}

variable "kms_data_key_reuse_period_seconds" {
  description = "The length of time, in seconds, for which Amazon SQS can reuse a data key to encrypt or decrypt messages before calling AWS KMS again."
  type        = number
  default     = null
}

variable "policy" {
  description = "The JSON policy for the SQS queue (base/source policy document)."
  type        = string
  default     = null
}

variable "create_queue_policy" {
  description = "Controls whether a queue policy should be attached to the primary queue."
  type        = bool
  default     = false
}

variable "queue_policy_override" {
  description = "JSON policy document that overrides the source policy document and any statements rendered from queue_policy_statements."
  type        = string
  default     = null
}

variable "queue_policy_statements" {
  description = "A list of IAM policy statements to render into the queue policy. Each statement may define sid, effect, actions, resources (defaults to the queue ARN when omitted), principals and conditions."
  type        = any
  default     = []
}

variable "create_dlq" {
  description = "Controls whether a dead-letter queue should be created and wired to the primary queue."
  type        = bool
  default     = false
}

variable "dlq_name" {
  description = "Name of the dead-letter queue. Defaults to '<main-queue-name>-dlq'. A '.fifo' suffix is appended automatically for FIFO queues."
  type        = string
  default     = null
}

variable "dlq_name_prefix" {
  description = "Prefix for the dead-letter queue name. A '.fifo' suffix is appended automatically for FIFO queues."
  type        = string
  default     = null
}

variable "dlq_message_retention_seconds" {
  description = "The number of seconds the dead-letter queue retains a message. Falls back to the primary queue value when not set."
  type        = number
  default     = null
}

variable "max_receive_count" {
  description = "The number of times a message is delivered to the source queue before being moved to the dead-letter queue."
  type        = number
  default     = 5
}

variable "create_dlq_redrive_allow_policy" {
  description = "Controls whether a redrive allow policy is attached to the dead-letter queue, restricting redrive permissions byQueue to the primary queue."
  type        = bool
  default     = true
}

variable "tags" {
  description = "A map of tags to assign to the created resources."
  type        = map(string)
  default     = {}
}

################################################################################
# Locals
################################################################################

locals {
  create     = var.create
  create_dlq = var.create && var.create_dlq
  fifo_queue = var.fifo_queue

  fifo_suffix = local.fifo_queue ? ".fifo" : ""

  # Primary queue naming: exactly one of name / name_prefix is supplied to the resource.
  main_use_name  = var.name != null || var.name_prefix == null
  main_name_base = coalesce(var.name, "sqs-queue")

  queue_name        = local.main_use_name ? "${local.main_name_base}${local.fifo_suffix}" : null
  queue_name_prefix = local.main_use_name ? null : "${var.name_prefix}${local.fifo_suffix}"

  # Dead-letter queue naming: defaults to "<main-name>-dlq" and inherits the FIFO suffix.
  dlq_use_name  = var.dlq_name != null || var.dlq_name_prefix == null
  dlq_name_base = coalesce(var.dlq_name, local.main_use_name ? "${local.main_name_base}-dlq" : "${coalesce(var.name_prefix, "sqs-queue")}-dlq")

  dlq_name        = local.dlq_use_name ? "${local.dlq_name_base}${local.fifo_suffix}" : null
  dlq_name_prefix = local.dlq_use_name ? null : "${var.dlq_name_prefix}${local.fifo_suffix}"

  # SQS-managed SSE is used automatically whenever a custom KMS key is omitted.
  sqs_managed_sse_enabled = var.kms_master_key_id == null ? var.sqs_managed_sse_enabled : false

  dlq_message_retention_seconds = var.dlq_message_retention_seconds != null ? var.dlq_message_retention_seconds : var.message_retention_seconds

  # Primary queue ARN composed purely from deterministic inputs (variables + static
  # provider metadata). This MUST NOT reference aws_sqs_queue resources, so it does
  # not introduce a static dependency edge back to the primary queue.
  # Only resolvable when the deterministic `name` pattern is used; under `name_prefix`
  # the AWS-generated suffix is unknowable at plan time and this is null.
  primary_queue_arn = local.queue_name != null ? format(
    "arn:%s:sqs:%s:%s:%s",
    data.aws_partition.current.partition,
    data.aws_region.current.name,
    data.aws_caller_identity.current.account_id,
    local.queue_name
  ) : null

  # The redrive allow policy can only be rendered when the primary queue ARN is
  # statically knowable (name pattern) and the DLQ is being created.
  create_dlq_redrive_allow_policy = local.create_dlq && var.create_dlq_redrive_allow_policy && local.primary_queue_arn != null

  tags = var.tags
}

################################################################################
# Primary Queue
################################################################################

resource "aws_sqs_queue" "this" {
  count = local.create ? 1 : 0

  name        = local.queue_name
  name_prefix = local.queue_name_prefix

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = var.message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  fifo_queue                  = local.fifo_queue
  content_based_deduplication = local.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = local.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = local.fifo_queue ? var.fifo_throughput_limit : null

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled

  # this -> dlq edge is intentionally preserved: the DLQ must exist before the
  # primary queue's redrive policy is applied (AWS validates the target exists).
  redrive_policy = local.create_dlq ? jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq[0].arn
    maxReceiveCount     = var.max_receive_count
  }) : null

  tags = local.tags
}

################################################################################
# Primary Queue Policy
################################################################################

data "aws_iam_policy_document" "queue" {
  count = local.create && var.create_queue_policy ? 1 : 0

  source_policy_documents = compact([var.policy, var.queue_policy_override])

  dynamic "statement" {
    for_each = var.queue_policy_statements
    content {
      sid    = try(statement.value.sid, null)
      effect = try(statement.value.effect, "Allow")

      actions = try(statement.value.actions, null)

      resources = length(try(statement.value.resources, [])) > 0 ? try(statement.value.resources, []) : [aws_sqs_queue.this[0].arn]

      dynamic "principals" {
        for_each = try(statement.value.principals, [])
        content {
          type        = principals.value.type
          identifiers = principals.value.identifiers
        }
      }

      dynamic "condition" {
        for_each = try(statement.value.conditions, [])
        content {
          test     = condition.value.test
          variable = condition.value.variable
          values   = condition.value.values
        }
      }
    }
  }
}

resource "aws_sqs_queue_policy" "this" {
  count = local.create && var.create_queue_policy ? 1 : 0

  queue_url = aws_sqs_queue.this[0].url
  policy    = data.aws_iam_policy_document.queue[0].json
}

################################################################################
# Dead-Letter Queue
################################################################################

resource "aws_sqs_queue" "dlq" {
  count = local.create_dlq ? 1 : 0

  name        = local.dlq_name
  name_prefix = local.dlq_name_prefix

  delay_seconds              = var.delay_seconds
  max_message_size           = var.max_message_size
  message_retention_seconds  = local.dlq_message_retention_seconds
  receive_wait_time_seconds  = var.receive_wait_time_seconds
  visibility_timeout_seconds = var.visibility_timeout_seconds

  fifo_queue                  = local.fifo_queue
  content_based_deduplication = local.fifo_queue ? var.content_based_deduplication : null
  deduplication_scope         = local.fifo_queue ? var.deduplication_scope : null
  fifo_throughput_limit       = local.fifo_queue ? var.fifo_throughput_limit : null

  kms_master_key_id                 = var.kms_master_key_id
  kms_data_key_reuse_period_seconds = var.kms_master_key_id != null ? var.kms_data_key_reuse_period_seconds : null
  sqs_managed_sse_enabled           = local.sqs_managed_sse_enabled

  # The primary queue ARN here is a purely derived string (NOT a resource reference),
  # which removes the dlq -> this static edge and breaks the dependency cycle.
  redrive_allow_policy = local.create_dlq_redrive_allow_policy ? jsonencode({
    redrivePermission = "byQueue"
    sourceQueueArns   = [local.primary_queue_arn]
  }) : null

  tags = local.tags
}

################################################################################
# Outputs
################################################################################

output "queue_id" {
  description = "The URL of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].id, null)
}

output "queue_arn" {
  description = "The ARN of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].arn, null)
}

output "queue_name" {
  description = "The name of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].name, null)
}

output "queue_url" {
  description = "The URL of the primary SQS queue."
  value       = try(aws_sqs_queue.this[0].url, null)
}

output "dead_letter_queue_arn" {
  description = "The ARN of the dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].arn, null)
}

output "dead_letter_queue_url" {
  description = "The URL of the dead-letter queue."
  value       = try(aws_sqs_queue.dlq[0].url, null)
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
  }
}

data "aws_partition" "current" {}

variable "backup_name" {
  description = "Name used for the AWS Backup vault and derived resources."
  type        = string
  default     = "default"
}

variable "account_type" {
  description = "Account role for this deployment: 'workload' or 'backup'."
  type        = string
  default     = "workload"

  validation {
    condition     = contains(["workload", "backup"], var.account_type)
    error_message = "account_type must be strictly either 'workload' or 'backup'."
  }
}

variable "kms_key_arn" {
  description = "Optional ARN of a KMS key used to encrypt the backup vault."
  type        = string
  default     = null
}

variable "vault_policy" {
  description = "Optional JSON policy document to attach to the backup vault."
  type        = string
  default     = null
}

variable "min_retention_days" {
  description = "Minimum retention days for the vault lock. Setting this enables the vault lock."
  type        = number
  default     = null
}

variable "max_retention_days" {
  description = "Maximum retention days for the vault lock."
  type        = number
  default     = null
}

variable "changeable_for_days" {
  description = "Number of days the vault lock remains changeable (governance cooling-off period)."
  type        = number
  default     = null
}

variable "enable_aws_backup_vault_notifications" {
  description = "Whether to enable SNS notifications for the backup vault."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "ARN of the SNS topic used for backup vault notifications."
  type        = string
  default     = null
}

variable "backup_vault_events" {
  description = "List of backup vault events that trigger SNS notifications."
  type        = list(string)
  default     = ["BACKUP_JOB_FAILED", "COPY_JOB_FAILED"]
}

variable "rule_schedule" {
  description = "Cron or rate expression that defines the backup rule schedule."
  type        = string
  default     = "cron(0 5 * * ? *)"
}

variable "selection_resources" {
  description = "Optional list of resource ARNs for an additional resource-based backup selection."
  type        = list(string)
  default     = []
}

variable "copy_actions" {
  description = "List of cross-region or cross-account copy actions for the backup rule."
  type = list(object({
    destination_vault_arn = string
    cold_storage_after    = optional(number, 30)
    delete_after          = optional(number, 120)
  }))
  default = []
}

variable "tags" {
  description = "Additional tags to apply to all created resources."
  type        = map(string)
  default     = {}
}

locals {
  create_workload_resources = var.account_type == "workload"
  vault_lock_enabled        = var.min_retention_days != null
  backup_plan_name          = "plan-${var.backup_name}-backup"

  common_tags = merge(
    var.tags,
    {
      BackupName  = var.backup_name
      AccountType = var.account_type
      ManagedBy   = "terraform"
    }
  )
}

resource "aws_backup_vault" "this" {
  name        = var.backup_name
  kms_key_arn = var.kms_key_arn
  tags        = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_backup_vault_lock_configuration" "this" {
  count = local.vault_lock_enabled ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  min_retention_days  = var.min_retention_days
  max_retention_days  = var.max_retention_days
  changeable_for_days = var.changeable_for_days
}

resource "aws_backup_vault_policy" "this" {
  count = var.vault_policy != null ? 1 : 0

  backup_vault_name = aws_backup_vault.this.name
  policy            = var.vault_policy
}

resource "aws_backup_vault_notifications" "this" {
  count = var.enable_aws_backup_vault_notifications ? 1 : 0

  backup_vault_name   = aws_backup_vault.this.name
  sns_topic_arn       = var.sns_topic_arn
  backup_vault_events = var.backup_vault_events

  lifecycle {
    precondition {
      condition     = var.sns_topic_arn != null
      error_message = "sns_topic_arn must be provided when enable_aws_backup_vault_notifications is true."
    }
  }
}

resource "aws_iam_role" "backup" {
  count = local.create_workload_resources ? 1 : 0

  name_prefix = "aws-backup-"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_iam_role_policy_attachment" "backup" {
  count = local.create_workload_resources ? 1 : 0

  role       = aws_iam_role.backup[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWSBackupServiceRolePolicyForBackup"
}

resource "aws_backup_plan" "this" {
  count = local.create_workload_resources ? 1 : 0

  name = local.backup_plan_name

  rule {
    rule_name         = "${local.backup_plan_name}-rule"
    target_vault_name = aws_backup_vault.this.name
    schedule          = var.rule_schedule
    start_window      = 60
    completion_window = 120

    lifecycle {
      cold_storage_after = 30
      delete_after       = 120
    }

    recovery_point_tags = local.common_tags

    dynamic "copy_action" {
      for_each = var.copy_actions
      content {
        destination_vault_arn = copy_action.value.destination_vault_arn

        lifecycle {
          cold_storage_after = copy_action.value.cold_storage_after
          delete_after       = copy_action.value.delete_after
        }
      }
    }
  }

  tags = local.common_tags
}

resource "aws_backup_selection" "tags" {
  count = local.create_workload_resources ? 1 : 0

  name         = "${local.backup_plan_name}-tags-selection"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.backup[0].arn

  selection_tag {
    type  = "STRINGEQUALS"
    key   = "Backup"
    value = "true"
  }
}

resource "aws_backup_selection" "resources" {
  count = local.create_workload_resources && length(var.selection_resources) > 0 ? 1 : 0

  name         = "${local.backup_plan_name}-resources-selection"
  plan_id      = aws_backup_plan.this[0].id
  iam_role_arn = aws_iam_role.backup[0].arn
  resources    = var.selection_resources
}

variable "config_name" {
  description = "Base name for the AWS Config compliance auditing stack. When null or empty a pet name is generated."
  type        = string
  default     = "config"
}

resource "random_pet" "config_name" {
  length    = 2
  separator = "-"
}

locals {
  config_name    = coalesce(var.config_name, random_pet.config_name.id)
  sns_topic_name = local.config_name
  s3_key_prefix  = "awsconfig/records"

  tags = {
    "terraform.io" = "true"
    "environment"  = "security"
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

# -----------------------------------------------------------------------------
# Customer managed KMS key (automatic rotation) for the SNS topic
# -----------------------------------------------------------------------------
resource "aws_kms_key" "config_sns" {
  description             = "Customer managed key used to encrypt the AWS Config SNS topic."
  deletion_window_in_days = 7
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "EnableRootPermissions"
        Effect    = "Allow"
        Principal = { AWS = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root" }
        Action    = "kms:*"
        Resource  = "*"
      },
      {
        Sid       = "AllowSnsEncryption"
        Effect    = "Allow"
        Principal = { Service = "sns.amazonaws.com" }
        Action = [
          "kms:Decrypt",
          "kms:GenerateDataKey*",
        ]
        Resource = "*"
      },
    ]
  })

  tags = local.tags
}

resource "aws_kms_alias" "config_sns" {
  name          = "alias/${local.config_name}-config-sns"
  target_key_id = aws_kms_key.config_sns.key_id
}

# -----------------------------------------------------------------------------
# SNS topic (encrypted with the customer managed KMS key)
# -----------------------------------------------------------------------------
resource "aws_sns_topic" "config" {
  name              = local.sns_topic_name
  kms_master_key_id = aws_kms_key.config_sns.id

  tags = local.tags
}

# -----------------------------------------------------------------------------
# S3 snapshot storage bucket
# -----------------------------------------------------------------------------
resource "aws_s3_bucket" "snapshot" {
  bucket        = "${local.config_name}-config-snapshots-${data.aws_caller_identity.current.account_id}"
  force_destroy = true

  tags = local.tags
}

resource "aws_s3_bucket_public_access_block" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.config_sns.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_policy" "snapshot" {
  bucket = aws_s3_bucket.snapshot.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid       = "AWSConfigBucketPermissionsCheck"
        Effect    = "Allow"
        Principal = { Service = "config.amazonaws.com" }
        Action    = "s3:GetBucketAcl"
        Resource  = aws_s3_bucket.snapshot.arn
      },
      {
        Sid       = "AWSConfigBucketExistenceCheck"
        Effect    = "Allow"
        Principal = { Service = "config.amazonaws.com" }
        Action    = "s3:ListBucket"
        Resource  = aws_s3_bucket.snapshot.arn
      },
      {
        Sid       = "AWSConfigBucketDelivery"
        Effect    = "Allow"
        Principal = { Service = "config.amazonaws.com" }
        Action    = "s3:PutObject"
        Resource  = "${aws_s3_bucket.snapshot.arn}/${local.s3_key_prefix}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
    ]
  })
}

# -----------------------------------------------------------------------------
# IAM role for AWS Config
# -----------------------------------------------------------------------------
resource "aws_iam_role" "config" {
  name = local.config_name

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect    = "Allow"
        Principal = { Service = "config.amazonaws.com" }
        Action    = "sts:AssumeRole"
      },
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "config_managed" {
  role       = aws_iam_role.config.name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/service-role/AWS_ConfigRole"
}

resource "aws_iam_role_policy" "config_snapshot_bucket" {
  name = "${local.config_name}-snapshot-bucket-write"
  role = aws_iam_role.config.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SnapshotBucketWrite"
        Effect = "Allow"
        Action = [
          "s3:PutObject",
        ]
        Resource = "${aws_s3_bucket.snapshot.arn}/${local.s3_key_prefix}/*"
        Condition = {
          StringEquals = {
            "s3:x-amz-acl" = "bucket-owner-full-control"
          }
        }
      },
    ]
  })
}

resource "aws_iam_role_policy" "config_sns_publish" {
  name = "${local.config_name}-sns-publish"
  role = aws_iam_role.config.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "SnsPublish"
        Effect   = "Allow"
        Action   = ["sns:Publish"]
        Resource = aws_sns_topic.config.arn
      },
    ]
  })
}

# -----------------------------------------------------------------------------
# AWS Config recorder and delivery channel
# -----------------------------------------------------------------------------
resource "aws_config_configuration_recorder" "config" {
  name     = local.config_name
  role_arn = aws_iam_role.config.arn

  recording_group {
    all_supported                 = true
    include_global_resource_types = true
  }
}

resource "aws_config_delivery_channel" "config" {
  name           = local.config_name
  s3_bucket_name = aws_s3_bucket.snapshot.bucket
  s3_key_prefix  = local.s3_key_prefix
  sns_topic_arn  = aws_sns_topic.config.arn

  snapshot_delivery_properties {
    delivery_frequency = "TwentyFour_Hours"
  }

  depends_on = [
    aws_config_configuration_recorder.config,
    aws_s3_bucket_policy.snapshot,
  ]
}

resource "aws_config_configuration_recorder_status" "config" {
  name       = aws_config_configuration_recorder.config.name
  is_enabled = true

  depends_on = [aws_config_delivery_channel.config]
}

# -----------------------------------------------------------------------------
# Managed AWS Config rules (evaluated every 24 hours / on configuration change)
# -----------------------------------------------------------------------------
resource "aws_config_config_rule" "cloudtrail_enabled" {
  name                        = "cloudtrail-enabled"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "CLOUD_TRAIL_ENABLED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "iam_pw_policy" {
  name                        = "iam-pw-policy"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "IAM_PASSWORD_POLICY"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ec2_vpc" {
  name                        = "ec2-vpc"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "INSTANCES_IN_VPC"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "root_mfa_enabled" {
  name                        = "root-mfa-enabled"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "ROOT_ACCOUNT_MFA_ENABLED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "acm_expiration_check" {
  name                        = "acm-expiration-check"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "ACM_CERTIFICATE_EXPIRATION_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ebs_inuse_check" {
  name                        = "ebs-inuse-check"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "EC2_VOLUME_INUSE_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "ec2_imdsv2_check" {
  name                        = "ec2-imdsv2-check"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "EC2_IMDSV2_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_encrypted" {
  name                        = "rds-encrypted"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "RDS_STORAGE_ENCRYPTED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_private" {
  name                        = "rds-private"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "RDS_INSTANCE_PUBLIC_ACCESS_CHECK"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "rds_private_snapshots" {
  name                        = "rds-private-snapshots"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "RDS_SNAPSHOTS_PUBLIC_PROHIBITED"
  }

  depends_on = [aws_config_configuration_recorder.config]
}

resource "aws_config_config_rule" "required_tags" {
  name                        = "required-tags"
  maximum_execution_frequency = "TwentyFour_Hours"

  source {
    owner             = "AWS"
    source_identifier = "REQUIRED_TAGS"
  }

  scope {
    compliance_resource_types = ["AWS::S3::Bucket"]
  }

  input_parameters = jsonencode({
    tag1Key = "terraform.io"
    tag2Key = "environment"
  })

  depends_on = [aws_config_configuration_recorder.config]
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  service_role_path = "/service-role/"

  drs_managed_policy_arns = {
    agent              = "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryAgentPolicy"
    failback           = "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryFailbackPolicy"
    conversion_server  = "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryConversionServerPolicy"
    recovery_instance  = "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryRecoveryInstancePolicy"
    replication_server = "arn:${local.partition}:iam::aws:policy/service-role/AWSElasticDisasterRecoveryReplicationServerPolicy"
  }

  ssm_managed_instance_core_arn = "arn:${local.partition}:iam::aws:policy/AmazonSSMManagedInstanceCore"

  ec2_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    ManagedBy = "terraform"
    Service   = "AWSElasticDisasterRecovery"
  }
}

###############################################################################
# AWSElasticDisasterRecoveryAgentRole
###############################################################################

resource "aws_iam_role" "agent" {
  name        = "AWSElasticDisasterRecoveryAgentRole"
  path        = local.service_role_path
  description = "Role assumed by AWS Elastic Disaster Recovery to install and manage the replication agent on source servers."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowElasticDisasterRecoveryServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity"
        ]
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          StringLike = {
            "sts:SourceIdentity" = "s-*"
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "agent" {
  role       = aws_iam_role.agent.name
  policy_arn = local.drs_managed_policy_arns.agent
}

###############################################################################
# AWSElasticDisasterRecoveryFailbackRole
###############################################################################

resource "aws_iam_role" "failback" {
  name        = "AWSElasticDisasterRecoveryFailbackRole"
  path        = local.service_role_path
  description = "Role assumed by AWS Elastic Disaster Recovery to perform failback of recovery instances."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowElasticDisasterRecoveryServiceToAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "drs.amazonaws.com"
        }
        Action = [
          "sts:AssumeRole",
          "sts:SetSourceIdentity"
        ]
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          StringLike = {
            "sts:SourceIdentity" = "i-*"
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "failback" {
  role       = aws_iam_role.failback.name
  policy_arn = local.drs_managed_policy_arns.failback
}

###############################################################################
# AWSElasticDisasterRecoveryConversionServerRole
###############################################################################

resource "aws_iam_role" "conversion_server" {
  name               = "AWSElasticDisasterRecoveryConversionServerRole"
  path               = local.service_role_path
  description        = "Role assumed by the EC2 conversion servers used by AWS Elastic Disaster Recovery."
  assume_role_policy = local.ec2_assume_role_policy
  tags               = local.tags
}

resource "aws_iam_role_policy_attachment" "conversion_server" {
  role       = aws_iam_role.conversion_server.name
  policy_arn = local.drs_managed_policy_arns.conversion_server
}

###############################################################################
# AWSElasticDisasterRecoveryRecoveryInstanceRole
###############################################################################

resource "aws_iam_role" "recovery_instance" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceRole"
  path               = local.service_role_path
  description        = "Role assumed by AWS Elastic Disaster Recovery recovery instances."
  assume_role_policy = local.ec2_assume_role_policy
  tags               = local.tags
}

resource "aws_iam_role_policy_attachment" "recovery_instance" {
  role       = aws_iam_role.recovery_instance.name
  policy_arn = local.drs_managed_policy_arns.recovery_instance
}

###############################################################################
# AWSElasticDisasterRecoveryReplicationServerRole
###############################################################################

resource "aws_iam_role" "replication_server" {
  name               = "AWSElasticDisasterRecoveryReplicationServerRole"
  path               = local.service_role_path
  description        = "Role assumed by the AWS Elastic Disaster Recovery replication servers."
  assume_role_policy = local.ec2_assume_role_policy
  tags               = local.tags
}

resource "aws_iam_role_policy_attachment" "replication_server" {
  role       = aws_iam_role.replication_server.name
  policy_arn = local.drs_managed_policy_arns.replication_server
}

###############################################################################
# AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole
###############################################################################

resource "aws_iam_role" "recovery_instance_with_launch_actions" {
  name               = "AWSElasticDisasterRecoveryRecoveryInstanceWithLaunchActionsRole"
  path               = local.service_role_path
  description        = "Role assumed by AWS Elastic Disaster Recovery recovery instances that run post-launch actions and require SSM access."
  assume_role_policy = local.ec2_assume_role_policy
  tags               = local.tags
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_actions_drs" {
  role       = aws_iam_role.recovery_instance_with_launch_actions.name
  policy_arn = local.drs_managed_policy_arns.recovery_instance
}

resource "aws_iam_role_policy_attachment" "recovery_instance_with_launch_actions_ssm" {
  role       = aws_iam_role.recovery_instance_with_launch_actions.name
  policy_arn = local.ssm_managed_instance_core_arn
}

###############################################################################
# AWSElasticDisasterRecoveryInitializerRole
###############################################################################

resource "aws_iam_role" "initializer" {
  name        = "AWSElasticDisasterRecoveryInitializerRole"
  path        = "/"
  description = "Role assumed by the initializing identity to set up AWS Elastic Disaster Recovery."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowCurrentCallingIdentityToAssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "aws:userid" = data.aws_caller_identity.current.user_id
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_policy" "initialize" {
  name        = "AWSElasticDisasterRecoveryInitializerPolicy"
  path        = "/"
  description = "Allows initialization of AWS Elastic Disaster Recovery, including instance profile management, role pass-through and creation of the required service roles."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "InitializeService"
        Effect   = "Allow"
        Action   = ["drs:InitializeService"]
        Resource = "*"
      },
      {
        Sid      = "CreateElasticDisasterRecoveryServiceLinkedRole"
        Effect   = "Allow"
        Action   = ["iam:CreateServiceLinkedRole"]
        Resource = [
          "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/drs.amazonaws.com/AWSServiceRoleForElasticDisasterRecovery"
        ]
        Condition = {
          StringEquals = {
            "iam:AWSServiceName" = "drs.amazonaws.com"
          }
        }
      },
      {
        Sid    = "ManageInstanceProfiles"
        Effect = "Allow"
        Action = [
          "iam:CreateInstanceProfile",
          "iam:DeleteInstanceProfile",
          "iam:GetInstanceProfile",
          "iam:AddRoleToInstanceProfile",
          "iam:RemoveRoleFromInstanceProfile",
          "iam:ListInstanceProfiles",
          "iam:ListInstanceProfilesForRole",
          "iam:TagInstanceProfile",
          "iam:UntagInstanceProfile"
        ]
        Resource = [
          "arn:${local.partition}:iam::${local.account_id}:instance-profile/*"
        ]
      },
      {
        Sid      = "PassRoleToEc2AndElasticDisasterRecovery"
        Effect   = "Allow"
        Action   = ["iam:PassRole"]
        Resource = "*"
        Condition = {
          StringEquals = {
            "iam:PassedToService" = [
              "ec2.amazonaws.com",
              "drs.amazonaws.com"
            ]
          }
        }
      },
      {
        Sid      = "FullEc2Access"
        Effect   = "Allow"
        Action   = ["ec2:*"]
        Resource = "*"
      },
      {
        Sid    = "AttachElasticDisasterRecoveryManagedPolicies"
        Effect = "Allow"
        Action = [
          "iam:AttachRolePolicy",
          "iam:DetachRolePolicy"
        ]
        Resource = [
          "arn:${local.partition}:iam::${local.account_id}:role/service-role/AWSElasticDisasterRecovery*"
        ]
        Condition = {
          StringEquals = {
            "iam:PolicyARN" = values(local.drs_managed_policy_arns)
          }
        }
      }
    ]
  })

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "initializer" {
  role       = aws_iam_role.initializer.name
  policy_arn = aws_iam_policy.initialize.arn
}

###############################################################################
# Outputs
###############################################################################

output "service_role_arns" {
  description = "ARNs of the AWS Elastic Disaster Recovery service roles."
  value = {
    agent                                 = aws_iam_role.agent.arn
    failback                              = aws_iam_role.failback.arn
    conversion_server                     = aws_iam_role.conversion_server.arn
    recovery_instance                     = aws_iam_role.recovery_instance.arn
    replication_server                    = aws_iam_role.replication_server.arn
    recovery_instance_with_launch_actions = aws_iam_role.recovery_instance_with_launch_actions.arn
  }
}

output "initializer_role_arn" {
  description = "ARN of the AWS Elastic Disaster Recovery initializer role."
  value       = aws_iam_role.initializer.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  environment = "prod"

  azs = slice(data.aws_availability_zones.available.names, 0, 4)

  external_subnet_cidrs = ["10.41.0.0/24", "10.41.1.0/24", "10.41.2.0/24", "10.41.3.0/24"]
  external_subnet_names = ["Subnet0-1a", "Subnet1-1b", "Subnet2-1c", "Subnet3-1d"]

  internal_subnet_cidrs = ["10.40.0.0/24", "10.40.1.0/24", "10.40.2.0/24", "10.40.3.0/24"]
  internal_subnet_names = ["Subnet0-1a", "Subnet1-1b", "Subnet2-1c", "Subnet3-1d"]
}

# ---------------------------------------------------------------------------
# External VPC (public-facing)
# ---------------------------------------------------------------------------

resource "aws_vpc" "external" {
  cidr_block           = "10.41.0.0/16"
  instance_tenancy     = "default"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name        = "Production External"
    purpose     = "Production External VPC"
    environment = local.environment
  }
}

resource "aws_default_security_group" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "Production External"
    environment = local.environment
  }
}

resource "aws_subnet" "external" {
  count = 4

  vpc_id            = aws_vpc.external.id
  cidr_block        = local.external_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name        = local.external_subnet_names[count.index]
    environment = local.environment
  }
}

resource "aws_internet_gateway" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "External GW"
    environment = local.environment
  }
}

resource "aws_route_table" "external" {
  vpc_id = aws_vpc.external.id

  tags = {
    Name        = "External Route Table"
    environment = local.environment
  }
}

resource "aws_route" "external_default" {
  route_table_id         = aws_route_table.external.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.external.id
}

resource "aws_main_route_table_association" "external" {
  vpc_id         = aws_vpc.external.id
  route_table_id = aws_route_table.external.id
}

resource "aws_route_table_association" "external" {
  count = 4

  subnet_id      = aws_subnet.external[count.index].id
  route_table_id = aws_route_table.external.id
}

resource "aws_default_network_acl" "external" {
  default_network_acl_id = aws_vpc.external.default_network_acl_id

  ingress {
    protocol   = "all"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  egress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    protocol   = "all"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  subnet_ids = aws_subnet.external[*].id

  tags = {
    Name        = "Production External"
    environment = local.environment
  }
}

# ---------------------------------------------------------------------------
# Internal VPC (isolated)
# ---------------------------------------------------------------------------

resource "aws_vpc" "internal" {
  cidr_block       = "10.40.0.0/16"
  instance_tenancy = "default"

  tags = {
    Name        = "Production Internal"
    purpose     = "Production Internal VPC"
    environment = local.environment
  }
}

resource "aws_default_security_group" "internal" {
  vpc_id = aws_vpc.internal.id

  tags = {
    Name        = "Production Internal"
    environment = local.environment
  }
}

resource "aws_subnet" "internal" {
  count = 4

  vpc_id            = aws_vpc.internal.id
  cidr_block        = local.internal_subnet_cidrs[count.index]
  availability_zone = local.azs[count.index]

  tags = {
    Name        = local.internal_subnet_names[count.index]
    environment = local.environment
  }
}

resource "aws_default_network_acl" "internal" {
  default_network_acl_id = aws_vpc.internal.default_network_acl_id

  ingress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    protocol   = "icmp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
    icmp_type  = -1
    icmp_code  = -1
  }

  egress {
    protocol   = "all"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  subnet_ids = aws_subnet.internal[*].id

  tags = {
    Name        = "Production Internal"
    environment = local.environment
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0.0"
    }
  }
}

variable "resource_prefix" {
  description = "Prefix applied to all resource names"
  type        = string
  default     = "n8n"
}

variable "certificate_arn" {
  description = "Optional ACM certificate ARN for the HTTPS listener"
  type        = string
  default     = null
}

variable "url" {
  description = "Optional override for the WEBHOOK_URL environment variable"
  type        = string
  default     = null
}

variable "desired_count" {
  description = "Desired number of ECS tasks"
  type        = number
  default     = 1
}

variable "container_image" {
  description = "Container image for n8n"
  type        = string
  default     = "n8nio/n8n:1.4.0"
}

variable "fargate_type" {
  description = "Fargate capacity provider type"
  type        = string
  default     = "FARGATE_SPOT"
}

data "aws_availability_zones" "available" {
  state = "available"
}

data "aws_region" "current" {}

locals {
  private_subnet_cidrs = ["10.0.0.0/24", "10.0.1.0/24", "10.0.2.0/24"]
  public_subnet_cidrs  = ["10.0.4.0/24", "10.0.5.0/24", "10.0.6.0/24"]

  certificate_arn = var.certificate_arn != null ? var.certificate_arn : one(aws_acm_certificate.n8n[*].arn)
  webhook_url     = var.url != null ? var.url : "https://${aws_lb.n8n.dns_name}"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "${var.resource_prefix}-vpc"
  }
}

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.resource_prefix}-private-${count.index}"
  }
}

resource "aws_subnet" "public" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = {
    Name = "${var.resource_prefix}-public-${count.index}"
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.resource_prefix}-igw"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = {
    Name = "${var.resource_prefix}-public-rt"
  }
}

resource "aws_route_table_association" "public" {
  count          = 3
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "${var.resource_prefix}-private-rt"
  }
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

resource "aws_security_group" "alb" {
  name        = "${var.resource_prefix}-alb-sg"
  description = "Allow inbound HTTP and HTTPS to the load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Outbound within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.resource_prefix}-alb-sg"
  }
}

resource "aws_security_group" "ecs_tasks" {
  name        = "${var.resource_prefix}-ecs-tasks-sg"
  description = "Allow n8n traffic only from the load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "n8n container port from ALB"
    from_port       = 5678
    to_port         = 5678
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "Outbound within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.resource_prefix}-ecs-tasks-sg"
  }
}

resource "aws_security_group" "efs" {
  name        = "${var.resource_prefix}-efs-sg"
  description = "Allow NFS traffic from the VPC"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "NFS from VPC CIDR"
    from_port   = 2049
    to_port     = 2049
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Outbound within VPC"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = {
    Name = "${var.resource_prefix}-efs-sg"
  }
}

resource "tls_private_key" "n8n" {
  count     = var.certificate_arn == null ? 1 : 0
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "tls_self_signed_cert" "n8n" {
  count                 = var.certificate_arn == null ? 1 : 0
  private_key_pem       = tls_private_key.n8n[0].private_key_pem
  validity_period_hours = 8760

  subject {
    common_name  = "${var.resource_prefix}.internal"
    organization = "n8n"
  }

  allowed_uses = [
    "key_encipherment",
    "digital_signature",
    "server_auth",
  ]
}

resource "aws_acm_certificate" "n8n" {
  count            = var.certificate_arn == null ? 1 : 0
  certificate_body = tls_self_signed_cert.n8n[0].cert_pem
  private_key      = tls_private_key.n8n[0].private_key_pem
}

resource "aws_lb" "n8n" {
  name                       = "${var.resource_prefix}-alb"
  internal                   = true
  load_balancer_type         = "application"
  security_groups            = [aws_security_group.alb.id]
  subnets                    = aws_subnet.public[*].id
  drop_invalid_header_fields = true

  tags = {
    Name = "${var.resource_prefix}-alb"
  }
}

resource "aws_lb_target_group" "n8n" {
  name                 = "${var.resource_prefix}-tg"
  port                 = 80
  protocol             = "HTTP"
  vpc_id               = aws_vpc.main.id
  target_type          = "ip"
  deregistration_delay = 30

  health_check {
    path                = "/healthz"
    protocol            = "HTTP"
    matcher             = "200"
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 3
    interval            = 30
  }

  lifecycle {
    create_before_destroy = true
  }

  tags = {
    Name = "${var.resource_prefix}-tg"
  }
}

resource "aws_lb_listener" "https" {
  load_balancer_arn = aws_lb.n8n.arn
  port              = 443
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-TLS13-1-2-2021-06"
  certificate_arn   = local.certificate_arn

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.n8n.arn
  }
}

resource "aws_lb_listener" "http" {
  load_balancer_arn = aws_lb.n8n.arn
  port              = 80
  protocol          = "HTTP"

  default_action {
    type = "redirect"

    redirect {
      port        = "443"
      protocol    = "HTTPS"
      status_code = "HTTP_301"
    }
  }
}

resource "aws_efs_file_system" "n8n" {
  creation_token = "${var.resource_prefix}-efs"
  encrypted      = true

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name = "${var.resource_prefix}-efs"
  }
}

resource "aws_efs_access_point" "n8n" {
  file_system_id = aws_efs_file_system.n8n.id

  posix_user {
    uid = 1000
    gid = 1000
  }

  root_directory {
    path = "/n8n"

    creation_info {
      owner_uid   = 1000
      owner_gid   = 1000
      permissions = "777"
    }
  }

  tags = {
    Name = "${var.resource_prefix}-efs-ap"
  }
}

resource "aws_efs_mount_target" "n8n" {
  count           = 3
  file_system_id  = aws_efs_file_system.n8n.id
  subnet_id       = aws_subnet.private[count.index].id
  security_groups = [aws_security_group.efs.id]
}

resource "aws_cloudwatch_log_group" "n8n" {
  name              = "${var.resource_prefix}-logs"
  retention_in_days = 1

  tags = {
    Name = "${var.resource_prefix}-logs"
  }
}

resource "aws_iam_role" "task_execution" {
  name = "${var.resource_prefix}-task-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role" "task" {
  name = "${var.resource_prefix}-task-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ecs-tasks.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_execution_logs" {
  name = "${var.resource_prefix}-task-execution-logs"
  role = aws_iam_role.task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_logs" {
  name = "${var.resource_prefix}-task-logs"
  role = aws_iam_role.task.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams"
        ]
        Resource = [
          aws_cloudwatch_log_group.n8n.arn,
          "${aws_cloudwatch_log_group.n8n.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy" "task_execution_efs" {
  name = "${var.resource_prefix}-task-execution-efs"
  role = aws_iam_role.task_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "elasticfilesystem:ClientMount",
          "elasticfilesystem:ClientWrite",
          "elasticfilesystem:DescribeMountTargets",
          "elasticfilesystem:DescribeFileSystems",
          "elasticfilesystem:DescribeAccessPoints"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_ecs_cluster" "n8n" {
  name = "${var.resource_prefix}-cluster"

  setting {
    name  = "containerInsights"
    value = "disabled"
  }

  tags = {
    Name = "${var.resource_prefix}-cluster"
  }
}

resource "aws_ecs_cluster_capacity_providers" "n8n" {
  cluster_name       = aws_ecs_cluster.n8n.name
  capacity_providers = [var.fargate_type]

  default_capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }
}

resource "aws_ecs_task_definition" "n8n" {
  family                   = "${var.resource_prefix}-task"
  requires_compatibilities = ["FARGATE"]
  network_mode             = "awsvpc"
  cpu                      = 256
  memory                   = 512
  execution_role_arn       = aws_iam_role.task_execution.arn
  task_role_arn            = aws_iam_role.task.arn

  volume {
    name = "n8n-data"

    efs_volume_configuration {
      file_system_id     = aws_efs_file_system.n8n.id
      transit_encryption = "ENABLED"

      authorization_config {
        access_point_id = aws_efs_access_point.n8n.id
        iam             = "ENABLED"
      }
    }
  }

  container_definitions = jsonencode([
    {
      name      = "n8n"
      image     = var.container_image
      essential = true

      portMappings = [
        {
          containerPort = 5678
          hostPort      = 5678
          protocol      = "tcp"
        }
      ]

      environment = [
        {
          name  = "N8N_SKIP_WEBHOOK_DEREGISTRATION_SHUTDOWN"
          value = "true"
        },
        {
          name  = "WEBHOOK_URL"
          value = local.webhook_url
        }
      ]

      mountPoints = [
        {
          sourceVolume  = "n8n-data"
          containerPath = "/home/node/.n8n"
          readOnly      = false
        }
      ]

      logConfiguration = {
        logDriver = "awslogs"
        options = {
          "awslogs-group"         = aws_cloudwatch_log_group.n8n.name
          "awslogs-region"        = data.aws_region.current.region
          "awslogs-stream-prefix" = "n8n"
        }
      }
    }
  ])

  tags = {
    Name = "${var.resource_prefix}-task"
  }
}

resource "aws_ecs_service" "n8n" {
  name            = "${var.resource_prefix}-service"
  cluster         = aws_ecs_cluster.n8n.id
  task_definition = aws_ecs_task_definition.n8n.arn
  desired_count   = var.desired_count

  capacity_provider_strategy {
    capacity_provider = var.fargate_type
    base              = 1
    weight            = 100
  }

  network_configuration {
    subnets          = aws_subnet.public[*].id
    security_groups  = [aws_security_group.ecs_tasks.id]
    assign_public_ip = true
  }

  load_balancer {
    target_group_arn = aws_lb_target_group.n8n.arn
    container_name   = "n8n"
    container_port   = 5678
  }

  depends_on = [
    aws_lb_listener.https,
    aws_lb_listener.http,
    aws_efs_mount_target.n8n,
  ]

  tags = {
    Name = "${var.resource_prefix}-service"
  }
}

locals {
  vpc_cidr = "10.255.0.0/16"

  common_tags = {
    Application = "dosomething-quasar"
    Environment = "production"
    Stack       = "data"
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

# ---------------------------------------------------------------------------
# VPC
# ---------------------------------------------------------------------------
resource "aws_vpc" "quasar" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "Quasar"
  })
}

# ---------------------------------------------------------------------------
# Subnets (multi-AZ RDS)
# ---------------------------------------------------------------------------
resource "aws_subnet" "rds_1a" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.100.0/24"
  availability_zone = data.aws_availability_zones.available.names[0]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1A"
  })
}

resource "aws_subnet" "rds_1e" {
  vpc_id            = aws_vpc.quasar.id
  cidr_block        = "10.255.101.0/24"
  availability_zone = data.aws_availability_zones.available.names[1]

  tags = merge(local.common_tags, {
    Name = "Quasar RDS - 1E"
  })
}

# ---------------------------------------------------------------------------
# Security Group: Bastion
# ---------------------------------------------------------------------------
resource "aws_security_group" "bastion" {
  name        = "Quasar-Bastion"
  description = "Bastion host access"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "SSH from admin range"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["203.0.113.0/24"]
  }

  egress {
    description = "Internal VPC egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Bastion"
  })
}

# ---------------------------------------------------------------------------
# Security Group: HA Proxy
# ---------------------------------------------------------------------------
resource "aws_security_group" "ha_proxy" {
  name        = "Quasar-HA-Proxy"
  description = "HA proxy load balancer access"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description = "HTTPS from anywhere"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "SSH from bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  egress {
    description = "Internal VPC egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-HA-Proxy"
  })
}

# ---------------------------------------------------------------------------
# Security Group: Jenkins
# ---------------------------------------------------------------------------
resource "aws_security_group" "jenkins" {
  name        = "Quasar-Jenkins"
  description = "Jenkins CI/CD automation access"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description     = "SSH from bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "HTTP alternate port from HA proxy"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.ha_proxy.id]
  }

  egress {
    description = "Internal VPC egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-Jenkins"
  })
}

# ---------------------------------------------------------------------------
# Security Group: ETL
# ---------------------------------------------------------------------------
resource "aws_security_group" "etl" {
  name        = "Quasar-ETL"
  description = "ETL compute node access"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description     = "SSH from bastion"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.bastion.id]
  }

  ingress {
    description     = "SSH from Jenkins"
    from_port       = 22
    to_port         = 22
    protocol        = "tcp"
    security_groups = [aws_security_group.jenkins.id]
  }

  egress {
    description = "Internal VPC egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-ETL"
  })
}

# ---------------------------------------------------------------------------
# Security Group: PostgreSQL
# ---------------------------------------------------------------------------
resource "aws_security_group" "postgresql" {
  name        = "Quasar-PostgreSQL"
  description = "PostgreSQL database access"
  vpc_id      = aws_vpc.quasar.id

  ingress {
    description = "PostgreSQL from anywhere"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    description     = "PostgreSQL from ETL"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.etl.id]
  }

  egress {
    description = "Internal VPC egress"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [local.vpc_cidr]
  }

  tags = merge(local.common_tags, {
    Name = "Quasar-PostgreSQL"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    local = {
      source  = "hashicorp/local"
      version = "~> 2.0"
    }
    null = {
      source  = "hashicorp/null"
      version = "~> 3.0"
    }
  }
}

variable "create" {
  description = "Global creation control for the CodeDeploy Lambda blue/green pipeline resources."
  type        = bool
  default     = true
}

variable "function_name" {
  description = "Name of the AWS Lambda function that is deployed."
  type        = string
  default     = ""
}

variable "alias_name" {
  description = "Name of the Lambda function alias used for blue/green traffic shifting."
  type        = string
  default     = "live"
}

variable "current_version" {
  description = "Current published Lambda function version (blue)."
  type        = string
  default     = ""
}

variable "target_version" {
  description = "Target published Lambda function version (green)."
  type        = string
  default     = ""
}

variable "before_allow_traffic_hook_arn" {
  description = "Optional ARN of the Lambda function invoked before traffic is allowed."
  type        = string
  default     = null
}

variable "after_allow_traffic_hook_arn" {
  description = "Optional ARN of the Lambda function invoked after traffic is allowed."
  type        = string
  default     = null
}

variable "app_name" {
  description = "Name of the CodeDeploy application (created or pre-existing)."
  type        = string
  default     = ""
}

variable "create_app" {
  description = "Whether to create a new CodeDeploy application."
  type        = bool
  default     = false
}

variable "use_existing_app" {
  description = "Whether to use an existing CodeDeploy application instead of creating one."
  type        = bool
  default     = false
}

variable "deployment_group_name" {
  description = "Name of the CodeDeploy deployment group (created or pre-existing)."
  type        = string
  default     = ""
}

variable "create_deployment_group" {
  description = "Whether to create a new CodeDeploy deployment group."
  type        = bool
  default     = false
}

variable "use_existing_deployment_group" {
  description = "Whether to use an existing CodeDeploy deployment group instead of creating one."
  type        = bool
  default     = false
}

variable "deployment_config_name" {
  description = "Name of the CodeDeploy deployment configuration used by the deployment group."
  type        = string
  default     = "CodeDeployDefault.LambdaAllAtOnce"
}

variable "enable_automatic_rollback" {
  description = "Whether automatic rollbacks are enabled for the deployment group."
  type        = bool
  default     = true
}

variable "rollback_events" {
  description = "Deployment events that trigger an automatic rollback."
  type        = list(string)
  default     = ["DEPLOYMENT_STOP_ON_ALARM"]
}

variable "enable_alarm_monitoring" {
  description = "Whether CloudWatch alarm monitoring is enabled for the deployment group."
  type        = bool
  default     = false
}

variable "alarm_names" {
  description = "CloudWatch alarms used for deployment monitoring."
  type        = list(string)
  default     = []
}

variable "ignore_poll_alarm_failure" {
  description = "Whether the deployment proceeds when the CloudWatch alarms cannot be polled."
  type        = bool
  default     = false
}

variable "trigger_configurations" {
  description = "Notification triggers configured on the deployment group."
  type = list(object({
    trigger_events     = list(string)
    trigger_name       = string
    trigger_target_arn = string
  }))
  default = []
}

variable "create_codedeploy_role" {
  description = "Whether to create the CodeDeploy IAM service role."
  type        = bool
  default     = true
}

variable "codedeploy_role_name" {
  description = "Name of the CodeDeploy IAM service role."
  type        = string
  default     = "codedeploy-lambda-blue-green-role"
}

variable "codedeploy_role_arn" {
  description = "ARN of an existing CodeDeploy role used when create_codedeploy_role is false."
  type        = string
  default     = null
}

variable "codedeploy_service_principals" {
  description = "Service principals allowed to assume the CodeDeploy role."
  type        = list(string)
  default     = ["codedeploy.amazonaws.com"]
}

variable "codedeploy_managed_policy_name" {
  description = "AWS managed policy attached to the CodeDeploy role when attach_managed_policy is true."
  type        = string
  default     = "AWSCodeDeployRoleForLambda"
}

variable "attach_managed_policy" {
  description = "Whether to additionally attach the AWS-managed CodeDeploy policy to the role (opt-in, off by default)."
  type        = bool
  default     = false
}

variable "attach_hooks_policy" {
  description = "Whether to attach an inline policy granting lambda:InvokeFunction on the lifecycle hooks."
  type        = bool
  default     = true
}

variable "attach_triggers_policy" {
  description = "Whether to attach an inline policy granting sns:Publish on the trigger targets."
  type        = bool
  default     = false
}

variable "create_deployment" {
  description = "Whether to build the AppSpec revision and deployment shell script."
  type        = bool
  default     = false
}

variable "run_deployment" {
  description = "Whether to execute the deployment through a null_resource local-exec provisioner."
  type        = bool
  default     = false
}

variable "save_deploy_script" {
  description = "Whether to persist the generated deployment script locally."
  type        = bool
  default     = false
}

variable "deploy_script_path" {
  description = "Relative path where the generated deployment script is saved."
  type        = string
  default     = "deploy_lambda.sh"
}

variable "aws_cli_command" {
  description = "AWS CLI command used by the generated deployment script."
  type        = string
  default     = "aws"
}

variable "get_deployment_sleep_timer" {
  description = "Seconds to sleep between deployment status polls."
  type        = number
  default     = 5
}

variable "monitor_deployment" {
  description = "Whether to wait for the deployment to reach a terminal status."
  type        = bool
  default     = true
}

variable "force_deploy" {
  description = "Whether to force a new deployment run on every apply using a uuid-based trigger."
  type        = bool
  default     = false
}

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  create_app              = var.create && var.create_app && !var.use_existing_app
  create_deployment_group = var.create && var.create_deployment_group && !var.use_existing_deployment_group
  create_role             = var.create && var.create_codedeploy_role

  service_role_arn = try(aws_iam_role.codedeploy[0].arn, var.codedeploy_role_arn)

  app_name              = try(aws_codedeploy_app.this[0].name, var.app_name)
  deployment_group_name = try(aws_codedeploy_deployment_group.this[0].deployment_group_name, var.deployment_group_name)

  partition = data.aws_partition.current.partition
  region    = data.aws_region.current.name
  account   = data.aws_caller_identity.current.account_id

  hook_arns = compact([
    var.before_allow_traffic_hook_arn,
    var.after_allow_traffic_hook_arn,
  ])

  trigger_arns = distinct([
    for trigger in var.trigger_configurations : trigger.trigger_target_arn
  ])

  create_hooks_policy    = local.create_role && var.attach_hooks_policy && length(local.hook_arns) > 0
  create_triggers_policy = local.create_role && var.attach_triggers_policy && length(local.trigger_arns) > 0

  lambda_function_arn = "arn:${local.partition}:lambda:${local.region}:${local.account}:function:${var.function_name}"

  lambda_resources = var.function_name != "" ? [
    local.lambda_function_arn,
    "${local.lambda_function_arn}:*",
  ] : ["*"]

  codedeploy_app_arn = "arn:${local.partition}:codedeploy:${local.region}:${local.account}:application:${local.app_name}"

  codedeploy_resources = local.app_name != "" ? [
    local.codedeploy_app_arn,
    "arn:${local.partition}:codedeploy:${local.region}:${local.account}:deploymentgroup:${local.app_name}/*",
    "arn:${local.partition}:codedeploy:${local.region}:${local.account}:deploymentconfig:*",
  ] : ["*"]

  appspec_hooks = concat(
    var.before_allow_traffic_hook_arn != null ? [{ BeforeAllowTraffic = var.before_allow_traffic_hook_arn }] : [],
    var.after_allow_traffic_hook_arn != null ? [{ AfterAllowTraffic = var.after_allow_traffic_hook_arn }] : [],
  )

  appspec = {
    version = "0.0"
    Resources = [
      {
        (var.function_name) = {
          Type = "AWS::Lambda::Function"
          Properties = {
            Name           = var.function_name
            Alias          = var.alias_name
            CurrentVersion = var.current_version
            TargetVersion  = var.target_version
          }
        }
      }
    ]
    Hooks = local.appspec_hooks
  }

  appspec_json = jsonencode(local.appspec)

  revision_json = jsonencode({
    revisionType = "AppSpecContent"
    appSpecContent = {
      content = local.appspec_json
    }
  })

  deploy_script = <<-EOT
    #!/usr/bin/env bash
    set -euo pipefail

    APP_NAME='${local.app_name}'
    DEPLOYMENT_GROUP_NAME='${local.deployment_group_name}'
    REVISION='${local.revision_json}'

    echo "Creating CodeDeploy deployment..."
    echo "  Application:      $APP_NAME"
    echo "  Deployment group: $DEPLOYMENT_GROUP_NAME"

    DEPLOYMENT_ID=$(${var.aws_cli_command} deploy create-deployment \
      --application-name "$APP_NAME" \
      --deployment-group-name "$DEPLOYMENT_GROUP_NAME" \
      --revision "$REVISION" \
      --query 'deploymentId' \
      --output text)

    echo "Deployment ID: $DEPLOYMENT_ID"

    if [ "${var.monitor_deployment}" = "true" ]; then
      echo "Monitoring deployment status..."
      while true; do
        DEPLOYMENT_STATUS=$(${var.aws_cli_command} deploy get-deployment \
          --deployment-id "$DEPLOYMENT_ID" \
          --query 'deploymentInfo.status' \
          --output text)

        echo "  Status: $DEPLOYMENT_STATUS"

        case "$DEPLOYMENT_STATUS" in
          Succeeded)
            echo "Deployment succeeded."
            break
            ;;
          Failed|Stopped|StoppedByUser)
            echo "Deployment ended with terminal status: $DEPLOYMENT_STATUS" >&2
            exit 1
            ;;
          *)
            sleep ${var.get_deployment_sleep_timer}
            ;;
        esac
      done
    fi

    echo "Done. Deployment ID: $DEPLOYMENT_ID"
    EOT
}

data "aws_iam_policy_document" "codedeploy_assume_role" {
  statement {
    sid     = "CodeDeployAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = var.codedeploy_service_principals
    }
  }
}

data "aws_iam_policy_document" "codedeploy_lambda_deployment" {
  count = local.create_role ? 1 : 0

  statement {
    sid    = "LambdaDeploymentPermissions"
    effect = "Allow"
    actions = [
      "lambda:GetFunction",
      "lambda:GetFunctionConfiguration",
      "lambda:GetFunctionCodeSigningConfig",
      "lambda:GetAlias",
      "lambda:ListAliases",
      "lambda:ListVersionsByFunction",
      "lambda:UpdateFunctionCode",
      "lambda:UpdateFunctionConfiguration",
      "lambda:UpdateAlias",
      "lambda:PublishVersion",
      "lambda:InvokeFunction",
    ]
    resources = local.lambda_resources
  }

  statement {
    sid    = "CodeDeployDeploymentPermissions"
    effect = "Allow"
    actions = [
      "codedeploy:GetApplication",
      "codedeploy:GetApplicationRevision",
      "codedeploy:RegisterApplicationRevision",
      "codedeploy:GetDeployment",
      "codedeploy:GetDeploymentConfig",
      "codedeploy:CreateDeployment",
    ]
    resources = local.codedeploy_resources
  }
}

data "aws_iam_policy_document" "hooks" {
  count = local.create_hooks_policy ? 1 : 0

  statement {
    sid       = "AllowInvokeLambdaLifecycleHooks"
    effect    = "Allow"
    actions   = ["lambda:InvokeFunction"]
    resources = local.hook_arns
  }
}

data "aws_iam_policy_document" "triggers" {
  count = local.create_triggers_policy ? 1 : 0

  statement {
    sid       = "AllowPublishToTriggerTargets"
    effect    = "Allow"
    actions   = ["sns:Publish"]
    resources = local.trigger_arns
  }
}

resource "aws_iam_role" "codedeploy" {
  count              = local.create_role ? 1 : 0
  name               = var.codedeploy_role_name
  description        = "IAM role that allows CodeDeploy to perform Lambda blue/green deployments."
  assume_role_policy = data.aws_iam_policy_document.codedeploy_assume_role.json
}

resource "aws_iam_policy" "codedeploy_lambda_deployment" {
  count       = local.create_role ? 1 : 0
  name        = "${var.codedeploy_role_name}-lambda-deployment-policy"
  description = "Customer-managed policy granting the permissions CodeDeploy requires to perform Lambda blue/green deployments."
  policy      = data.aws_iam_policy_document.codedeploy_lambda_deployment[0].json
}

resource "aws_iam_role_policy_attachment" "codedeploy_lambda_deployment" {
  count      = local.create_role ? 1 : 0
  role       = aws_iam_role.codedeploy[0].name
  policy_arn = aws_iam_policy.codedeploy_lambda_deployment[0].arn
}

resource "aws_iam_role_policy_attachment" "codedeploy_managed" {
  count      = local.create_role && var.attach_managed_policy ? 1 : 0
  role       = aws_iam_role.codedeploy[0].name
  policy_arn = "arn:${data.aws_partition.current.partition}:iam::aws:policy/${var.codedeploy_managed_policy_name}"
}

resource "aws_iam_role_policy" "hooks" {
  count  = local.create_hooks_policy ? 1 : 0
  name   = "codedeploy-lambda-hooks-policy"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.hooks[0].json
}

resource "aws_iam_role_policy" "triggers" {
  count  = local.create_triggers_policy ? 1 : 0
  name   = "codedeploy-triggers-policy"
  role   = aws_iam_role.codedeploy[0].id
  policy = data.aws_iam_policy_document.triggers[0].json
}

resource "aws_codedeploy_app" "this" {
  count            = local.create_app ? 1 : 0
  name             = var.app_name
  compute_platform = "Lambda"
}

resource "aws_codedeploy_deployment_group" "this" {
  count                  = local.create_deployment_group ? 1 : 0
  app_name               = local.app_name
  deployment_group_name  = var.deployment_group_name
  service_role_arn       = local.service_role_arn
  deployment_config_name = var.deployment_config_name

  deployment_style {
    deployment_option = "WITH_TRAFFIC_CONTROL"
    deployment_type   = "BLUE_GREEN"
  }

  auto_rollback_configuration {
    enabled = var.enable_automatic_rollback
    events  = var.rollback_events
  }

  dynamic "alarm_configuration" {
    for_each = var.enable_alarm_monitoring ? [1] : []
    content {
      enabled                   = true
      alarms                    = var.alarm_names
      ignore_poll_alarm_failure = var.ignore_poll_alarm_failure
    }
  }

  dynamic "trigger_configuration" {
    for_each = var.trigger_configurations
    content {
      trigger_events     = trigger_configuration.value.trigger_events
      trigger_name       = trigger_configuration.value.trigger_name
      trigger_target_arn = trigger_configuration.value.trigger_target_arn
    }
  }
}

resource "local_file" "deploy_script" {
  count           = var.create && var.create_deployment && var.save_deploy_script ? 1 : 0
  filename        = "${path.module}/${var.deploy_script_path}"
  content         = local.deploy_script
  file_permission = "0755"
}

resource "null_resource" "deploy" {
  count = var.create && var.create_deployment && var.run_deployment ? 1 : 0

  triggers = {
    function_name   = var.function_name
    alias_name      = var.alias_name
    current_version = var.current_version
    target_version  = var.target_version
    force_deploy    = var.force_deploy ? uuid() : "static"
  }

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = local.deploy_script
  }

  depends_on = [local_file.deploy_script]
}

output "codedeploy_app_name" {
  description = "Name of the CodeDeploy application in use."
  value       = local.app_name
}

output "codedeploy_deployment_group_name" {
  description = "Name of the CodeDeploy deployment group in use."
  value       = local.deployment_group_name
}

output "codedeploy_role_arn" {
  description = "ARN of the CodeDeploy service role in use."
  value       = local.service_role_arn
}

output "codedeploy_policy_arn" {
  description = "ARN of the customer-managed CodeDeploy for Lambda policy in use."
  value       = try(aws_iam_policy.codedeploy_lambda_deployment[0].arn, null)
}

output "appspec_json" {
  description = "AppSpec JSON revision used for the deployment."
  value       = local.appspec_json
}

output "deploy_script" {
  description = "Generated deployment shell script."
  value       = var.create && var.create_deployment ? local.deploy_script : null
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "vpc_cidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "internal_domain_name" {
  description = "Internal DNS domain name used by DHCP options and the private hosted zone."
  type        = string
  default     = "internal"
}

variable "dhcp_domain_name_servers" {
  description = "DNS resolvers advertised via DHCP options (AmazonProvidedDNS is the VPC resolver)."
  type        = list(string)
  default     = ["AmazonProvidedDNS", "8.8.8.8"]
}

variable "admin_cidrs" {
  description = "List of administrator CIDR blocks allowed to SSH via the Home SSH security group."
  type        = list(string)
  default     = ["203.0.113.0/24"]
}

###############################################################################
# Locals
###############################################################################

locals {
  vpc_name = "main"

  subnet_cidrs = {
    reserved   = "10.0.0.0/24"
    sandbox    = "10.0.1.0/24"
    web        = "10.0.2.0/24"
    database   = "10.0.3.0/24"
    gameserver = "10.0.4.0/22"
  }

  common_tags = {
    ManagedBy = "terraform"
  }

  game_ports = [27015, 27020]

  ephemeral_from = 32768
  ephemeral_to   = 65535
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

###############################################################################
# Internet Gateway
###############################################################################

resource "aws_internet_gateway" "ig" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "ig"
  })
}

###############################################################################
# DHCP Options
###############################################################################

resource "aws_vpc_dhcp_options" "main" {
  domain_name         = var.internal_domain_name
  domain_name_servers = var.dhcp_domain_name_servers

  tags = merge(local.common_tags, {
    Name = "main"
  })
}

resource "aws_vpc_dhcp_options_association" "main" {
  vpc_id          = aws_vpc.main.id
  dhcp_options_id = aws_vpc_dhcp_options.main.id
}

###############################################################################
# Private Route 53 Hosted Zone
###############################################################################

resource "aws_route53_zone" "internal" {
  name    = var.internal_domain_name
  comment = "Private hosted zone for the internal domain"

  vpc {
    vpc_id = aws_vpc.main.id
  }

  tags = merge(local.common_tags, {
    Name = var.internal_domain_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Subnets
###############################################################################

resource "aws_subnet" "reserved" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs.reserved
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "reserved"
  })
}

resource "aws_subnet" "sandbox" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs.sandbox
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "sandbox"
  })
}

resource "aws_subnet" "web" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs.web
  availability_zone       = data.aws_availability_zones.available.names[2]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "web"
  })
}

resource "aws_subnet" "database" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs.database
  availability_zone       = data.aws_availability_zones.available.names[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name = "database"
  })
}

resource "aws_subnet" "gameserver" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = local.subnet_cidrs.gameserver
  availability_zone       = data.aws_availability_zones.available.names[1]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
