###############################################################################
# Route Tables (one per subnet, default route via the internet gateway)
###############################################################################

resource "aws_route_table" "reserved" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(local.common_tags, {
    Name = "reserved"
  })
}

resource "aws_route_table_association" "reserved" {
  subnet_id      = aws_subnet.reserved.id
  route_table_id = aws_route_table.reserved.id
}

resource "aws_route_table" "sandbox" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(local.common_tags, {
    Name = "sandbox"
  })
}

resource "aws_route_table_association" "sandbox" {
  subnet_id      = aws_subnet.sandbox.id
  route_table_id = aws_route_table.sandbox.id
}

resource "aws_route_table" "web" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(local.common_tags, {
    Name = "web"
  })
}

resource "aws_route_table_association" "web" {
  subnet_id      = aws_subnet.web.id
  route_table_id = aws_route_table.web.id
}

resource "aws_route_table" "database" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(local.common_tags, {
    Name = "database"
  })
}

resource "aws_route_table_association" "database" {
  subnet_id      = aws_subnet.database.id
  route_table_id = aws_route_table.database.id
}

resource "aws_route_table" "gameserver" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.ig.id
  }

  tags = merge(local.common_tags, {
    Name = "gameserver"
  })
}

resource "aws_route_table_association" "gameserver" {
  subnet_id      = aws_subnet.gameserver.id
  route_table_id = aws_route_table.gameserver.id
}

###############################################################################
# Network ACL - sandbox (all TCP in and out)
###############################################################################

resource "aws_network_acl" "sandbox" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.sandbox.id]

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = merge(local.common_tags, {
    Name = "sandbox"
  })
}

###############################################################################
# Network ACL - web (SSH, HTTP, HTTPS, ephemeral in; all TCP out)
###############################################################################

resource "aws_network_acl" "web" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.web.id]

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 120
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 130
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = local.ephemeral_from
    to_port    = local.ephemeral_to
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = merge(local.common_tags, {
    Name = "web"
  })
}

###############################################################################
# Network ACL - database (TCP only to/from web and gameserver subnets)
###############################################################################

resource "aws_network_acl" "database" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.database.id]

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_subnet.web.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = aws_subnet.gameserver.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = aws_subnet.web.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = aws_subnet.gameserver.cidr_block
    from_port  = 0
    to_port    = 65535
  }

  tags = merge(local.common_tags, {
    Name = "database"
  })
}

###############################################################################
# Network ACL - gameserver (SSH, game ports, ephemeral in; all TCP/UDP out)
###############################################################################

resource "aws_network_acl" "gameserver" {
  vpc_id     = aws_vpc.main.id
  subnet_ids = [aws_subnet.gameserver.id]

  ingress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 22
    to_port    = 22
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = local.game_ports[0]
    to_port    = local.game_ports[0]
  }

  ingress {
    protocol   = "udp"
    rule_no    = 120
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = local.game_ports[0]
    to_port    = local.game_ports[0]
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 130
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = local.game_ports[1]
    to_port    = local.game_ports[1]
  }

  ingress {
    protocol   = "udp"
    rule_no    = 140
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = local.game_ports[1]
    to_port    = local.game_ports[1]
  }

  ingress {
    protocol   = "tcp"
    rule_no    = 150
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = local.ephemeral_from
    to_port    = local.ephemeral_to
  }

  ingress {
    protocol   = "udp"
    rule_no    = 160
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = local.ephemeral_from
    to_port    = local.ephemeral_to
  }

  egress {
    protocol   = "tcp"
    rule_no    = 100
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  egress {
    protocol   = "udp"
    rule_no    = 110
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 65535
  }

  tags = merge(local.common_tags, {
    Name = "gameserver"
  })
}

###############################################################################
# Security Group - Home SSH
###############################################################################

resource "aws_security_group" "home_ssh" {
  name        = "Home SSH"
  description = "Allow SSH from configured administrator CIDRs and from itself."
  vpc_id      = aws_vpc.main.id

  dynamic "ingress" {
    for_each = var.admin_cidrs
    content {
      description = "SSH from administrator CIDR"
      from_port   = 22
      to_port     = 22
      protocol    = "tcp"
      cidr_blocks = [ingress.value]
    }
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Home SSH"
  })
}

###############################################################################
# Security Group - Packer SSH
###############################################################################

resource "aws_security_group" "packer_ssh" {
  name        = "Packer SSH"
  description = "Allow SSH from the VPC CIDR and from itself."
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "SSH from the VPC CIDR"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "SSH from self"
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    self        = true
  }

  egress {
    description = "Outbound traffic restricted to the VPC CIDR"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "Packer SSH"
  })
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "ID of the main VPC."
  value       = aws_vpc.main.id
}

output "internet_gateway_id" {
  description = "ID of the internet gateway."
  value       = aws_internet_gateway.ig.id
}

output "subnet_ids" {
  description = "Map of subnet names to their IDs."
  value = {
    reserved   = aws_subnet.reserved.id
    sandbox    = aws_subnet.sandbox.id
    web        = aws_subnet.web.id
    database   = aws_subnet.database.id
    gameserver = aws_subnet.gameserver.id
  }
}

output "internal_hosted_zone_id" {
  description = "ID of the private Route 53 hosted zone for the internal domain."
  value       = aws_route53_zone.internal.zone_id
}

output "home_ssh_security_group_id" {
  description = "ID of the Home SSH security group."
  value       = aws_security_group.home_ssh.id
}

output "packer_ssh_security_group_id" {
  description = "ID of the Packer SSH security group."
  value       = aws_security_group.packer_ssh.id
}

variable "base_bucket_name" {
  description = "Base name of the S3 bucket."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "use_account_alias_prefix" {
  description = "Prefix the bucket name with the AWS IAM account alias."
  type        = bool
  default     = false
}

variable "use_random_suffix" {
  description = "Prefix the bucket name with a random suffix."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Additional JSON bucket policy to be merged into the managed policy."
  type        = string
  default     = ""
}

variable "enable_s3_public_access_block" {
  description = "Whether to enable the S3 public access block configuration."
  type        = bool
  default     = true
}

variable "object_ownership" {
  description = "Object ownership setting applied through ownership controls."
  type        = string
  default     = "BucketOwnerEnforced"
}

variable "kms_master_key_id" {
  description = "KMS key ARN/ID used to enable aws:kms encryption. Defaults to AES256 when null."
  type        = string
  default     = null
}

variable "bucket_key_enabled" {
  description = "Whether S3 bucket keys are enabled for the default encryption configuration."
  type        = bool
  default     = false
}

variable "versioning_status" {
  description = "Bucket versioning status (Enabled, Suspended, or Disabled)."
  type        = string
  default     = "Enabled"
}

variable "force_destroy" {
  description = "Whether all objects should be deleted so the bucket can be destroyed."
  type        = bool
  default     = false
}

variable "transition_default_minimum_object_size" {
  description = "Default minimum object size applied to lifecycle transitions."
  type        = string
  default     = "all_storage_classes_128K"
}

variable "enable_analytics" {
  description = "Whether to enable S3 storage class analytics."
  type        = bool
  default     = true
}

variable "enable_bucket_inventory" {
  description = "Whether to enable S3 bucket inventory reporting."
  type        = bool
  default     = false
}

variable "logging_bucket" {
  description = "External target bucket name for S3 server access logging."
  type        = string
  default     = null
}

variable "transfer_acceleration" {
  description = "Transfer acceleration status (Enabled or Suspended). Null disables the configuration."
  type        = string
  default     = null
}

variable "s3_bucket_acl" {
  description = "Canned ACL applied to the bucket when set."
  type        = string
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules applied to the bucket."
  type = list(object({
    id              = optional(string)
    allowed_headers = optional(list(string))
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string))
    max_age_seconds = optional(number)
  }))
  default = []
}

variable "tags" {
  description = "Tags applied to resources that support tagging."
  type        = map(string)
  default     = {}
}

###############################################################################
# Data sources
###############################################################################

data "aws_iam_account_alias" "current" {
  count = var.use_account_alias_prefix ? 1 : 0
}

###############################################################################
# Random suffix
###############################################################################

resource "random_id" "this" {
  count       = var.use_random_suffix ? 1 : 0
  byte_length = 4
}

###############################################################################
# Locals
###############################################################################

locals {
  account_alias = try(data.aws_iam_account_alias.current[0].account_alias, "")
  random_suffix = try(random_id.this[0].hex, "")

  name_prefix = (
    var.use_random_suffix
    ? local.random_suffix
    : (var.use_account_alias_prefix ? local.account_alias : "")
  )

  bucket_name = local.name_prefix != "" ? "${local.name_prefix}-${var.base_bucket_name}" : var.base_bucket_name

  sse_algorithm = var.kms_master_key_id != null ? "aws:kms" : "AES256"

  analytics_prefix = "_AWSBucketAnalytics/"
  inventory_prefix = "_AWSBucketInventory/"

  enable_logging = var.logging_bucket != null && var.logging_bucket != ""
}

###############################################################################
# Bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket        = local.bucket_name
  force_destroy = var.force_destroy

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "this" {
  count = var.enable_s3_public_access_block ? 1 : 0

  bucket = aws_s3_bucket.this.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_status
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.sse_algorithm
      kms_master_key_id = var.kms_master_key_id
    }

    bucket_key_enabled = var.bucket_key_enabled
  }
}

###############################################################################
# Lifecycle
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  transition_default_minimum_object_size = var.transition_default_minimum_object_size

  rule {
    id     = "abort-incomplete-multipart-upload"
    status = "Enabled"

    filter {}

    abort_incomplete_multipart_upload {
      days_after_initiation = 14
    }
  }

  rule {
    id     = "noncurrent-version-management"
    status = "Enabled"

    filter {}

    noncurrent_version_transition {
      noncurrent_days = 30
      storage_class   = "STANDARD_IA"
    }

    noncurrent_version_expiration {
      noncurrent_days = 365
    }
  }

  dynamic "rule" {
    for_each = var.enable_analytics ? [1] : []

    content {
      id     = "expire-analytics-exports"
      status = "Enabled"

      filter {
        prefix = local.analytics_prefix
      }

      expiration {
        days = 30
      }
    }
  }

  dynamic "rule" {
    for_each = var.enable_bucket_inventory ? [1] : []

    content {
      id     = "expire-inventory-reports"
      status = "Enabled"

      filter {
        prefix = local.inventory_prefix
      }

      expiration {
        days = 14
      }
    }
  }
}

###############################################################################
# Analytics
###############################################################################

resource "aws_s3_bucket_analytics_configuration" "this" {
  count = var.enable_analytics ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "EntireBucketAnalytics"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"

      destination {
        s3_bucket_destination {
          bucket_arn = aws_s3_bucket.this.arn
          format     = "CSV"
          prefix     = local.analytics_prefix
        }
      }
    }
  }
}

###############################################################################
# Inventory
###############################################################################

resource "aws_s3_bucket_inventory" "this" {
  count = var.enable_bucket_inventory ? 1 : 0

  bucket = aws_s3_bucket.this.id
  name   = "EntireBucketInventory"

  included_object_versions = "All"

  schedule {
    frequency = "Weekly"
  }

  filter {
    prefix = ""
  }

  optional_fields = [
    "Size",
    "LastModifiedDate",
    "StorageClass",
    "ETag",
    "IsMultipartUploaded",
    "ReplicationStatus",
    "EncryptionStatus",
  ]

  destination {
    bucket {
      format     = "ORC"
      bucket_arn = aws_s3_bucket.this.arn
      prefix     = local.inventory_prefix
    }
  }
}

###############################################################################
# Logging
###############################################################################

resource "aws_s3_bucket_logging" "this" {
  count = local.enable_logging ? 1 : 0

  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_bucket
  target_prefix = "s3/${aws_s3_bucket.this.id}/"
}

###############################################################################
# Transfer acceleration
###############################################################################

resource "aws_s3_bucket_accelerate_configuration" "this" {
  count = var.transfer_acceleration != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  status = var.transfer_acceleration
}

###############################################################################
# ACL
###############################################################################

resource "aws_s3_bucket_acl" "this" {
  count = var.s3_bucket_acl != null ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = var.s3_bucket_acl
}

###############################################################################
# CORS
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = length(var.cors_rules) > 0 ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = try(cors_rule.value.id, null)
      allowed_headers = try(cors_rule.value.allowed_headers, null)
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = try(cors_rule.value.expose_headers, null)
      max_age_seconds = try(cors_rule.value.max_age_seconds, null)
    }
  }
}

###############################################################################
# Bucket policy
###############################################################################

data "aws_iam_policy_document" "combined" {
  source_policy_documents = compact([var.custom_bucket_policy])

  statement {
    sid    = "denyInsecureTransport"
    effect = "Deny"

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  dynamic "statement" {
    for_each = var.enable_analytics ? [1] : []

    content {
      sid    = "allowS3AnalyticsDelivery"
      effect = "Allow"

      actions = ["s3:PutObject"]

      resources = ["${aws_s3_bucket.this.arn}/${local.analytics_prefix}*"]

      principals {
        type        = "Service"
        identifiers = ["s3.amazonaws.com"]
      }

      condition {
        test     = "StringEquals"
        variable = "s3:x-amz-acl"
        values   = ["bucket-owner-full-control"]
      }
    }
  }

  dynamic "statement" {
    for_each = var.enable_bucket_inventory ? [1] : []

    content {
      sid    = "allowS3InventoryDelivery"
      effect = "Allow"

      actions = ["s3:PutObject"]

      resources = ["${aws_s3_bucket.this.arn}/${local.inventory_prefix}*"]

      principals {
        type        = "Service"
        identifiers = ["s3.amazonaws.com"]
      }

      condition {
        test     = "StringEquals"
        variable = "s3:x-amz-acl"
        values   = ["bucket-owner-full-control"]
      }
    }
  }
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.combined.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# Outputs
###############################################################################

output "bucket_id" {
  description = "Name (ID) of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_domain_name" {
  description = "Bucket domain name."
  value       = aws_s3_bucket.this.bucket_domain_name
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.40.0"
    }
  }
}

data "aws_caller_identity" "current" {}

###############################################################################
# Variables
###############################################################################

variable "bucket_name" {
  description = "Name of the S3 bucket. Conflicts with name_prefix. Maximum 63 characters."
  type        = string
  default     = null

  validation {
    condition     = var.bucket_name == null || (length(var.bucket_name) >= 3 && length(var.bucket_name) <= 63)
    error_message = "The bucket name must be between 3 and 63 characters."
  }
}

variable "name_prefix" {
  description = "Prefix used to generate the S3 bucket name. Conflicts with bucket_name. Maximum 37 characters."
  type        = string
  default     = null

  validation {
    condition     = var.name_prefix == null || length(var.name_prefix) <= 37
    error_message = "The bucket name prefix must be 37 characters or less."
  }
}

variable "force_destroy" {
  description = "Whether all objects should be deleted from the bucket before the bucket is destroyed."
  type        = bool
  default     = false
}

variable "object_ownership" {
  description = "Object ownership setting for the bucket."
  type        = string
  default     = "BucketOwnerEnforced"

  validation {
    condition = contains(
      ["BucketOwnerPreferred", "ObjectWriter", "BucketOwnerEnforced"],
      var.object_ownership
    )
    error_message = "object_ownership must be one of BucketOwnerPreferred, ObjectWriter, or BucketOwnerEnforced."
  }
}

variable "block_public_acls" {
  description = "Whether Amazon S3 should block public ACLs for the bucket."
  type        = bool
  default     = true
}

variable "block_public_policy" {
  description = "Whether Amazon S3 should block public bucket policies for the bucket."
  type        = bool
  default     = true
}

variable "ignore_public_acls" {
  description = "Whether Amazon S3 should ignore public ACLs for the bucket."
  type        = bool
  default     = true
}

variable "restrict_public_buckets" {
  description = "Whether Amazon S3 should restrict public bucket policies for the bucket."
  type        = bool
  default     = true
}

variable "kms_key_arn" {
  description = "Optional KMS key ARN used for default bucket encryption. When set, SSE-KMS with bucket keys is enabled."
  type        = string
  default     = null
}

variable "versioning_enabled" {
  description = "Whether versioning is enabled for the bucket. Defaults to Suspended when false."
  type        = bool
  default     = false
}

variable "custom_bucket_policy" {
  description = "Optional custom IAM policy document (JSON) merged into the bucket policy."
  type        = string
  default     = null
}

variable "logging_source_bucket_arns" {
  description = "Source bucket ARNs permitted to deliver server access logs to this bucket via logging.s3.amazonaws.com."
  type        = list(string)
  default     = []
}

variable "enable_eventbridge_notifications" {
  description = "Whether to send S3 event notifications to Amazon EventBridge."
  type        = bool
  default     = false
}

variable "logging_target_bucket" {
  description = "Target bucket name for server access logging. When set, server access logging is enabled."
  type        = string
  default     = null
}

variable "logging_target_prefix" {
  description = "Prefix applied to server access log object keys."
  type        = string
  default     = null
}

variable "object_lock_enabled" {
  description = "Whether S3 Object Lock is enabled for the bucket."
  type        = bool
  default     = false
}

variable "object_lock_mode" {
  description = "Default Object Lock retention mode (GOVERNANCE or COMPLIANCE)."
  type        = string
  default     = "GOVERNANCE"

  validation {
    condition     = contains(["GOVERNANCE", "COMPLIANCE"], var.object_lock_mode)
    error_message = "object_lock_mode must be either GOVERNANCE or COMPLIANCE."
  }
}

variable "object_lock_days" {
  description = "Default Object Lock retention in days."
  type        = number
  default     = 30
}

variable "object_lock_years" {
  description = "Default Object Lock retention in years. When set, takes precedence over object_lock_days."
  type        = number
  default     = null
}

variable "cors_rules" {
  description = "List of CORS rules applied to the bucket."
  type = list(object({
    id              = optional(string, null)
    allowed_headers = optional(list(string), [])
    allowed_methods = list(string)
    allowed_origins = list(string)
    expose_headers  = optional(list(string), [])
    max_age_seconds = optional(number, null)
  }))
  default = []
}

variable "lifecycle_rules" {
  description = "List of lifecycle management rules applied to the bucket."
  type = list(object({
    id      = string
    enabled = optional(bool, true)
    prefix  = optional(string, null)

    expiration = optional(object({
      days = optional(number, null)
    }), null)

    transitions = optional(list(object({
      days          = number
      storage_class = string
    })), [])

    noncurrent_version_expiration = optional(object({
      days = optional(number, null)
    }), null)

    noncurrent_version_transitions = optional(list(object({
      days          = number
      storage_class = string
    })), [])

    abort_incomplete_multipart_upload_days = optional(number, null)
  }))
  default = []
}

variable "inventory_configurations" {
  description = "List of S3 inventory configurations."
  type = list(object({
    name                     = string
    included_object_versions = string
    schedule_frequency       = string
    destination_bucket_arn   = string
    destination_prefix       = optional(string, null)
    destination_format       = string
    encryption_type          = optional(string, "sse_s3")
    kms_key_arn              = optional(string, null)
    optional_fields          = optional(list(string), [])
    filter_prefix            = optional(string, null)
  }))
  default = []

  validation {
    condition = alltrue([
      for c in var.inventory_configurations :
      contains(["CSV", "ORC", "Parquet"], upper(c.destination_format))
    ])
    error_message = "destination_format must be one of CSV, ORC, or Parquet."
  }

  validation {
    condition = alltrue([
      for c in var.inventory_configurations :
      contains(["sse_s3", "sse_kms"], lower(c.encryption_type))
    ])
    error_message = "encryption_type must be either sse_s3 or sse_kms."
  }
}

variable "replication_configurations" {
  description = "List of cross-region replication rules."
  type = list(object({
    id                               = string
    priority                         = number
    status                           = optional(string, "Enabled")
    destination_bucket_arn           = string
    storage_class                    = optional(string, null)
    replica_kms_key_arn              = optional(string, null)
    metrics_enabled                  = optional(bool, false)
    delete_marker_replication_status = optional(string, null)
    filter_prefix                    = optional(string, null)

    source_selection_criteria = optional(object({
      sse_kms_encrypted_objects_status = optional(string, null)
      replica_modifications_status     = optional(string, null)
    }), null)
  }))
  default = []
}

###############################################################################
# Locals
###############################################################################

locals {
  bucket_identifier = coalesce(var.bucket_name, var.name_prefix, "enterprise-s3")

  encryption_kms_enabled = var.kms_key_arn != null && var.kms_key_arn != ""

  logging_enabled = var.logging_target_bucket != null

  replication_enabled = length(var.replication_configurations) > 0

  lifecycle_enabled = length(var.lifecycle_rules) > 0

  cors_enabled = length(var.cors_rules) > 0

  object_lock_retention_days = var.object_lock_years == null ? var.object_lock_days : null

  replication_destination_object_arns = [
    for r in var.replication_configurations : "${r.destination_bucket_arn}/*"
  ]
}

###############################################################################
# S3 Bucket
###############################################################################

resource "aws_s3_bucket" "this" {
  bucket        = var.bucket_name
  bucket_prefix = var.bucket_name == null ? local.bucket_identifier : null
  force_destroy = var.force_destroy

  object_lock_enabled = var.object_lock_enabled

  tags = {
    Name = local.bucket_identifier
  }

  lifecycle {
    prevent_destroy = true

    precondition {
      condition     = (var.bucket_name != null && var.name_prefix == null) || var.bucket_name == null
      error_message = "Provide at most one of bucket_name or name_prefix."
    }
  }
}

###############################################################################
# Ownership Controls and Conditional ACL
###############################################################################

resource "aws_s3_bucket_ownership_controls" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    object_ownership = var.object_ownership
  }
}

resource "aws_s3_bucket_acl" "this" {
  count = var.object_ownership == "ObjectWriter" ? 1 : 0

  bucket = aws_s3_bucket.this.id
  acl    = "private"

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

###############################################################################
# Public Access Block
###############################################################################

resource "aws_s3_bucket_public_access_block" "this" {
  bucket = aws_s3_bucket.this.id

  block_public_acls       = var.block_public_acls
  block_public_policy     = var.block_public_policy
  ignore_public_acls      = var.ignore_public_acls
  restrict_public_buckets = var.restrict_public_buckets
}

###############################################################################
# Server-Side Encryption
###############################################################################

resource "aws_s3_bucket_server_side_encryption_configuration" "this" {
  bucket = aws_s3_bucket.this.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = local.encryption_kms_enabled ? "aws:kms" : "AES256"
      kms_master_key_id = local.encryption_kms_enabled ? var.kms_key_arn : null
    }

    bucket_key_enabled = local.encryption_kms_enabled
  }
}

###############################################################################
# Versioning
###############################################################################

resource "aws_s3_bucket_versioning" "this" {
  bucket = aws_s3_bucket.this.id

  versioning_configuration {
    status = var.versioning_enabled ? "Enabled" : "Suspended"
  }
}

###############################################################################
# Bucket Policy
###############################################################################

data "aws_iam_policy_document" "bucket_policy" {
  statement {
    sid    = "EnforceSecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.this.arn,
      "${aws_s3_bucket.this.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  dynamic "statement" {
    for_each = length(var.logging_source_bucket_arns) > 0 ? [1] : []

    content {
      sid    = "AllowS3ServerAccessLogging"
      effect = "Allow"

      principals {
        type        = "Service"
        identifiers = ["logging.s3.amazonaws.com"]
      }

      actions = ["s3:PutObject"]

      resources = ["${aws_s3_bucket.this.arn}/*"]

      condition {
        test     = "StringEquals"
        variable = "aws:SourceAccount"
        values   = [data.aws_caller_identity.current.account_id]
      }

      condition {
        test     = "ArnLike"
        variable = "aws:SourceArn"
        values   = var.logging_source_bucket_arns
      }
    }
  }

  source_policy_documents = var.custom_bucket_policy != null ? [var.custom_bucket_policy] : []
}

resource "aws_s3_bucket_policy" "this" {
  bucket = aws_s3_bucket.this.id
  policy = data.aws_iam_policy_document.bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.this]
}

###############################################################################
# EventBridge Notifications
###############################################################################

resource "aws_s3_bucket_notification" "this" {
  count = var.enable_eventbridge_notifications ? 1 : 0

  bucket      = aws_s3_bucket.this.id
  eventbridge = true
}

###############################################################################
# Server Access Logging
###############################################################################

resource "aws_s3_bucket_logging" "this" {
  count = local.logging_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  target_bucket = var.logging_target_bucket
  target_prefix = var.logging_target_prefix

  lifecycle {
    precondition {
      condition     = !var.object_lock_enabled
      error_message = "Server access logging cannot be enabled when Object Lock is configured."
    }
  }
}

###############################################################################
# Object Lock Configuration
###############################################################################

resource "aws_s3_bucket_object_lock_configuration" "this" {
  count = var.object_lock_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  rule {
    default_retention {
      mode  = var.object_lock_mode
      days  = local.object_lock_retention_days
      years = var.object_lock_years
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]

  lifecycle {
    precondition {
      condition     = !local.logging_enabled
      error_message = "Object Lock cannot be configured when server access logging is enabled."
    }
  }
}

###############################################################################
# CORS Configuration
###############################################################################

resource "aws_s3_bucket_cors_configuration" "this" {
  count = local.cors_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "cors_rule" {
    for_each = var.cors_rules

    content {
      id              = cors_rule.value.id
      allowed_headers = cors_rule.value.allowed_headers
      allowed_methods = cors_rule.value.allowed_methods
      allowed_origins = cors_rule.value.allowed_origins
      expose_headers  = cors_rule.value.expose_headers
      max_age_seconds = cors_rule.value.max_age_seconds
    }
  }

  depends_on = [aws_s3_bucket_ownership_controls.this]
}

###############################################################################
# Lifecycle Configuration
###############################################################################

resource "aws_s3_bucket_lifecycle_configuration" "this" {
  count = local.lifecycle_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id

  dynamic "rule" {
    for_each = var.lifecycle_rules

    content {
      id     = rule.value.id
      status = rule.value.enabled ? "Enabled" : "Disabled"

      filter {
        prefix = rule.value.prefix != null ? rule.value.prefix : ""
      }

      dynamic "expiration" {
        for_each = rule.value.expiration != null ? [rule.value.expiration] : []

        content {
          days = expiration.value.days
        }
      }

      dynamic "transition" {
        for_each = rule.value.transitions

        content {
          days          = transition.value.days
          storage_class = transition.value.storage_class
        }
      }

      dynamic "noncurrent_version_expiration" {
        for_each = rule.value.noncurrent_version_expiration != null ? [rule.value.noncurrent_version_expiration] : []

        content {
          noncurrent_days = noncurrent_version_expiration.value.days
        }
      }

      dynamic "noncurrent_version_transition" {
        for_each = rule.value.noncurrent_version_transitions

        content {
          noncurrent_days = noncurrent_version_transition.value.days
          storage_class   = noncurrent_version_transition.value.storage_class
        }
      }

      dynamic "abort_incomplete_multipart_upload" {
        for_each = rule.value.abort_incomplete_multipart_upload_days != null ? [rule.value.abort_incomplete_multipart_upload_days] : []

        content {
          days_after_initiation = abort_incomplete_multipart_upload.value
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_versioning.this]
}

###############################################################################
# Inventory Configuration
###############################################################################

resource "aws_s3_bucket_inventory" "this" {
  for_each = { for c in var.inventory_configurations : c.name => c }

  bucket                   = aws_s3_bucket.this.id
  name                     = each.value.name
  included_object_versions = each.value.included_object_versions
  optional_fields          = each.value.optional_fields

  schedule {
    frequency = each.value.schedule_frequency
  }

  dynamic "filter" {
    for_each = each.value.filter_prefix != null ? [each.value.filter_prefix] : []

    content {
      prefix = filter.value
    }
  }

  destination {
    bucket {
      account_id = data.aws_caller_identity.current.account_id
      bucket_arn = each.value.destination_bucket_arn
      prefix     = each.value.destination_prefix
      format     = upper(each.value.destination_format)

      dynamic "encryption" {
        for_each = [lower(each.value.encryption_type)]

        content {
          dynamic "sse_s3" {
            for_each = encryption.value == "sse_s3" ? [1] : []

            content {}
          }

          dynamic "sse_kms" {
            for_each = encryption.value == "sse_kms" ? [1] : []

            content {
              key_id = each.value.kms_key_arn
            }
          }
        }
      }
    }
  }

  depends_on = [aws_s3_bucket_policy.this]
}

###############################################################################
# Replication IAM Role and Policy
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "replication_permissions" {
  statement {
    sid    = "ReplicationSourceBucketPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.this.arn]
  }

  statement {
    sid    = "ReplicationSourceObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.this.arn}/*"]
  }

  statement {
    sid    = "ReplicationDestinationObjectPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = local.replication_destination_object_arns
  }
}

resource "aws_iam_role" "replication" {
  count = local.replication_enabled ? 1 : 0

  name               = "${local.bucket_identifier}-replication"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json
}

resource "aws_iam_role_policy" "replication" {
  count = local.replication_enabled ? 1 : 0

  name   = "${local.bucket_identifier}-replication-policy"
  role   = aws_iam_role.replication[0].id
  policy = data.aws_iam_policy_document.replication_permissions.json
}

###############################################################################
# Cross-Region Replication Configuration
###############################################################################

resource "aws_s3_bucket_replication_configuration" "this" {
  count = local.replication_enabled ? 1 : 0

  bucket = aws_s3_bucket.this.id
  role   = aws_iam_role.replication[0].arn

  dynamic "rule" {
    for_each = var.replication_configurations

    content {
      id       = rule.value.id
      priority = rule.value.priority
      status   = rule.value.status

      dynamic "filter" {
        for_each = rule.value.filter_prefix != null ? [rule.value.filter_prefix] : []

        content {
          prefix = filter.value
        }
      }

      dynamic "delete_marker_replication" {
        for_each = rule.value.delete_marker_replication_status != null ? [rule.value.delete_marker_replication_status] : []

        content {
          status = delete_marker_replication.value
        }
      }

      destination {
        bucket        = rule.value.destination_bucket_arn
        storage_class = rule.value.storage_class

        dynamic "encryption_configuration" {
          for_each = rule.value.replica_kms_key_arn != null ? [rule.value.replica_kms_key_arn] : []

          content {
            replica_kms_key_id = encryption_configuration.value
          }
        }

        dynamic "metrics" {
          for_each = rule.value.metrics_enabled ? [1] : []

          content {
            status = "Enabled"
          }
        }
      }

      dynamic "source_selection_criteria" {
        for_each = rule.value.source_selection_criteria != null ? [rule.value.source_selection_criteria] : []

        content {
          dynamic "sse_kms_encrypted_objects" {
            for_each = source_selection_criteria.value.sse_kms_encrypted_objects_status != null ? [source_selection_criteria.value.sse_kms_encrypted_objects_status] : []

            content {
              status = sse_kms_encrypted_objects.value
            }
          }

          dynamic "replica_modifications" {
            for_each = source_selection_criteria.value.replica_modifications_status != null ? [source_selection_criteria.value.replica_modifications_status] : []

            content {
              status = replica_modifications.value
            }
          }
        }
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.this,
    aws_iam_role_policy.replication,
  ]

  lifecycle {
    precondition {
      condition     = var.versioning_enabled
      error_message = "Bucket versioning must be enabled to configure cross-region replication."
    }
  }
}

###############################################################################
# Outputs
###############################################################################

output "bucket_id" {
  description = "The name of the S3 bucket."
  value       = aws_s3_bucket.this.id
}

output "bucket_arn" {
  description = "The ARN of the S3 bucket."
  value       = aws_s3_bucket.this.arn
}

output "bucket_regional_domain_name" {
  description = "The regional domain name of the S3 bucket."
  value       = aws_s3_bucket.this.bucket_regional_domain_name
}

output "replication_role_arn" {
  description = "The ARN of the IAM role used for replication."
  value       = try(aws_iam_role.replication[0].arn, null)
}

variable "group_name_prefix" {
  description = "Prefix used to name the developer and admin IAM groups."
  type        = string
  default     = "app"
}

variable "s3_bucket_region" {
  description = "The single AWS region in which developers are permitted to create S3 buckets."
  type        = string
  default     = "us-east-1"
}

variable "remote_state_bucket_name" {
  description = "Name of the S3 bucket that holds Terraform remote state and must be inaccessible to developers."
  type        = string
  default     = "app-terraform-remote-state"
}

locals {
  account_id       = data.aws_caller_identity.current.account_id
  partition        = data.aws_partition.current.partition
  developer_group  = "${var.group_name_prefix}_developer"
  admin_group      = "${var.group_name_prefix}_admin"
  admin_role_name  = "admin"
  remote_state_arn = "arn:${local.partition}:s3:::${var.remote_state_bucket_name}"
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Account-wide password policy
###############################################################################

resource "aws_iam_account_password_policy" "baseline" {
  minimum_password_length        = 12
  require_lowercase_characters   = true
  require_uppercase_characters   = true
  require_numbers                = true
  require_symbols                = true
  allow_users_to_change_password = true
  password_reuse_prevention      = 24
  max_password_age               = 90
}

###############################################################################
# Account-level S3 public access block
###############################################################################

resource "aws_s3_account_public_access_block" "account" {
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

###############################################################################
# IAM groups
###############################################################################

resource "aws_iam_group" "developer" {
  name = local.developer_group
}

resource "aws_iam_group" "admin" {
  name = local.admin_group
}

###############################################################################
# Developer group - AWS managed policies
###############################################################################

resource "aws_iam_group_policy_attachment" "developer_iam_read_only" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/IAMReadOnlyAccess"
}

resource "aws_iam_group_policy_attachment" "developer_change_password" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/IAMUserChangePassword"
}

resource "aws_iam_group_policy_attachment" "developer_ssh_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/IAMUserSSHKeys"
}

###############################################################################
# Developer group - self service access keys
###############################################################################

resource "aws_iam_policy" "developer_self_manage_access_keys" {
  name        = "${var.group_name_prefix}_developer_self_manage_access_keys"
  description = "Allows developers to manage their own IAM access keys."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ManageOwnAccessKeys"
        Effect = "Allow"
        Action = [
          "iam:CreateAccessKey",
          "iam:DeleteAccessKey",
          "iam:ListAccessKeys",
          "iam:UpdateAccessKey"
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_self_manage_access_keys" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_self_manage_access_keys.arn
}

###############################################################################
# Developer group - self service virtual MFA devices (MFA required to deactivate)
###############################################################################

resource "aws_iam_policy" "developer_self_manage_mfa" {
  name        = "${var.group_name_prefix}_developer_self_manage_mfa"
  description = "Allows developers to manage their own virtual MFA devices. Deactivation requires MFA."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowManageOwnVirtualMFADevice"
        Effect = "Allow"
        Action = [
          "iam:CreateVirtualMFADevice",
          "iam:DeleteVirtualMFADevice"
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:mfa/$${aws:username}"
      },
      {
        Sid    = "AllowManageOwnUserMFA"
        Effect = "Allow"
        Action = [
          "iam:EnableMFADevice",
          "iam:ListMFADevices",
          "iam:ResyncMFADevice"
        ]
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
      },
      {
        Sid      = "AllowDeactivateMFADevice"
        Effect   = "Allow"
        Action   = "iam:DeactivateMFADevice"
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "DenyDeactivateMFADeviceWithoutMFA"
        Effect   = "Deny"
        Action   = "iam:DeactivateMFADevice"
        Resource = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_self_manage_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_self_manage_mfa.arn
}

###############################################################################
# Developer group - MFA gated S3 access
###############################################################################

resource "aws_iam_policy" "developer_s3_mfa" {
  name        = "${var.group_name_prefix}_developer_s3_mfa"
  description = "MFA gated S3 access, restricting bucket creation to a single region and blocking the remote-state bucket."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowS3WithMFA"
        Effect = "Allow"
        Action = [
          "s3:AbortMultipartUpload",
          "s3:DeleteObject",
          "s3:GetBucketLocation",
          "s3:GetBucketPolicy",
          "s3:GetObject",
          "s3:ListAllMyBuckets",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:ListMultipartUploadParts",
          "s3:PutObject"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "DenyS3WithoutMFA"
        Effect   = "Deny"
        Action   = "s3:*"
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      },
      {
        Sid      = "DenyCreateBucketOutsideDesignatedRegion"
        Effect   = "Deny"
        Action   = "s3:CreateBucket"
        Resource = "*"
        Condition = {
          StringNotEquals = {
            "aws:RequestedRegion" = var.s3_bucket_region
          }
        }
      },
      {
        Sid    = "DenyAccessToRemoteStateBucket"
        Effect = "Deny"
        Action = "s3:*"
        Resource = [
          local.remote_state_arn,
          "${local.remote_state_arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_s3_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_s3_mfa.arn
}

###############################################################################
# Developer group - MFA gated EC2 / ELB / CloudWatch / AutoScaling access
###############################################################################

resource "aws_iam_policy" "developer_services_mfa" {
  name        = "${var.group_name_prefix}_developer_services_mfa"
  description = "MFA gated access to EC2, ELB, CloudWatch and AutoScaling, including specific service-linked roles."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowServicesWithMFA"
        Effect = "Allow"
        Action = [
          "ec2:*",
          "elasticloadbalancing:*",
          "cloudwatch:*",
          "autoscaling:*"
        ]
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "AllowServiceLinkedRolesWithMFA"
        Effect   = "Allow"
        Action   = "iam:CreateServiceLinkedRole"
        Resource = [
          "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/autoscaling.amazonaws.com/AWSServiceRoleForAutoScaling",
          "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/ec2.application-autoscaling.amazonaws.com/AWSServiceRoleForApplicationAutoScaling_EC2SpotFleetRequest",
          "arn:${local.partition}:iam::${local.account_id}:role/aws-service-role/spot.amazonaws.com/AWSServiceRoleForEC2Spot"
        ]
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid    = "DenyServicesWithoutMFA"
        Effect = "Deny"
        Action = [
          "ec2:*",
          "elasticloadbalancing:*",
          "cloudwatch:*",
          "autoscaling:*"
        ]
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "developer_services_mfa" {
  group      = aws_iam_group.developer.name
  policy_arn = aws_iam_policy.developer_services_mfa.arn
}

###############################################################################
# Administrative role assumable by the account root principal
###############################################################################

resource "aws_iam_role" "admin" {
  name        = local.admin_role_name
  description = "Administrative role assumable by the account root principal with MFA."

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "AllowRootToAssumeAdminRoleWithMFA"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action = "sts:AssumeRole"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_policy" "admin_full_access_mfa" {
  name        = "${var.group_name_prefix}_admin_full_access_mfa"
  description = "Full administrative access, only when MFA is present."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "FullAdministrativeAccessWithMFA"
        Effect   = "Allow"
        Action   = "*"
        Resource = "*"
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      },
      {
        Sid      = "DenyAllWithoutMFA"
        Effect   = "Deny"
        Action   = "*"
        Resource = "*"
        Condition = {
          BoolIfExists = {
            "aws:MultiFactorAuthPresent" = "false"
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "admin_full_access_mfa" {
  role       = aws_iam_role.admin.name
  policy_arn = aws_iam_policy.admin_full_access_mfa.arn
}

###############################################################################
# Admin group - permission to assume the admin role when MFA is present
###############################################################################

resource "aws_iam_policy" "admin_group_assume_admin_role" {
  name        = "${var.group_name_prefix}_admin_group_assume_admin_role"
  description = "Allows admin group members to assume the admin role when MFA is present."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "AllowAssumeAdminRoleWithMFA"
        Effect   = "Allow"
        Action   = "sts:AssumeRole"
        Resource = aws_iam_role.admin.arn
        Condition = {
          Bool = {
            "aws:MultiFactorAuthPresent" = "true"
          }
        }
      }
    ]
  })
}

resource "aws_iam_group_policy_attachment" "admin_assume_admin_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.admin_group_assume_admin_role.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

##############################################################################
# TerraForest :: data driven AWS CI/CD pipeline orchestration framework
#
# Everything in this stack is derived from a single YAML file whose path is
# supplied through the `config` variable.  Expected schema (all blocks are
# optional, sensible defaults are applied where possible):
#
#   s3:
#     artifact_bucket:    <string>     # CodePipeline artifact store bucket
#     build_cache_bucket: <string>     # CodeBuild S3 cache bucket
#     force_destroy:      <bool>
#
#   iam:
#     create_default_codepipeline_role: <bool>
#     default_codepipeline_role_name:   <string>   # created under /terraforest/
#
#   codestar_connections:
#     - name:          <string>
#       provider_type: Bitbucket | GitHub | GitHubEnterpriseServer
#       host_arn:      <string>            # GitHubEnterpriseServer only
#
#   codebuild_projects:
#     - name:            <string>
#       description:     <string>
#       service_role_arn: <string>
#       buildspec:       <string>
#       image:           <string>
#       compute_type:    <string>
#       privileged_mode: <bool>
#       environment_variables:
#         - name: <string>
#           value: <string>
#           type: PLAINTEXT | PARAMETER_STORE | SECRETS_MANAGER
#
#   pipelines:
#     - name:           <string>
#       pipeline_type:  V1 | V2
#       role_arn:       <string>            # optional, falls back to the managed role
#       artifact_bucket: <string>           # bucket key or explicit bucket name
#       source:
#         type: CodeCommit | S3 | ECR | CodeStar
#         # CodeCommit
#         repository_name: <string>
#         branch_name:     <string>
#         # S3
#         s3_bucket:       <string>
#         s3_object_key:   <string>
#         # ECR
#         image_tag:       <string>
#         # CodeStar
#         connection_name:    <string>
#         full_repository_id: <string>
#         output_artifact_format: <string>
#       stages:
#         - name: <string>
#           actions:
#             - name: <string>
#               type: Approval | CodeBuild | Lambda
#               input_artifacts:  [<string>]
#               output_artifacts: [<string>]
#               # Approval
#               custom_data: ...
#               notification_arn: ...
#               external_entity_link: ...
#               # CodeBuild
#               project_name: ...
#               primary_source: ...
#               environment_variables: [...]
#               # Lambda
#               function_name: ...
#               user_parameters: {...}
#
#   triggers:
#     - pipeline: <string>
#       name:     <string>
#       type:     CodeCommitBranch | CodeCommitTag | Schedule | EventPattern
#       enabled:  <bool>
#       # CodeCommitBranch / CodeCommitTag
#       repository_name: <string>
#       branch_name:     <string>
#       branch_names:    [<string>]
#       # Schedule
#       schedule_expression: <string>
#       # EventPattern
#       event_pattern: <map>
##############################################################################

variable "config" {
  description = "Path to the YAML configuration file driving the CI/CD framework. When empty or pointing to a non-existent file, a minimal built-in configuration is used so the module remains deployable standalone."
  type        = string
  default     = ""
}

variable "tags" {
  description = "Map of tags applied to every taggable resource created by this stack."
  type        = map(string)
  default     = {}
}

##############################################################################
# Static provider metadata
##############################################################################

data "aws_caller_identity" "current" {}
data "aws_region" "current" {}
data "aws_partition" "current" {}

##############################################################################
# Configuration parsing
##############################################################################

locals {
  # Operator supplied YAML wins when the path is set and resolves to a file;
  # otherwise fall back to a minimal built-in configuration so the module can
  # be planned/applied without any external input.
  raw_config = (
    var.config != "" && fileexists(var.config)
    ? yamldecode(file(var.config))
    : yamldecode(<<-EOT
        iam:
          create_default_codepipeline_role: true
        pipelines: []
        triggers: []
      EOT
    )
  )

  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.region
  partition  = data.aws_partition.current.partition

  # ---- S3 -----------------------------------------------------------------
  s3_config               = try(local.raw_config.s3, {})
  artifact_bucket_name    = try(local.s3_config.artifact_bucket, "terraforest-artifacts-${local.account_id}-${local.region}")
  build_cache_bucket_name = try(local.s3_config.build_cache_bucket, "terraforest-build-cache-${local.account_id}-${local.region}")

  managed_buckets = {
    artifact    = local.artifact_bucket_name
    build_cache = local.build_cache_bucket_name
  }

  managed_bucket_arns = distinct(flatten([
    for b in values(local.managed_buckets) : [
      "arn:${local.partition}:s3:::${b}",
      "arn:${local.partition}:s3:::${b}/*",
    ]
  ]))

  # ---- IAM ----------------------------------------------------------------
  iam_config                     = try(local.raw_config.iam, {})
  create_default_role            = try(local.iam_config.create_default_codepipeline_role, true)
  default_codepipeline_role_name = try(local.iam_config.default_codepipeline_role_name, "terraforest-codepipeline-role")

  default_codepipeline_role_arn = local.create_default_role ? aws_iam_role.default_codepipeline[0].arn : null

  # ---- CodeStar connections ----------------------------------------------
  codestar_connections     = try(local.raw_config.codestar_connections, [])
  codestar_connections_map = { for c in local.codestar_connections : c.name => c }
  codestar_connection_arns = [for c in aws_codestarconnections_connection.connections : c.arn]

  # ---- Pipelines ----------------------------------------------------------
  pipelines     = try(local.raw_config.pipelines, [])
  pipelines_map = { for p in local.pipelines : p.name => p }

  pipeline_role_arn = {
    for p in local.pipelines : p.name => try(p.role_arn, local.default_codepipeline_role_arn)
  }

  pipeline_artifact_bucket = {
    for p in local.pipelines : p.name => (
      try(p.artifact_bucket, null) == null ?
      local.artifact_bucket_name :
      contains(keys(local.managed_buckets), try(p.artifact_bucket, "")) ?
      local.managed_buckets[p.artifact_bucket] :
      p.artifact_bucket
    )
  }

  pipeline_artifact_bucket_arns = distinct(flatten([
    for b in values(local.pipeline_artifact_bucket) : [
      "arn:${local.partition}:s3:::${b}",
      "arn:${local.partition}:s3:::${b}/*",
    ]
  ]))

  # ---- CodeBuild ----------------------------------------------------------
  codebuild_projects     = try(local.raw_config.codebuild_projects, [])
  codebuild_projects_map = { for p in local.codebuild_projects : p.name => p }
  create_codebuild_role  = length(local.codebuild_projects) > 0

  # ---- Source resolution --------------------------------------------------
  source_provider = {
    for p in local.pipelines : p.name => (
      try(p.source.type, "") == "S3" ? "S3" :
      try(p.source.type, "") == "ECR" ? "ECR" :
      try(p.source.type, "") == "CodeStar" ? "CodeStarSourceConnection" :
      "CodeCommit"
    )
  }

  source_configuration = {
    for p in local.pipelines : p.name => {
      for k, v in {
        RepositoryName = try(p.source.repository_name, null)
        BranchName = contains(["CodeCommit", "CodeStar"], try(p.source.type, "")) ? try(
          p.source.branch_name, "main"
        ) : null
        PollForSourceChanges = contains(["CodeCommit", "S3"], try(p.source.type, "")) ? tostring(
          try(p.source.poll_for_source_changes, false)
        ) : null
        S3Bucket    = try(p.source.type, "") == "S3" ? try(p.source.s3_bucket, null) : null
        S3ObjectKey = try(p.source.type, "") == "S3" ? try(p.source.s3_object_key, null) : null
        ImageTag    = try(p.source.type, "") == "ECR" ? try(p.source.image_tag, "latest") : null
        ConnectionArn = try(p.source.type, "") == "CodeStar" ? (
          try(aws_codestarconnections_connection.connections[p.source.connection_name].arn, null)
        ) : null
        FullRepositoryId = try(p.source.type, "") == "CodeStar" ? try(
          p.source.full_repository_id, null
        ) : null
        OutputArtifactFormat = try(p.source.output_artifact_format, null)
      } : k => v if v != null
    }
  }

  # ---- Action / stage normalization --------------------------------------
  action_type_map = {
    Approval  = { category = "Approval", owner = "AWS", provider = "Manual", version = "1" }
    CodeBuild = { category = "Build", owner = "AWS", provider = "CodeBuild", version = "1" }
    Lambda    = { category = "Invoke", owner = "AWS", provider = "Lambda", version = "1" }
  }

  pipeline_stages = {
    for p in local.pipelines : p.name => [
      for s in try(p.stages, []) : {
        name = s.name
        actions = [
          for a in try(s.actions, []) : {
            name             = a.name
            category         = local.action_type_map[try(a.type, "CodeBuild")].category
            owner            = local.action_type_map[try(a.type, "CodeBuild")].owner
            provider         = local.action_type_map[try(a.type, "CodeBuild")].provider
            version          = local.action_type_map[try(a.type, "CodeBuild")].version
            input_artifacts  = try(a.input_artifacts, [])
            output_artifacts = try(a.output_artifacts, [])
            run_order        = try(a.run_order, null)
            namespace        = try(a.namespace, null)
            configuration = {
              for k, v in {
                CustomData = try(a.type, "CodeBuild") == "Approval" ? try(
                  a.custom_data, null
                ) : null
                NotificationArn = try(a.type, "CodeBuild") == "Approval" ? try(
                  a.notification_arn, null
                ) : null
                ExternalEntityLink = try(a.type, "CodeBuild") == "Approval" ? try(
                  a.external_entity_link, null
                ) : null
                ProjectName = try(a.type, "CodeBuild") == "CodeBuild" ? try(
                  a.project_name, null
                ) : null
                PrimarySource = try(a.type, "CodeBuild") == "CodeBuild" ? try(
                  a.primary_source, null
                ) : null
                EnvironmentVariables = try(a.type, "CodeBuild") == "CodeBuild" ? (
                  try(a.environment_variables, null) != null ? jsonencode([
                    for ev in a.environment_variables : {
                      name  = ev.name
                      value = ev.value
                      type  = try(ev.type, "PLAINTEXT")
                    }
                  ]) : null
                ) : null
                BatchSize = try(a.type, "CodeBuild") == "CodeBuild" ? (
                  try(a.batch_size, null) != null ? tostring(a.batch_size) : null
                ) : null
                FunctionName = try(a.type, "CodeBuild") == "Lambda" ? try(
                  a.function_name, null
                ) : null
                UserParameters = try(a.type, "CodeBuild") == "Lambda" ? (
                  try(a.user_parameters, null) != null ? jsonencode(a.user_parameters) : null
                ) : null
              } : k => v if v != null
            }
          }
        ]
      }
    ]
  }

  # ---- EventBridge triggers ----------------------------------------------
  triggers_raw = try(local.raw_config.triggers, [])

  triggers_filtered = [
    for t in local.triggers_raw : t
    if contains(keys(local.pipelines_map), t.pipeline)
  ]

  trigger_map = {
    for idx, t in local.triggers_filtered :
    "${t.pipeline}-${try(t.name, tostring(idx))}" => t
  }

  triggers_by_pipeline = {
    for name in distinct([for t in local.triggers_filtered : t.pipeline]) :
    name => [for t in local.triggers_filtered : t if t.pipeline == name]
  }

  trigger_defs = {
    for key, t in local.trigger_map : key => {
      pipeline = t.pipeline
      enabled  = try(t.enabled, true)
      schedule_expression = try(t.type, "") == "Schedule" ? try(
        t.schedule_expression, "rate(1 hour)"
      ) : null
      event_pattern = (
        try(t.type, "") == "CodeCommitBranch" ? jsonencode({
          source        = ["aws.codecommit"]
          "detail-type" = ["CodeCommit Repository State Change"]
          resources     = ["arn:${local.partition}:codecommit:${local.region}:${local.account_id}:${t.repository_name}"]
          detail = {
            event         = ["referenceCreated", "referenceUpdated"]
            referenceType = ["branch"]
            referenceName = try(t.branch_names, [try(t.branch_name, "main")])
          }
        }) :
        try(t.type, "") == "CodeCommitTag" ? jsonencode({
          source        = ["aws.codecommit"]
          "detail-type" = ["CodeCommit Repository State Change"]
          resources     = ["arn:${local.partition}:codecommit:${local.region}:${local.account_id}:${t.repository_name}"]
          detail = merge(
            {
              event         = ["referenceCreated", "referenceUpdated"]
              referenceType = ["tag"]
            },
            try(t.tag_names, null) != null ? { referenceName = t.tag_names } : {}
          )
        }) :
        try(t.type, "") == "EventPattern" ? jsonencode(try(t.event_pattern, {})) :
        null
      )
      input = jsonencode(try(t.input, { source = "eventbridge" }))
    }
  }
}

##############################################################################
# Customer managed KMS key for artifact / cache encryption
##############################################################################

resource "aws_kms_key" "terraforest" {
  description             = "TerraForest CI/CD artifact and build cache encryption key"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  tags = merge(var.tags, { Name = "terraforest" })
}

resource "aws_kms_key_policy" "terraforest" {
  key_id = aws_kms_key.terraforest.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableRootAccountAccess"
        Effect = "Allow"
        Principal = {
          AWS = "arn:${local.partition}:iam::${local.account_id}:root"
        }
        Action   = "kms:*"
        Resource = "*"
      }
    ]
  })
}

resource "aws_kms_alias" "terraforest" {
  name          = "alias/terraforest"
  target_key_id = aws_kms_key.terraforest.key_id
}

##############################################################################
# S3 artifact & build cache buckets
##############################################################################

resource "aws_s3_bucket" "managed" {
  for_each = local.managed_buckets

  bucket        = each.value
  force_destroy = try(local.s3_config.force_destroy, false)

  tags = merge(var.tags, { Name = each.value })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_versioning" "managed" {
  for_each = aws_s3_bucket.managed

  bucket = each.value.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "managed" {
  for_each = aws_s3_bucket.managed

  bucket = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "managed" {
  for_each = aws_s3_bucket.managed

  bucket = each.value.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.terraforest.arn
    }
    bucket_key_enabled = true
  }
}

##############################################################################
# Default CodePipeline IAM role (/terraforest/)
##############################################################################

resource "aws_iam_role" "default_codepipeline" {
  count = local.create_default_role ? 1 : 0

  name = local.default_codepipeline_role_name
  path = "/terraforest/"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codepipeline.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

data "aws_iam_policy_document" "default_codepipeline" {
  count = local.create_default_role ? 1 : 0

  statement {
    sid    = "CodeCommitAccess"
    effect = "Allow"

    actions = [
      "codecommit:GetBranch",
      "codecommit:GetCommit",
      "codecommit:GetRepository",
      "codecommit:ListBranches",
      "codecommit:ListRepositories",
      "codecommit:GetUploadArchiveStatus",
      "codecommit:CancelUploadArchive",
      "codecommit:UploadArchive",
      "codecommit:GitPull",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "CodeBuildAccess"
    effect = "Allow"

    actions = [
      "codebuild:BatchGetBuilds",
      "codebuild:StartBuild",
      "codebuild:BatchGetProjects",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "EcrAccess"
    effect = "Allow"

    actions = [
      "ecr:DescribeImages",
      "ecr:GetAuthorizationToken",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:BatchCheckLayerAvailability",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "KmsArtifactAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = [aws_kms_key.terraforest.arn]
  }

  dynamic "statement" {
    for_each = length(local.codestar_connection_arns) > 0 ? [1] : []

    content {
      sid       = "CodeStarConnectionsUse"
      effect    = "Allow"
      actions   = ["codestar-connections:UseConnection"]
      resources = local.codestar_connection_arns
    }
  }

  dynamic "statement" {
    for_each = length(local.pipeline_artifact_bucket_arns) > 0 ? [1] : []

    content {
      sid    = "ArtifactBucketAccess"
      effect = "Allow"

      actions = [
        "s3:GetObject",
        "s3:GetObjectVersion",
        "s3:PutObject",
        "s3:GetBucketVersioning",
        "s3:GetBucketLocation",
        "s3:ListBucket",
        "s3:ListBucketVersions",
      ]

      resources = local.pipeline_artifact_bucket_arns
    }
  }
}

resource "aws_iam_role_policy" "default_codepipeline" {
  count = local.create_default_role ? 1 : 0

  name   = "${local.default_codepipeline_role_name}-policy"
  role   = aws_iam_role.default_codepipeline[0].id
  policy = data.aws_iam_policy_document.default_codepipeline[0].json
}

##############################################################################
# CodeStar connections
##############################################################################

resource "aws_codestarconnections_connection" "connections" {
  for_each = local.codestar_connections_map

  name          = each.value.name
  provider_type = each.value.provider_type
  host_arn      = try(each.value.host_arn, null)

  tags = var.tags
}

##############################################################################
# Optional CodeBuild projects
##############################################################################

resource "aws_iam_role" "codebuild" {
  count = local.create_codebuild_role ? 1 : 0

  name = "terrabits-codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

data "aws_iam_policy_document" "codebuild" {
  count = local.create_codebuild_role ? 1 : 0

  statement {
    sid    = "CloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogGroup",
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/codebuild/*",
    ]
  }

  statement {
    sid    = "S3Access"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:GetBucketVersioning",
      "s3:GetBucketLocation",
      "s3:ListBucket",
      "s3:ListBucketVersions",
    ]

    resources = local.managed_bucket_arns
  }

  statement {
    sid    = "KmsArtifactAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:GenerateDataKeyWithoutPlaintext",
      "kms:DescribeKey",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = [aws_kms_key.terraforest.arn]
  }

  statement {
    sid    = "CodeCommitAccess"
    effect = "Allow"

    actions = [
      "codecommit:GitPull",
      "codecommit:GetBranch",
      "codecommit:GetCommit",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "EcrAccess"
    effect = "Allow"

    actions = [
      "ecr:GetAuthorizationToken",
      "ecr:BatchCheckLayerAvailability",
      "ecr:GetDownloadUrlForLayer",
      "ecr:BatchGetImage",
      "ecr:PutImage",
      "ecr:InitiateLayerUpload",
      "ecr:UploadLayerPart",
      "ecr:CompleteLayerUpload",
    ]

    resources = ["*"]
  }
}

resource "aws_iam_role_policy" "codebuild" {
  count = local.create_codebuild_role ? 1 : 0

  name   = "terrabits-codebuild-service-role-policy"
  role   = aws_iam_role.codebuild[0].id
  policy = data.aws_iam_policy_document.codebuild[0].json
}

resource "aws_codebuild_project" "projects" {
  for_each = local.codebuild_projects_map

  name           = each.value.name
  description    = try(each.value.description, "Managed by terraforest")
  service_role   = try(each.value.service_role_arn, aws_iam_role.codebuild[0].arn)
  build_timeout  = try(each.value.build_timeout, 60)
  queued_timeout = try(each.value.queued_timeout, 480)

  artifacts {
    type = try(each.value.artifacts_type, "CODEPIPELINE")
  }

  environment {
    compute_type                = try(each.value.compute_type, "BUILD_GENERAL1_SMALL")
    image                       = try(each.value.image, "aws/codebuild/standard:7.0")
    type                        = try(each.value.environment_type, "LINUX_CONTAINER")
    image_pull_credentials_type = try(each.value.image_pull_credentials_type, "CODEBUILD")
    privileged_mode             = try(each.value.privileged_mode, false)

    dynamic "environment_variable" {
      for_each = try(each.value.environment_variables, [])

      content {
        name  = environment_variable.value.name
        value = environment_variable.value.value
        type  = try(environment_variable.value.type, "PLAINTEXT")
      }
    }
  }

  source {
    type      = try(each.value.source_type, "CODEPIPELINE")
    buildspec = try(each.value.buildspec, null)
  }

  dynamic "cache" {
    for_each = local.build_cache_bucket_name != null ? [1] : []

    content {
      type     = "S3"
      location = "${local.build_cache_bucket_name}/cache"
    }
  }

  logs_config {
    cloudwatch_logs {
      group_name = "/aws/codebuild/${each.value.name}"
    }
  }

  tags = var.tags
}

##############################################################################
# CodePipelines
##############################################################################

resource "aws_codepipeline" "pipelines" {
  for_each = local.pipelines_map

  name          = each.key
  role_arn      = local.pipeline_role_arn[each.key]
  pipeline_type = try(each.value.pipeline_type, "V2")

  tags = var.tags

  artifact_store {
    location = local.pipeline_artifact_bucket[each.key]
    type     = "S3"
  }

  stage {
    name = try(each.value.source.stage_name, "Source")

    action {
      name             = "Source"
      category         = "Source"
      owner            = "AWS"
      provider         = local.source_provider[each.key]
      version          = "1"
      output_artifacts = [try(each.value.source.output_artifact, "SourceArtifact")]
      configuration    = local.source_configuration[each.key]
    }
  }

  dynamic "stage" {
    for_each = local.pipeline_stages[each.key]

    content {
      name = stage.value.name

      dynamic "action" {
        for_each = stage.value.actions

        content {
          name             = action.value.name
          category         = action.value.category
          owner            = action.value.owner
          provider         = action.value.provider
          version          = action.value.version
          input_artifacts  = action.value.input_artifacts
          output_artifacts = action.value.output_artifacts
          run_order        = action.value.run_order
          namespace        = action.value.namespace
          configuration    = action.value.configuration
        }
      }
    }
  }
}

##############################################################################
# EventBridge triggers
##############################################################################

resource "aws_iam_role" "eventbridge" {
  for_each = local.triggers_by_pipeline

  name = "terrabits-${each.key}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "events.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = var.tags
}

resource "aws_iam_role_policy" "eventbridge" {
  for_each = local.triggers_by_pipeline

  name = "terrabits-${each.key}-start-pipeline"

  role = aws_iam_role.eventbridge[each.key].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "codepipeline:StartPipelineExecution"
        Resource = aws_codepipeline.pipelines[each.key].arn
      }
    ]
  })
}

resource "aws_cloudwatch_event_rule" "triggers" {
  for_each = local.trigger_defs

  name        = "terrabits-${each.key}"
  description = "Trigger ${each.value.pipeline} pipeline via terraforest"

  schedule_expression = each.value.schedule_expression
  event_pattern       = each.value.event_pattern
  state               = each.value.enabled ? "ENABLED" : "DISABLED"

  tags = var.tags
}

resource "aws_cloudwatch_event_target" "triggers" {
  for_each = local.trigger_defs

  rule      = aws_cloudwatch_event_rule.triggers[each.key].name
  target_id = "${each.value.pipeline}-pipeline"
  arn       = aws_codepipeline.pipelines[each.value.pipeline].arn
  role_arn  = aws_iam_role.eventbridge[each.value.pipeline].arn
  input     = each.value.input
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

################################################################################
# Module behaviour
################################################################################

variable "create" {
  description = "Controls whether this configuration creates any resources (security group, its rules and the managed prefix list)."
  type        = bool
  default     = true
}

variable "create_sg" {
  description = "Controls whether a new security group is created (true) or rules are managed on an existing security group supplied through var.security_group_id (false)."
  type        = bool
  default     = true
}

variable "name" {
  description = "Base name used when naming the resources created by this configuration. Must not begin with the reserved AWS security-group identifier prefix 'sg-'."
  type        = string
  default     = "network-sg-module"

  validation {
    condition     = length(var.name) > 0 && !startswith(var.name, "sg-")
    error_message = "The name must be non-empty and must not begin with 'sg-', which is reserved by AWS for security group identifiers."
  }

  validation {
    condition     = length(var.name) <= 200
    error_message = "The name must be 200 characters or fewer so that the composed security group name_prefix (which appends a suffix) stays within the 255 character AWS limit."
  }
}

variable "tags" {
  description = "Map of tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

################################################################################
# Networking
################################################################################

variable "vpc_id" {
  description = "ID of the VPC in which the security groups are created. When null the VPC created by this configuration is used."
  type        = string
  default     = null
}

variable "vpc_cidr_block" {
  description = "IPv4 CIDR block for the VPC created by this configuration when var.vpc_id is null."
  type        = string
  default     = "10.0.0.0/16"
}

################################################################################
# Security group
################################################################################

variable "security_group_id" {
  description = "ID of an existing security group whose rules are managed when var.create_sg is false. When null a security group is created by this configuration and used instead."
  type        = string
  default     = null
}

variable "security_group_description" {
  description = "Description assigned to the newly created security group."
  type        = string
  default     = "Security group managed by Terraform"
}

variable "revoke_rules_on_delete" {
  description = "Whether Terraform revokes all attached ingress and egress rules before deleting the security group."
  type        = bool
  default     = false
}

################################################################################
# Rules applied to the newly created security group
################################################################################

variable "ingress_rules" {
  description = "Ingress rules applied to the newly created security group. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id or prefix_list_id."
  type = list(object({
    description              = optional(string)
    ip_protocol              = optional(string, "-1")
    from_port                = optional(number, 0)
    to_port                  = optional(number, 0)
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.ingress_rules :
      length([
        for value in [rule.cidr_ipv4, rule.cidr_ipv6, rule.source_security_group_id, rule.prefix_list_id] :
        value if value != null
      ]) == 1
    ])
    error_message = "Each ingress rule must set exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id or prefix_list_id."
  }
}

variable "egress_rules" {
  description = "Egress rules applied to the newly created security group. Defaults to allowing all outbound IPv4 traffic."
  type = list(object({
    description              = optional(string)
    ip_protocol              = optional(string, "-1")
    from_port                = optional(number, 0)
    to_port                  = optional(number, 0)
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = [
    {
      description = "Allow all outbound IPv4 traffic"
      ip_protocol = "-1"
      from_port   = 0
      to_port     = 0
      cidr_ipv4   = "0.0.0.0/0"
    }
  ]

  validation {
    condition = alltrue([
      for rule in var.egress_rules :
      length([
        for value in [rule.cidr_ipv4, rule.cidr_ipv6, rule.source_security_group_id, rule.prefix_list_id] :
        value if value != null
      ]) == 1
    ])
    error_message = "Each egress rule must set exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id or prefix_list_id."
  }
}

################################################################################
# Rules applied to the existing security group
################################################################################

variable "existing_sg_ingress_rules" {
  description = "Ingress rules applied to the existing security group when var.create_sg is false. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id or prefix_list_id."
  type = list(object({
    description              = optional(string)
    ip_protocol              = optional(string, "-1")
    from_port                = optional(number, 0)
    to_port                  = optional(number, 0)
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_sg_ingress_rules :
      length([
        for value in [rule.cidr_ipv4, rule.cidr_ipv6, rule.source_security_group_id, rule.prefix_list_id] :
        value if value != null
      ]) == 1
    ])
    error_message = "Each existing security group ingress rule must set exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id or prefix_list_id."
  }
}

variable "existing_sg_egress_rules" {
  description = "Egress rules applied to the existing security group when var.create_sg is false. Each rule must set exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id or prefix_list_id."
  type = list(object({
    description              = optional(string)
    ip_protocol              = optional(string, "-1")
    from_port                = optional(number, 0)
    to_port                  = optional(number, 0)
    cidr_ipv4                = optional(string)
    cidr_ipv6                = optional(string)
    source_security_group_id = optional(string)
    prefix_list_id           = optional(string)
  }))
  default = []

  validation {
    condition = alltrue([
      for rule in var.existing_sg_egress_rules :
      length([
        for value in [rule.cidr_ipv4, rule.cidr_ipv6, rule.source_security_group_id, rule.prefix_list_id] :
        value if value != null
      ]) == 1
    ])
    error_message = "Each existing security group egress rule must set exactly one of cidr_ipv4, cidr_ipv6, source_security_group_id or prefix_list_id."
  }
}

################################################################################
# Managed prefix list
################################################################################

variable "create_prefix_list" {
  description = "Whether to create a customer managed EC2 prefix list. Ignored when var.prefix_list_ids is not empty."
  type        = bool
  default     = false
}

variable "prefix_list_name" {
  description = "Name of the customer managed prefix list. Defaults to \"<var.name>-prefix-list\" when null."
  type        = string
  default     = null
}

variable "prefix_list_address_family" {
  description = "Address family of the customer managed prefix list (IPv4 or IPv6)."
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either IPv4 or IPv6."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries the customer managed prefix list can hold."
  type        = number
  default     = 10
}

variable "prefix_list_entries" {
  description = "CIDR entries used to populate the customer managed prefix list."
  type        = list(string)
  default     = []
}

variable "prefix_list_ids" {
  description = "Existing managed prefix list IDs. When non-empty no new prefix list is created by this configuration."
  type        = list(string)
  default     = []
}

################################################################################
# Locals
################################################################################

locals {
  create    = var.create
  create_sg = var.create && var.create_sg

  tags = merge(var.tags, {
    "ManagedBy" = "Terraform"
  })

  # VPC: use the supplied ID when provided, otherwise the VPC created here.
  create_vpc = local.create && var.vpc_id == null
  vpc_id     = var.vpc_id != null ? var.vpc_id : one(aws_vpc.main[*].id)

  # Newly created security group.
  new_sg_id = one(aws_security_group.this[*].id)

  # Existing security group: supplied ID, or a placeholder created here so the
  # configuration remains self contained on a greenfield account.
  create_existing_sg = local.create && !var.create_sg && var.security_group_id == null
  existing_sg_id     = var.security_group_id != null ? var.security_group_id : one(aws_security_group.existing[*].id)

  # Security group all rules are attached to.
  security_group_id = local.create ? (var.create_sg ? local.new_sg_id : local.existing_sg_id) : null

  # Rule sets for the newly created security group.
  new_ingress_rules = local.create && var.create_sg ? var.ingress_rules : []
  new_egress_rules  = local.create && var.create_sg ? var.egress_rules : []

  # Rule sets for the existing security group.
  existing_ingress_rules = local.create && !var.create_sg ? var.existing_sg_ingress_rules : []
  existing_egress_rules  = local.create && !var.create_sg ? var.existing_sg_egress_rules : []

  # Customer managed prefix list.
  create_prefix_list = local.create && var.create_prefix_list && length(var.prefix_list_ids) == 0
  prefix_list_name   = coalesce(var.prefix_list_name, "${var.name}-prefix-list")
}

################################################################################
# VPC (greenfield dependency)
################################################################################

resource "aws_vpc" "main" {
  count = local.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, {
    "Name" = "${var.name}-vpc"
  })
}

################################################################################
# Security groups
################################################################################

resource "aws_security_group" "this" {
  count = local.create_sg ? 1 : 0

  name_prefix = "${var.name}-"
  description = var.security_group_description
  vpc_id      = local.vpc_id

  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = merge(local.tags, {
    "Name" = "${var.name}-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_security_group" "existing" {
  count = local.create_existing_sg ? 1 : 0

  name_prefix = "${var.name}-existing-"
  description = "Security group managed by this configuration when create_sg = false"
  vpc_id      = local.vpc_id

  revoke_rules_on_delete = var.revoke_rules_on_delete

  tags = merge(local.tags, {
    "Name" = "${var.name}-existing-sg"
  })

  lifecycle {
    create_before_destroy = true
  }
}

################################################################################
# Rules attached to the newly created security group
################################################################################

resource "aws_vpc_security_group_ingress_rule" "new" {
  for_each = { for idx, rule in local.new_ingress_rules : tostring(idx) => rule }

  security_group_id            = local.security_group_id
  description                  = try(each.value.description, null)
  ip_protocol                  = try(each.value.ip_protocol, "-1")
  from_port                    = each.value.ip_protocol == "-1" ? null : try(each.value.from_port, 0)
  to_port                      = each.value.ip_protocol == "-1" ? null : try(each.value.to_port, 0)
  cidr_ipv4                    = try(each.value.cidr_ipv4, null)
  cidr_ipv6                    = try(each.value.cidr_ipv6, null)
  referenced_security_group_id = try(each.value.source_security_group_id, null)
  prefix_list_id               = try(each.value.prefix_list_id, null)

  tags = merge(local.tags, {
    "Name" = "${var.name}-ingress-${each.key}"
  })
}

resource "aws_vpc_security_group_egress_rule" "new" {
  for_each = { for idx, rule in local.new_egress_rules : tostring(idx) => rule }

  security_group_id            = local.security_group_id
  description                  = try(each.value.description, null)
  ip_protocol                  = try(each.value.ip_protocol, "-1")
  from_port                    = each.value.ip_protocol == "-1" ? null : try(each.value.from_port, 0)
  to_port                      = each.value.ip_protocol == "-1" ? null : try(each.value.to_port, 0)
  cidr_ipv4                    = try(each.value.cidr_ipv4, null)
  cidr_ipv6                    = try(each.value.cidr_ipv6, null)
  referenced_security_group_id = try(each.value.source_security_group_id, null)
  prefix_list_id               = try(each.value.prefix_list_id, null)

  tags = merge(local.tags, {
    "Name" = "${var.name}-egress-${each.key}"
  })
}

################################################################################
# Rules attached to the existing security group
################################################################################

resource "aws_vpc_security_group_ingress_rule" "existing" {
  for_each = { for idx, rule in local.existing_ingress_rules : tostring(idx) => rule }

  security_group_id            = local.security_group_id
  description                  = try(each.value.description, null)
  ip_protocol                  = try(each.value.ip_protocol, "-1")
  from_port                    = each.value.ip_protocol == "-1" ? null : try(each.value.from_port, 0)
  to_port                      = each.value.ip_protocol == "-1" ? null : try(each.value.to_port, 0)
  cidr_ipv4                    = try(each.value.cidr_ipv4, null)
  cidr_ipv6                    = try(each.value.cidr_ipv6, null)
  referenced_security_group_id = try(each.value.source_security_group_id, null)
  prefix_list_id               = try(each.value.prefix_list_id, null)

  tags = merge(local.tags, {
    "Name" = "${var.name}-existing-ingress-${each.key}"
  })
}

resource "aws_vpc_security_group_egress_rule" "existing" {
  for_each = { for idx, rule in local.existing_egress_rules : tostring(idx) => rule }

  security_group_id            = local.security_group_id
  description                  = try(each.value.description, null)
  ip_protocol                  = try(each.value.ip_protocol, "-1")
  from_port                    = each.value.ip_protocol == "-1" ? null : try(each.value.from_port, 0)
  to_port                      = each.value.ip_protocol == "-1" ? null : try(each.value.to_port, 0)
  cidr_ipv4                    = try(each.value.cidr_ipv4, null)
  cidr_ipv6                    = try(each.value.cidr_ipv6, null)
  referenced_security_group_id = try(each.value.source_security_group_id, null)
  prefix_list_id               = try(each.value.prefix_list_id, null)

  tags = merge(local.tags, {
    "Name" = "${var.name}-existing-egress-${each.key}"
  })
}

################################################################################
# Customer managed EC2 prefix list
################################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = local.prefix_list_name
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = { for idx, cidr in var.prefix_list_entries : tostring(idx) => cidr }

    content {
      cidr        = entry.value
      description = "Managed prefix list entry ${entry.key}"
    }
  }

  tags = merge(local.tags, {
    "Name" = local.prefix_list_name
  })

  lifecycle {
    precondition {
      condition     = length(var.prefix_list_entries) <= var.prefix_list_max_entries
      error_message = "The number of prefix_list_entries must not exceed prefix_list_max_entries."
    }
  }
}

################################################################################
# Outputs
################################################################################

output "vpc_id" {
  description = "ID of the VPC used by this configuration."
  value       = local.vpc_id
}

output "security_group_id" {
  description = "ID of the security group that rules are attached to."
  value       = local.security_group_id
}

output "created_security_group_id" {
  description = "ID of the newly created security group, when one is created."
  value       = local.new_sg_id
}

output "created_security_group_arn" {
  description = "ARN of the newly created security group, when one is created."
  value       = try(aws_security_group.this[0].arn, null)
}

output "existing_security_group_id" {
  description = "ID of the existing security group used when create_sg is false."
  value       = local.existing_sg_id
}

output "managed_prefix_list_id" {
  description = "ID of the customer managed prefix list created by this configuration, if any."
  value       = try(aws_ec2_managed_prefix_list.this[0].id, null)
}

output "managed_prefix_list_arn" {
  description = "ARN of the customer managed prefix list created by this configuration, if any."
  value       = try(aws_ec2_managed_prefix_list.this[0].arn, null)
}

locals {
  environment = "dev"
}

