# near-wallets-blockchain
###############################################################################
resource "aws_dynamodb_table" "near_wallets_blockchain" {
  name         = "near-wallets-blockchain"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "wallet_id"

  attribute {
    name = "wallet_id"
    type = "S"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "near-wallets-blockchain"
    Environment = local.environment
  }
}

###############################################################################
# near-wallets-private
###############################################################################
resource "aws_dynamodb_table" "near_wallets_private" {
  name         = "near-wallets-private"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "walletId"

  attribute {
    name = "walletId"
    type = "S"
  }

  attribute {
    name = "UserId"
    type = "S"
  }

  global_secondary_index {
    name            = "UserIdIndex"
    hash_key        = "UserId"
    range_key       = "walletId"
    projection_type = "ALL"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "near-wallets-private"
    Environment = local.environment
  }
}

###############################################################################
# near-wallets
###############################################################################
resource "aws_dynamodb_table" "near_wallets" {
  name             = "near-wallets"
  billing_mode     = "PAY_PER_REQUEST"
  hash_key         = "walletId"
  stream_enabled   = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "walletId"
    type = "S"
  }

  attribute {
    name = "userId"
    type = "S"
  }

  attribute {
    name = "walletName"
    type = "S"
  }

  attribute {
    name = "jobId"
    type = "S"
  }

  global_secondary_index {
    name            = "userId-Index"
    hash_key        = "userId"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "walletName-Index"
    hash_key        = "walletName"
    projection_type = "ALL"
  }

  global_secondary_index {
    name            = "jobId-Index"
    hash_key        = "jobId"
    projection_type = "ALL"
  }

  lifecycle {
    prevent_destroy = true
  }

  tags = {
    Name        = "near-wallets"
    Environment = local.environment
  }
}

