terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.30.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.5.0"
    }
  }
}

##############################################################################
# Static provider metadata
##############################################################################

data "aws_partition" "current" {}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

##############################################################################
# Variables
##############################################################################

variable "name" {
  description = "Explicit base identifier used for all resources. Falls back to a two-word hyphenated random pet name when empty."
  type        = string
  default     = ""
}

variable "endpoint_type" {
  description = "Transfer server endpoint type. One of PUBLIC, VPC or VPC_ENDPOINT."
  type        = string
  default     = "PUBLIC"

  validation {
    condition     = contains(["PUBLIC", "VPC", "VPC_ENDPOINT"], var.endpoint_type)
    error_message = "endpoint_type must be one of: PUBLIC, VPC, VPC_ENDPOINT."
  }
}

variable "protocols" {
  description = "Protocols enabled on the Transfer server (SFTP, FTPS, FTP, AS2)."
  type        = list(string)
  default     = ["SFTP"]
}

variable "domain" {
  description = "Storage domain backing the Transfer server. One of S3 or EFS."
  type        = string
  default     = "S3"

  validation {
    condition     = contains(["S3", "EFS"], var.domain)
    error_message = "domain must be one of: S3, EFS."
  }
}

variable "identity_provider_type" {
  description = "Identity provider type for the Transfer server."
  type        = string
  default     = "SERVICE_MANAGED"

  validation {
    condition     = contains(["SERVICE_MANAGED", "API_GATEWAY", "AWS_DIRECTORY_SERVICE", "LAMBDA"], var.identity_provider_type)
    error_message = "identity_provider_type must be one of: SERVICE_MANAGED, API_GATEWAY, AWS_DIRECTORY_SERVICE, LAMBDA."
  }
}

variable "logging_role_arn" {
  description = "Existing IAM role ARN used for Transfer logging. When empty a role attached to AWSTransferLoggingAccess is created."
  type        = string
  default     = ""
}

variable "security_policy_name" {
  description = "Name of the Transfer security policy applied to the server."
  type        = string
  default     = "TransferSecurityPolicy-2023-05"
}

variable "certificate_arn" {
  description = "ACM certificate ARN used for FTPS."
  type        = string
  default     = ""
}

variable "host_key" {
  description = "Private host key material provisioned on the Transfer server."
  type        = string
  default     = ""
  sensitive   = true
}

variable "pre_authentication_login_banner" {
  description = "Login banner displayed before authentication."
  type        = string
  default     = ""
}

variable "post_authentication_login_banner" {
  description = "Login banner displayed after authentication."
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "VPC ID hosting the Transfer endpoint (VPC endpoint types only)."
  type        = string
  default     = ""
}

variable "subnet_ids" {
  description = "Subnet IDs for the Transfer VPC endpoint. An Elastic IP is created per subnet when none are supplied."
  type        = list(string)
  default     = []
}

variable "security_group_ids" {
  description = "Pre-existing security group IDs. A dedicated security group is created when empty."
  type        = list(string)
  default     = []
}

variable "address_allocation_ids" {
  description = "Pre-existing Elastic IP allocation IDs. One EIP is created per subnet when empty."
  type        = list(string)
  default     = []
}

variable "vpc_endpoint_id" {
  description = "VPC endpoint ID used with the VPC_ENDPOINT endpoint type."
  type        = string
  default     = ""
}

variable "api_gateway_url" {
  description = "Invoke URL of the API Gateway used as a custom identity provider."
  type        = string
  default     = ""
}

variable "api_gateway_invocation_role_arn" {
  description = "Existing IAM role ARN that the Transfer server assumes to invoke API Gateway."
  type        = string
  default     = ""
}

variable "hosted_zone_id" {
  description = "Route 53 hosted zone ID used for the optional CNAME record."
  type        = string
  default     = ""
}

variable "hosted_zone_name" {
  description = "Base domain of the Route 53 hosted zone (e.g. example.com)."
  type        = string
  default     = ""
}

variable "subdomain" {
  description = "Sub-domain label mapped to the Transfer server endpoint."
  type        = string
  default     = "sftp"
}

variable "dns_ttl" {
  description = "TTL in seconds for the Route 53 CNAME record."
  type        = number
  default     = 300
}

variable "log_retention_days" {
  description = "Retention in days for the Transfer CloudWatch log group."
  type        = number
  default     = 90
}

variable "protocol_details" {
  description = "Optional protocol configuration details for AS2, passive IP, set-stat and TLS session resumption."
  type = object({
    as2_transports              = optional(list(string))
    passive_ip                  = optional(string)
    set_stat_option             = optional(string)
    tls_session_resumption_mode = optional(string)
  })
  default = {}
}

variable "users" {
  description = "Map of SFTP users keyed by user name."
  type = map(object({
    home_directory      = optional(string)
    home_directory_type = optional(string, "LOGICAL")
    s3_bucket           = optional(string, "")
    s3_prefix           = optional(string, "")
    tags                = optional(map(string), {})
  }))
  default = {}
}

variable "user_ssh_keys" {
  description = "Map of user name to a list of SSH public key bodies associated with that user."
  type        = map(list(string))
  default     = {}
}

variable "tags" {
  description = "Additional tags applied to all taggable resources."
  type        = map(string)
  default     = {}
}

##############################################################################
# Naming
##############################################################################

resource "random_pet" "this" {
  count     = var.name == "" ? 1 : 0
  length    = 2
  separator = "-"
}

locals {
  server_name = var.name != "" ? var.name : one(random_pet.this[*].id)

  partition    = data.aws_partition.current.partition
  region       = data.aws_region.current.region
  account_id   = data.aws_caller_identity.current.account_id

  is_vpc_standard = var.endpoint_type == "VPC"
  is_vpc_endpoint = var.endpoint_type == "VPC_ENDPOINT"
  is_vpc          = local.is_vpc_standard || local.is_vpc_endpoint

  create_security_group = local.is_vpc_standard && length(var.security_group_ids) == 0
  create_eips           = local.is_vpc_standard && length(var.subnet_ids) > 0 && length(var.address_allocation_ids) == 0

  security_group_ids     = local.is_vpc_standard ? concat(var.security_group_ids, aws_security_group.transfer[*].id) : null
  address_allocation_ids = local.is_vpc_standard ? concat(var.address_allocation_ids, aws_eip.transfer[*].id) : null

  enable_api_gateway = var.identity_provider_type == "API_GATEWAY"

  has_protocol_details = (
    var.protocol_details.as2_transports != null ||
    var.protocol_details.passive_ip != null ||
    var.protocol_details.set_stat_option != null ||
    var.protocol_details.tls_session_resumption_mode != null
  )

  tags = merge(
    {
      Name        = local.server_name
      ManagedBy   = "terraform"
      Application = "aws-transfer-family"
    },
    var.tags,
  )

  logging_role_arn = var.logging_role_arn != "" ? var.logging_role_arn : one(aws_iam_role.transfer_logging[*].arn)

  api_gateway_invocation_role_arn = var.api_gateway_invocation_role_arn != "" ? var.api_gateway_invocation_role_arn : one(aws_iam_role.api_gateway_invocation[*].arn)
}

##############################################################################
# CloudWatch logging
##############################################################################

resource "aws_cloudwatch_log_group" "transfer" {
  name              = "/aws/transfer/${local.server_name}"
  retention_in_days = var.log_retention_days

  tags = local.tags
}

data "aws_iam_policy_document" "transfer_assume_role" {
  statement {
    sid     = "AllowTransferAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["transfer.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "transfer_logging" {
  count = var.logging_role_arn == "" ? 1 : 0

  name               = "${local.server_name}-transfer-logging"
  description        = "IAM role assumed by AWS Transfer Family to write logs to CloudWatch."
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "transfer_logging" {
  count = var.logging_role_arn == "" ? 1 : 0

  role       = aws_iam_role.transfer_logging[0].name
  policy_arn = "arn:${local.partition}:iam::aws:policy/service-role/AWSTransferLoggingAccess"
}

##############################################################################
# API Gateway custom identity provider authorization
##############################################################################

data "aws_iam_policy_document" "api_gateway_cloudwatch_assume_role" {
  count = local.enable_api_gateway ? 1 : 0

  statement {
    sid     = "AllowApiGatewayAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["apigateway.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "api_gateway_cloudwatch" {
  count = local.enable_api_gateway ? 1 : 0

  name               = "${local.server_name}-apigw-cloudwatch"
  description        = "IAM role allowing API Gateway to publish execution logs to CloudWatch."
  assume_role_policy = data.aws_iam_policy_document.api_gateway_cloudwatch_assume_role[0].json

  tags = local.tags
}

data "aws_iam_policy_document" "api_gateway_cloudwatch" {
  count = local.enable_api_gateway ? 1 : 0

  statement {
    sid       = "ManageApiGatewayLogGroups"
    effect    = "Allow"
    actions   = ["logs:CreateLogGroup", "logs:DescribeLogGroups"]
    resources = ["arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:*"]
  }

  statement {
    sid    = "WriteApiGatewayLogs"
    effect = "Allow"
    actions = [
      "logs:CreateLogStream",
      "logs:DescribeLogStreams",
      "logs:PutLogEvents",
      "logs:GetLogEvents",
      "logs:FilterLogEvents",
    ]
    resources = [
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/api-gateway/*",
      "arn:${local.partition}:logs:${local.region}:${local.account_id}:log-group:/aws/api-gateway/*:*",
    ]
  }
}

resource "aws_iam_role_policy" "api_gateway_cloudwatch" {
  count = local.enable_api_gateway ? 1 : 0

  name   = "api-gateway-cloudwatch-logs"
  role   = aws_iam_role.api_gateway_cloudwatch[0].id
  policy = data.aws_iam_policy_document.api_gateway_cloudwatch[0].json
}

resource "aws_api_gateway_account" "this" {
  count = local.enable_api_gateway ? 1 : 0

  cloudwatch_role_arn = aws_iam_role.api_gateway_cloudwatch[0].arn
}

resource "aws_iam_role" "api_gateway_invocation" {
  count = local.enable_api_gateway && var.api_gateway_invocation_role_arn == "" ? 1 : 0

  name               = "${local.server_name}-apigw-invocation"
  description        = "IAM role assumed by AWS Transfer Family to invoke the API Gateway identity provider."
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json

  tags = local.tags
}

data "aws_iam_policy_document" "api_gateway_invocation" {
  count = local.enable_api_gateway && var.api_gateway_invocation_role_arn == "" ? 1 : 0

  statement {
    sid       = "InvokeIdentityProviderApi"
    effect    = "Allow"
    actions   = ["execute-api:Invoke"]
    resources = ["arn:${local.partition}:execute-api:${local.region}:${local.account_id}:*/*/*/*"]
  }
}

resource "aws_iam_role_policy" "api_gateway_invocation" {
  count = local.enable_api_gateway && var.api_gateway_invocation_role_arn == "" ? 1 : 0

  name   = "api-gateway-invoke"
  role   = aws_iam_role.api_gateway_invocation[0].id
  policy = data.aws_iam_policy_document.api_gateway_invocation[0].json
}

##############################################################################
# VPC networking helpers
##############################################################################

resource "aws_security_group" "transfer" {
  count = local.create_security_group ? 1 : 0

  name        = "${local.server_name}-transfer-sftp"
  description = "Dedicated security group for the AWS Transfer Family SFTP endpoint."
  vpc_id      = var.vpc_id

  tags = merge(local.tags, { Name = "${local.server_name}-transfer-sftp" })
}

resource "aws_vpc_security_group_ingress_rule" "transfer_sftp" {
  count = local.create_security_group ? 1 : 0

  security_group_id = aws_security_group.transfer[0].id
  description       = "SFTP access"
  cidr_ipv4         = "0.0.0.0/0"
  from_port         = 22
  to_port           = 22
  ip_protocol       = "tcp"
}

resource "aws_vpc_security_group_egress_rule" "transfer_all" {
  count = local.create_security_group ? 1 : 0

  security_group_id = aws_security_group.transfer[0].id
  description       = "Allow all outbound traffic"
  cidr_ipv4         = "0.0.0.0/0"
  ip_protocol       = "-1"
}

resource "aws_eip" "transfer" {
  count = local.create_eips ? length(var.subnet_ids) : 0

  domain = "vpc"

  tags = merge(local.tags, { Name = "${local.server_name}-transfer-${count.index}" })
}

##############################################################################
# Transfer server
##############################################################################

resource "aws_transfer_server" "this" {
  identity_provider_type = var.identity_provider_type
  endpoint_type          = var.endpoint_type
  protocols              = var.protocols
  domain                 = var.domain
  security_policy_name   = var.security_policy_name
  logging_role           = local.logging_role_arn

  certificate = var.certificate_arn != "" ? var.certificate_arn : null
  host_key    = var.host_key != "" ? var.host_key : null

  pre_authentication_login_banner  = var.pre_authentication_login_banner != "" ? var.pre_authentication_login_banner : null
  post_authentication_login_banner = var.post_authentication_login_banner != "" ? var.post_authentication_login_banner : null

  url             = local.enable_api_gateway ? var.api_gateway_url : null
  invocation_role = local.enable_api_gateway ? local.api_gateway_invocation_role_arn : null

  structured_log_destinations = [aws_cloudwatch_log_group.transfer.arn]

  dynamic "endpoint_details" {
    for_each = local.is_vpc ? [1] : []

    content {
      vpc_id                 = local.is_vpc_standard ? var.vpc_id : null
      subnet_ids             = local.is_vpc_standard ? var.subnet_ids : null
      security_group_ids     = local.security_group_ids
      address_allocation_ids = local.address_allocation_ids
      vpc_endpoint_id        = local.is_vpc_endpoint ? var.vpc_endpoint_id : null
    }
  }

  dynamic "protocol_details" {
    for_each = local.has_protocol_details ? [1] : []

    content {
      as2_transports              = var.protocol_details.as2_transports
      passive_ip                  = var.protocol_details.passive_ip
      set_stat_option             = var.protocol_details.set_stat_option
      tls_session_resumption_mode = var.protocol_details.tls_session_resumption_mode
    }
  }

  tags = merge(local.tags, { Name = local.server_name })
}

##############################################################################
# Per-user S3 home directories
##############################################################################

resource "aws_s3_bucket" "user" {
  for_each = { for uname, u in var.users : uname => u if u.s3_bucket == "" }

  bucket        = "${local.server_name}-${lower(each.key)}-home"
  force_destroy = false

  tags = merge(local.tags, { Name = "${local.server_name}-${lower(each.key)}-home" })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "user" {
  for_each = aws_s3_bucket.user

  bucket = each.value.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "user" {
  for_each = aws_s3_bucket.user

  bucket = each.value.id

  rule {
    bucket_key_enabled = true

    apply_server_side_encryption_by_default {
      sse_algorithm = "AES256"
    }
  }
}

locals {
  created_bucket_names = { for uname, b in aws_s3_bucket.user : uname => b.bucket }

  user_bucket_names = {
    for uname, u in var.users : uname => lookup(local.created_bucket_names, uname, u.s3_bucket)
  }

  user_s3_prefix = {
    for uname, u in var.users : uname => (
      u.s3_prefix == "" ? "" : (endswith(u.s3_prefix, "/") ? u.s3_prefix : "${u.s3_prefix}/")
    )
  }

  ssh_keys = merge([
    for uname, keys in var.user_ssh_keys : {
      for idx, key in keys : "${uname}-${idx}" => {
        user = uname
        body = trimspace(key)
      }
    }
  ]...)
}

##############################################################################
# Per-user IAM roles and policies
##############################################################################

resource "aws_iam_role" "user" {
  for_each = var.users

  name               = "${local.server_name}-${lower(each.key)}"
  description        = "IAM role assumed by AWS Transfer Family for user ${each.key}."
  assume_role_policy = data.aws_iam_policy_document.transfer_assume_role.json

  tags = merge(local.tags, each.value.tags)
}

data "aws_iam_policy_document" "user" {
  for_each = var.users

  statement {
    sid       = "ListHomeDirectoryBucket"
    effect    = "Allow"
    actions   = ["s3:ListBucket", "s3:GetBucketLocation"]
    resources = ["arn:${local.partition}:s3:::${local.user_bucket_names[each.key]}"]

    dynamic "condition" {
      for_each = local.user_s3_prefix[each.key] != "" ? [1] : []

      content {
        test     = "StringLike"
        variable = "s3:prefix"
        values   = ["${local.user_s3_prefix[each.key]}*"]
      }
    }
  }

  statement {
    sid    = "HomeDirectoryObjectAccess"
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:GetObjectTagging",
      "s3:PutObject",
      "s3:PutObjectTagging",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]
    resources = ["arn:${local.partition}:s3:::${local.user_bucket_names[each.key]}/${local.user_s3_prefix[each.key]}*"]
  }
}

resource "aws_iam_role_policy" "user" {
  for_each = var.users

  name   = "transfer-user-s3-home"
  role   = aws_iam_role.user[each.key].id
  policy = data.aws_iam_policy_document.user[each.key].json
}

##############################################################################
# Per-user Transfer users and SSH keys
##############################################################################

resource "aws_transfer_user" "this" {
  for_each = var.users

  server_id = aws_transfer_server.this.id
  user_name = each.key
  role      = aws_iam_role.user[each.key].arn

  home_directory = (
    each.value.home_directory != null ? each.value.home_directory :
    "/${local.user_bucket_names[each.key]}/${local.user_s3_prefix[each.key]}"
  )
  home_directory_type = each.value.home_directory_type

  tags = merge(local.tags, each.value.tags)
}

resource "aws_transfer_ssh_key" "this" {
  for_each = {
    for k, v in local.ssh_keys : k => v
    if contains(keys(var.users), v.user) && v.body != ""
  }

  server_id = aws_transfer_server.this.id
  user_name = aws_transfer_user.this[each.value.user].user_name
  body      = each.value.body
}

##############################################################################
# Optional Route 53 DNS mapping
##############################################################################

resource "aws_route53_record" "transfer" {
  count = var.hosted_zone_id != "" && var.hosted_zone_name != "" ? 1 : 0

  zone_id = var.hosted_zone_id
  name    = "${var.subdomain}.${var.hosted_zone_name}"
  type    = "CNAME"
  ttl     = var.dns_ttl
  records = [aws_transfer_server.this.endpoint]
}

##############################################################################
# Outputs
##############################################################################

output "transfer_server_id" {
  description = "ID of the AWS Transfer Family server."
  value       = aws_transfer_server.this.id
}

output "transfer_server_arn" {
  description = "ARN of the AWS Transfer Family server."
  value       = aws_transfer_server.this.arn
}

output "transfer_server_endpoint" {
  description = "Endpoint hostname of the AWS Transfer Family server."
  value       = aws_transfer_server.this.endpoint
}

output "transfer_server_logging_role_arn" {
  description = "IAM role ARN used for Transfer logging."
  value       = local.logging_role_arn
}

output "transfer_server_security_group_id" {
  description = "ID of the dynamically created security group, if any."
  value       = one(aws_security_group.transfer[*].id)
}

output "transfer_server_eip_allocation_ids" {
  description = "Elastic IP allocation IDs created for the VPC endpoint."
  value       = aws_eip.transfer[*].id
}

output "s3_home_buckets" {
  description = "Map of user name to the S3 bucket that holds their home directory."
  value       = local.user_bucket_names
}

output "transfer_user_role_arns" {
  description = "Map of user name to the IAM role ARN assumed by the Transfer user."
  value       = { for uname, role in aws_iam_role.user : uname => role.arn }
}

output "route53_record_fqdn" {
  description = "FQDN of the Route 53 CNAME record, if created."
  value       = one(aws_route53_record.transfer[*].fqdn)
}

terraform {
  required_version = ">= 1.3"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

variable "aws_region" {
  description = "AWS region used for deployment."
  type        = string
  default     = "us-east-1"
}

variable "vpc_name" {
  description = "Name of the VPC and prefix applied to all created resources."
  type        = string
  default     = "benchmark-vpc"
}

variable "vpc_cidr" {
  description = "CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/18"
}

variable "az_count" {
  description = "Number of availability zones to use. Set to 0 to use all available AZs in the region."
  type        = number
  default     = 0
}

variable "create_public_subnets" {
  description = "Whether to create public subnets, internet gateway and public routing."
  type        = bool
  default     = true
}

variable "create_private_subnets" {
  description = "Whether to create private subnets and private routing."
  type        = bool
  default     = true
}

variable "create_nat_gateway" {
  description = "Whether to create a NAT gateway for private subnet egress."
  type        = bool
  default     = true
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  all_azs  = sort(data.aws_availability_zones.available.names)
  az_count = var.az_count == 0 ? length(local.all_azs) : min(var.az_count, length(local.all_azs))
  azs      = slice(local.all_azs, 0, local.az_count)

  public_subnet_count  = var.create_public_subnets ? local.az_count : 0
  private_subnet_count = var.create_private_subnets ? local.az_count : 0

  create_nat = var.create_nat_gateway && var.create_public_subnets && local.az_count > 0

  common_tags = {
    Name        = var.vpc_name
    Region      = var.aws_region
    ManagedBy   = "terraform"
    Environment = "benchmark"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = var.vpc_name
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_internet_gateway" "main" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-igw"
  })
}

resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 6, count.index)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-${local.azs[count.index]}"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(var.vpc_cidr, 6, count.index + 10)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-${local.azs[count.index]}"
    Tier = "private"
  })
}

resource "aws_eip" "nat" {
  count  = local.create_nat ? 1 : 0
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  count = local.create_nat ? 1 : 0

  allocation_id = aws_eip.nat[0].id
  subnet_id     = aws_subnet.public[0].id

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-nat"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main[0].id
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_route_table" "private" {
  count = local.private_subnet_count

  vpc_id = aws_vpc.main.id

  dynamic "route" {
    for_each = local.create_nat ? [1] : []
    content {
      cidr_block     = "0.0.0.0/0"
      nat_gateway_id = aws_nat_gateway.main[0].id
    }
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-rt-${count.index}"
  })
}

resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_network_acl" "public" {
  count = var.create_public_subnets ? 1 : 0

  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.public[*].id

  ingress {
    rule_no    = 100
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 80
    to_port    = 80
  }

  ingress {
    rule_no    = 110
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 443
    to_port    = 443
  }

  ingress {
    rule_no    = 120
    protocol   = "tcp"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 1024
    to_port    = 65535
  }

  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-public-acl"
  })
}

resource "aws_network_acl" "private" {
  count = var.create_private_subnets ? 1 : 0

  vpc_id     = aws_vpc.main.id
  subnet_ids = aws_subnet.private[*].id

  ingress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = var.vpc_cidr
    from_port  = 0
    to_port    = 0
  }

  egress {
    rule_no    = 100
    protocol   = "-1"
    action     = "allow"
    cidr_block = "0.0.0.0/0"
    from_port  = 0
    to_port    = 0
  }

  tags = merge(local.common_tags, {
    Name = "${var.vpc_name}-private-acl"
  })
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 4.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "vpc_cidr" {
  description = "IPv4 CIDR block for the VPC"
  type        = string
  default     = "10.16.0.0/16"
}

variable "is_ipv6_enabled" {
  description = "Assign an Amazon-provided IPv6 CIDR block to the VPC"
  type        = bool
  default     = true
}

variable "subnet_ipv4_new_bits" {
  description = "Additional bits used to calculate IPv4 subnets (/20)"
  type        = number
  default     = 4
}

variable "subnet_ipv6_new_bits" {
  description = "Additional bits used to calculate IPv6 subnets (/64)"
  type        = number
  default     = 8
}

variable "sn_details" {
  description = "Explicit list of subnet definitions; when null, 12 subnets are generated across three AZs."
  type = list(object({
    name   = string
    az     = string
    public = bool
  }))
  default = null
}

###############################################################################
# Data Sources
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Locals
###############################################################################

locals {
  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  tiers = [
    { name = "web", public = true },
    { name = "app", public = false },
    { name = "database", public = false },
    { name = "reserved", public = false },
  ]

  generated_sn_details = flatten([
    for tier in local.tiers : [
      for idx, az in local.azs : {
        name   = "${tier.name}-${idx + 1}"
        az     = az
        public = tier.public
      }
    ]
  ])

  sn_details = var.sn_details != null ? var.sn_details : local.generated_sn_details
  sn_map     = { for s in local.sn_details : s.name => s }
}

###############################################################################
# Networking
###############################################################################

resource "aws_vpc" "main" {
  cidr_block                       = var.vpc_cidr
  instance_tenancy                 = "default"
  enable_dns_support               = true
  enable_dns_hostnames             = true
  assign_generated_ipv6_cidr_block = var.is_ipv6_enabled

  tags = {
    Name = "main-vpc"
  }
}

module "ipv4_subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = aws_vpc.main.cidr_block

  networks = [
    for s in local.sn_details : {
      name     = s.name
      new_bits = var.subnet_ipv4_new_bits
    }
  ]
}

module "ipv6_subnets" {
  source  = "hashicorp/subnets/cidr"
  version = "1.0.0"

  base_cidr_block = var.is_ipv6_enabled ? aws_vpc.main.ipv6_cidr_block : "2001:db8:1::/56"

  networks = [
    for s in local.sn_details : {
      name     = s.name
      new_bits = var.subnet_ipv6_new_bits
    }
  ]
}

resource "aws_subnet" "this" {
  for_each = local.sn_map

  vpc_id            = aws_vpc.main.id
  availability_zone = each.value.az
  cidr_block        = module.ipv4_subnets.network_cidr_blocks[each.key]

  ipv6_cidr_block                 = var.is_ipv6_enabled ? module.ipv6_subnets.network_cidr_blocks[each.key] : null
  assign_ipv6_address_on_creation = var.is_ipv6_enabled ? each.value.public : false
  map_public_ip_on_launch         = each.value.public

  tags = {
    Name = each.key
  }
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "main-igw-vpc-${aws_vpc.main.id}"
  }
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  tags = {
    Name = "public-rt-web"
  }
}

resource "aws_route" "public_ipv4" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route" "public_ipv6" {
  count = var.is_ipv6_enabled ? 1 : 0

  route_table_id              = aws_route_table.public.id
  destination_ipv6_cidr_block = "::/0"
  gateway_id                  = aws_internet_gateway.main.id
}

resource "aws_route_table_association" "public" {
  for_each = { for s in local.sn_details : s.name => s if s.public }

  subnet_id      = aws_subnet.this[each.key].id
  route_table_id = aws_route_table.public.id
}

###############################################################################
# Security Groups
###############################################################################

resource "aws_security_group" "web" {
  name        = "web_sg"
  description = "Web tier security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "web_sg"
  }
}

resource "aws_security_group" "app" {
  name        = "app_sg"
  description = "Application tier security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "app_sg"
  }
}

resource "aws_security_group" "db" {
  name        = "db_sg"
  description = "Database tier security group"
  vpc_id      = aws_vpc.main.id

  tags = {
    Name = "db_sg"
  }
}

# web_sg rules
resource "aws_security_group_rule" "web_ingress_https" {
  type              = "ingress"
  description       = "TLS from the internet"
  security_group_id = aws_security_group.web.id
  from_port         = 443
  to_port           = 443
  protocol          = "tcp"
  cidr_blocks       = ["0.0.0.0/0"]
}

resource "aws_security_group_rule" "web_ingress_ssh" {
  type              = "ingress"
  description       = "SSH from within the VPC"
  security_group_id = aws_security_group.web.id
  from_port         = 22
  to_port           = 22
  protocol          = "tcp"
  cidr_blocks       = [aws_vpc.main.cidr_block]
}

resource "aws_security_group_rule" "web_egress_app" {
  type                     = "egress"
  description              = "TLS to the application tier"
  security_group_id        = aws_security_group.web.id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app.id
}

# app_sg rules
resource "aws_security_group_rule" "app_ingress_web" {
  type                     = "ingress"
  description              = "TLS from the web tier"
  security_group_id        = aws_security_group.app.id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.web.id
}

resource "aws_security_group_rule" "app_egress_db" {
  type                     = "egress"
  description              = "TLS to the database tier"
  security_group_id        = aws_security_group.app.id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.db.id
}

# db_sg rules
resource "aws_security_group_rule" "db_ingress_app" {
  type                     = "ingress"
  description              = "TLS from the application tier"
  security_group_id        = aws_security_group.db.id
  from_port                = 443
  to_port                  = 443
  protocol                 = "tcp"
  source_security_group_id = aws_security_group.app.id
}

###############################################################################
# Outputs
###############################################################################

output "vpc_id" {
  description = "The ID of the main VPC"
  value       = aws_vpc.main.id
}

output "vpc_ipv6_cidr_block" {
  description = "The IPv6 CIDR block assigned to the VPC"
  value       = aws_vpc.main.ipv6_cidr_block
}

output "subnet_ids" {
  description = "Map of subnet name to subnet ID"
  value       = { for k, s in aws_subnet.this : k => s.id }
}

output "public_subnet_ids" {
  description = "IDs of the public subnets"
  value       = [for s in local.sn_details : aws_subnet.this[s.name].id if s.public]
}

output "private_subnet_ids" {
  description = "IDs of the private subnets"
  value       = [for s in local.sn_details : aws_subnet.this[s.name].id if !s.public]
}

output "internet_gateway_id" {
  description = "The ID of the internet gateway"
  value       = aws_internet_gateway.main.id
}

output "public_route_table_id" {
  description = "The ID of the public route table"
  value       = aws_route_table.public.id
}

output "security_group_ids" {
  description = "Map of tier to security group ID"
  value = {
    web = aws_security_group.web.id
    app = aws_security_group.app.id
    db  = aws_security_group.db.id
  }
}

variable "name" {
  description = "Name prefix for the VPC and its resources."
  type        = string
  default     = "vpc"
}

variable "create_vpc" {
  description = "Controls if the VPC resources should be created."
  type        = bool
  default     = true
}

variable "vpc_cidr" {
  description = "The CIDR block for the VPC."
  type        = string
  default     = "10.0.0.0/16"
}

variable "enable_dns_hostnames" {
  description = "Should be true to enable DNS hostnames in the VPC."
  type        = bool
  default     = true
}

variable "enable_dns_support" {
  description = "Should be true to enable DNS support in the VPC."
  type        = bool
  default     = true
}

variable "azs" {
  description = "A list of availability zone names or IDs to spread subnets across."
  type        = list(string)
  default     = []
}

variable "public_subnets" {
  description = "A list of public subnet CIDR blocks."
  type        = list(string)
  default     = []
}

variable "private_subnets" {
  description = "A list of private subnet CIDR blocks."
  type        = list(string)
  default     = []
}

variable "intra_subnets" {
  description = "A list of intra (isolated) subnet CIDR blocks."
  type        = list(string)
  default     = []
}

variable "public_subnet_names" {
  description = "Optional explicit list of public subnet Name tags. Overrides generated names."
  type        = list(string)
  default     = []
}

variable "private_subnet_names" {
  description = "Optional explicit list of private subnet Name tags. Overrides generated names."
  type        = list(string)
  default     = []
}

variable "intra_subnet_names" {
  description = "Optional explicit list of intra subnet Name tags. Overrides generated names."
  type        = list(string)
  default     = []
}

variable "public_subnet_suffix" {
  description = "Suffix appended to public subnet Name tags."
  type        = string
  default     = "public"
}

variable "private_subnet_suffix" {
  description = "Suffix appended to private subnet Name tags."
  type        = string
  default     = "private"
}

variable "intra_subnet_suffix" {
  description = "Suffix appended to intra subnet Name tags."
  type        = string
  default     = "intra"
}

variable "map_public_ip_on_launch" {
  description = "Should be true to auto-assign a public IP on launch for public subnets."
  type        = bool
  default     = false
}

variable "create_igw" {
  description = "Controls if an Internet Gateway should be created for the public subnets."
  type        = bool
  default     = true
}

variable "enable_nat_gateway" {
  description = "Controls if NAT Gateways (and associated EIPs) should be created for private subnets."
  type        = bool
  default     = false
}

variable "tags" {
  description = "A map of tags to add to all resources."
  type        = map(string)
  default     = {}
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  azs = length(var.azs) > 0 ? var.azs : data.aws_availability_zones.available.names

  public_subnet_count  = var.create_vpc ? length(var.public_subnets) : 0
  private_subnet_count = var.create_vpc ? length(var.private_subnets) : 0
  intra_subnet_count   = var.create_vpc ? length(var.intra_subnets) : 0

  nat_gateway_count = var.enable_nat_gateway ? min(length(var.private_subnets), length(var.public_subnets)) : 0

  common_tags = merge(var.tags, { ManagedBy = "terraform" })
}

resource "aws_vpc" "this" {
  count = var.create_vpc ? 1 : 0

  cidr_block           = var.vpc_cidr
  enable_dns_hostnames = var.enable_dns_hostnames
  enable_dns_support   = var.enable_dns_support

  tags = merge(local.common_tags, {
    Name = var.name
  })
}

resource "aws_internet_gateway" "this" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.common_tags, {
    Name = "${var.name}-igw"
  })
}

resource "aws_subnet" "public" {
  count = local.public_subnet_count

  vpc_id                  = aws_vpc.this[0].id
  cidr_block              = var.public_subnets[count.index]
  availability_zone       = local.azs[count.index % length(local.azs)]
  map_public_ip_on_launch = var.map_public_ip_on_launch

  tags = merge(local.common_tags, {
    Name = try(
      var.public_subnet_names[count.index],
      "${var.name}-${var.public_subnet_suffix}-${local.azs[count.index % length(local.azs)]}"
    )
  })
}

resource "aws_subnet" "private" {
  count = local.private_subnet_count

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.private_subnets[count.index]
  availability_zone = local.azs[count.index % length(local.azs)]

  tags = merge(local.common_tags, {
    Name = try(
      var.private_subnet_names[count.index],
      "${var.name}-${var.private_subnet_suffix}-${local.azs[count.index % length(local.azs)]}"
    )
  })
}

resource "aws_subnet" "intra" {
  count = local.intra_subnet_count

  vpc_id            = aws_vpc.this[0].id
  cidr_block        = var.intra_subnets[count.index]
  availability_zone = local.azs[count.index % length(local.azs)]

  tags = merge(local.common_tags, {
    Name = try(
      var.intra_subnet_names[count.index],
      "${var.name}-${var.intra_subnet_suffix}-${local.azs[count.index % length(local.azs)]}"
    )
  })
}

resource "aws_route_table" "public" {
  count = var.create_vpc && length(var.public_subnets) > 0 ? 1 : 0

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.common_tags, {
    Name = "${var.name}-${var.public_subnet_suffix}-rt"
  })
}

resource "aws_route" "public_internet_gateway" {
  count = var.create_vpc && var.create_igw && length(var.public_subnets) > 0 ? 1 : 0

  route_table_id         = aws_route_table.public[0].id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.this[0].id
}

resource "aws_route_table_association" "public" {
  count = local.public_subnet_count

  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public[0].id
}

resource "aws_eip" "nat" {
  count = var.create_vpc ? local.nat_gateway_count : 0

  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${var.name}-nat-eip-${count.index}"
  })
}

resource "aws_nat_gateway" "this" {
  count = var.create_vpc ? local.nat_gateway_count : 0

  allocation_id = aws_eip.nat[count.index].id
  subnet_id     = aws_subnet.public[count.index % length(aws_subnet.public)].id

  tags = merge(local.common_tags, {
    Name = "${var.name}-nat-${count.index}"
  })

  depends_on = [aws_internet_gateway.this]
}

resource "aws_route_table" "private" {
  count = local.private_subnet_count

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.common_tags, {
    Name = "${var.name}-${var.private_subnet_suffix}-rt-${count.index}"
  })
}

resource "aws_route" "private_nat_gateway" {
  count = var.create_vpc && var.enable_nat_gateway && local.nat_gateway_count > 0 ? length(var.private_subnets) : 0

  route_table_id         = aws_route_table.private[count.index].id
  destination_cidr_block = "0.0.0.0/0"
  nat_gateway_id         = aws_nat_gateway.this[count.index % local.nat_gateway_count].id
}

resource "aws_route_table_association" "private" {
  count = local.private_subnet_count

  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private[count.index].id
}

resource "aws_route_table" "intra" {
  count = local.intra_subnet_count

  vpc_id = aws_vpc.this[0].id

  tags = merge(local.common_tags, {
    Name = "${var.name}-${var.intra_subnet_suffix}-rt-${count.index}"
  })
}

resource "aws_route_table_association" "intra" {
  count = local.intra_subnet_count

  subnet_id      = aws_subnet.intra[count.index].id
  route_table_id = aws_route_table.intra[count.index].id
}

output "vpc_id" {
  description = "The ID of the VPC."
  value       = try(aws_vpc.this[0].id, null)
}

output "vpc_cidr_block" {
  description = "The CIDR block of the VPC."
  value       = try(aws_vpc.this[0].cidr_block, null)
}

output "internet_gateway_id" {
  description = "The ID of the Internet Gateway."
  value       = try(aws_internet_gateway.this[0].id, null)
}

output "public_subnet_ids" {
  description = "List of public subnet IDs."
  value       = aws_subnet.public[*].id
}

output "private_subnet_ids" {
  description = "List of private subnet IDs."
  value       = aws_subnet.private[*].id
}

output "intra_subnet_ids" {
  description = "List of intra (isolated) subnet IDs."
  value       = aws_subnet.intra[*].id
}

output "public_route_table_id" {
  description = "The ID of the public route table."
  value       = try(aws_route_table.public[0].id, null)
}

output "private_route_table_ids" {
  description = "List of private route table IDs."
  value       = aws_route_table.private[*].id
}

output "intra_route_table_ids" {
  description = "List of intra (isolated) route table IDs."
  value       = aws_route_table.intra[*].id
}

output "nat_gateway_ids" {
  description = "List of NAT Gateway IDs."
  value       = aws_nat_gateway.this[*].id
}

output "nat_gateway_public_ips" {
  description = "List of public Elastic IPs allocated to the NAT Gateways."
  value       = aws_eip.nat[*].public_ip
}

###############################################################################
# Variables
###############################################################################

variable "api_type" {
  description = "Type of API Gateway to provision: 'http' (API Gateway v2) or 'rest' (API Gateway v1)."
  type        = string
  default     = "http"

  validation {
    condition     = contains(["http", "rest"], var.api_type)
    error_message = "api_type must be either \"http\" or \"rest\"."
  }
}

variable "api_name" {
  description = "Name of the API Gateway."
  type        = string
  default     = "benchmark-api"
}

variable "environment" {
  description = "Environment name used to name API stages (<environment>-stage)."
  type        = string
  default     = "dev"
}

variable "vpc_cidr" {
  description = "CIDR block of the VPC created to host VPC link connectivity."
  type        = string
  default     = "10.0.0.0/16"
}

variable "private_subnet_cidrs" {
  description = "CIDR blocks for the private subnets used by VPC links and load balancers."
  type        = list(string)
  default     = ["10.0.10.0/24", "10.0.11.0/24"]
}

variable "enable_vpc_link" {
  description = "Whether to provision VPC link infrastructure (private subnets, load balancers and VPC links)."
  type        = bool
  default     = false
}

variable "nlb_target_port" {
  description = "TCP port the NLB target group forwards to on the target ALB."
  type        = number
  default     = 443
}

variable "health_check_path" {
  description = "Path used for the NLB target group HTTPS health check."
  type        = string
  default     = "/health"
}

variable "enable_custom_domain" {
  description = "Whether to provision custom domain names, regional ACM certificates and Route 53 alias A records."
  type        = bool
  default     = false
}

variable "domain_name" {
  description = "Fully qualified custom domain name for the API."
  type        = string
  default     = "api.example.com"
}

variable "hosted_zone_name" {
  description = "Route 53 hosted zone name used for ACM DNS validation and alias records."
  type        = string
  default     = "example.com"
}

variable "enable_custom_authorizer" {
  description = "Whether to provision a custom Lambda authorizer (Node.js 16.x)."
  type        = bool
  default     = false
}

variable "authorizer_identity_source" {
  description = "REST API identity source for the custom authorizer."
  type        = string
  default     = "method.request.header.Authorization"
}

variable "enable_ip_restriction" {
  description = "Whether to attach an IP source restriction resource policy to the REST API."
  type        = bool
  default     = false
}

variable "allowed_ip_ranges" {
  description = "CIDR ranges allowed to invoke the REST API when IP restriction is enabled."
  type        = list(string)
  default     = ["0.0.0.0/0"]
}

variable "http_routes" {
  description = "List of HTTP API route keys (for example \"GET /items\")."
  type        = list(string)
  default     = ["GET /items"]
}

variable "rest_resources" {
  description = "Map of REST API resources. The key is a logical name and parent_path references another key."
  type = map(object({
    path_part   = string
    parent_path = optional(string, null)
  }))
  default = {
    items = { path_part = "items" }
    item  = { path_part = "{id}", parent_path = "items" }
  }
}

variable "rest_methods" {
  description = "Map of REST API methods. request_parameters carries path parameter overrides."
  type = map(object({
    resource_key       = string
    http_method        = string
    authorization      = optional(string, "NONE")
    request_parameters = optional(map(bool), {})
  }))
  default = {
    get_items = {
      resource_key = "items"
      http_method  = "GET"
    }
    get_item = {
      resource_key       = "item"
      http_method        = "GET"
      request_parameters = { "method.request.path.id" = true }
    }
  }
}

variable "usage_plan_quota_limit" {
  description = "Number of requests allowed per quota period for the REST API usage plan."
  type        = number
  default     = 10000
}

variable "usage_plan_quota_period" {
  description = "Quota period for the REST API usage plan."
  type        = string
  default     = "MONTH"
}

variable "usage_plan_rate_limit" {
  description = "Steady-state request rate limit for the REST API usage plan."
  type        = number
  default     = 100
}

variable "usage_plan_burst_limit" {
  description = "Burst request limit for the REST API usage plan."
  type        = number
  default     = 200
}

###############################################################################
# Locals and provider metadata
###############################################################################

locals {
  is_http = var.api_type == "http"
  is_rest = var.api_type == "rest"

  stage_name = "${var.environment}-stage"

  create_network = var.enable_vpc_link

  create_backend = (
    (local.is_http && length(var.http_routes) > 0) ||
    (local.is_rest && length(var.rest_methods) > 0)
  )

  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    ApiName     = var.api_name
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

###############################################################################
# Network (used for VPC links)
###############################################################################

resource "aws_vpc" "main" {
  count                = local.create_network ? 1 : 0
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.tags, { Name = "${var.api_name}-vpc" })
}

resource "aws_subnet" "private" {
  count             = local.create_network ? length(var.private_subnet_cidrs) : 0
  vpc_id            = aws_vpc.main[0].id
  cidr_block        = var.private_subnet_cidrs[count.index]
  availability_zone = data.aws_availability_zones.available.names[count.index]

  tags = merge(local.tags, { Name = "${var.api_name}-private-${count.index}" })
}

resource "aws_security_group" "vpc_link" {
  count       = local.create_network ? 1 : 0
  name        = "${var.api_name}-vpc-link-sg"
  description = "Security group for the API Gateway VPC link elastic network interfaces"
  vpc_id      = aws_vpc.main[0].id

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${var.api_name}-vpc-link-sg" })
}

resource "aws_security_group" "alb" {
  count       = local.is_rest && local.create_network ? 1 : 0
  name        = "${var.api_name}-alb-sg"
  description = "Security group for the internal ALB fronted by the NLB VPC link"
  vpc_id      = aws_vpc.main[0].id

  ingress {
    description = "Allow HTTPS traffic from within the VPC"
    from_port   = var.nlb_target_port
    to_port     = var.nlb_target_port
    protocol    = "tcp"
    cidr_blocks = [var.vpc_cidr]
  }

  egress {
    description = "Allow all outbound traffic"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = merge(local.tags, { Name = "${var.api_name}-alb-sg" })
}

###############################################################################
# Shared backend Lambda used for API integrations
###############################################################################

data "archive_file" "backend" {
  count       = local.create_backend ? 1 : 0
  type        = "zip"
  output_path = "${path.module}/backend.zip"

  source {
    filename = "index.js"
    content  = <<-EOT
      exports.handler = async (event) => {
        return {
          statusCode: 200,
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            message: "OK",
            path: event.rawPath || event.path || "/",
            method: event.requestContext && event.requestContext.http
              ? event.requestContext.http.method
              : (event.httpMethod || "GET"),
          }),
        };
      };
    EOT
  }
}

resource "aws_cloudwatch_log_group" "backend" {
  count             = local.create_backend ? 1 : 0
  name              = "/aws/lambda/${var.api_name}-backend"
  retention_in_days = 14

  tags = local.tags
}

resource "aws_iam_role" "backend" {
  count = local.create_backend ? 1 : 0
  name  = "${var.api_name}-backend-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "backend" {
  count = local.create_backend ? 1 : 0
  name  = "${var.api_name}-backend-policy"
  role  = aws_iam_role.backend[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Resource = [
        aws_cloudwatch_log_group.backend[0].arn,
        "${aws_cloudwatch_log_group.backend[0].arn}:*"
      ]
    }]
  })
}

resource "aws_lambda_function" "backend" {
  count            = local.create_backend ? 1 : 0
  function_name    = "${var.api_name}-backend"
  role             = aws_iam_role.backend[0].arn
  runtime          = "nodejs18.x"
  handler          = "index.handler"
  filename         = data.archive_file.backend[0].output_path
  source_code_hash = data.archive_file.backend[0].output_base64sha256

  tags = local.tags
}

###############################################################################
# Custom Lambda authorizer (Node.js 16.x)
###############################################################################

data "archive_file" "authorizer" {
  count       = var.enable_custom_authorizer ? 1 : 0
  type        = "zip"
  output_path = "${path.module}/authorizer.zip"

  source {
    filename = "index.js"
    content  = <<-EOT
      exports.handler = async (event) => {
        const header =
          event.authorizationToken ||
          (event.headers && (event.headers.authorization || event.headers.Authorization)) ||
          "";

        if (!header || header === "unauthorized") {
          throw new Error("Unauthorized");
        }

        return {
          principalId: "user",
          policyDocument: {
            Version: "2012-10-17",
            Statement: [
              {
                Action: "execute-api:Invoke",
                Effect: "Allow",
                Resource: event.methodArn || "*",
              },
            ],
          },
          context: {
            scope: "read",
          },
        };
      };
    EOT
  }
}

resource "aws_cloudwatch_log_group" "authorizer" {
  count             = var.enable_custom_authorizer ? 1 : 0
  name              = "/aws/lambda/${var.api_name}-authorizer"
  retention_in_days = 14

  tags = local.tags
}

resource "aws_iam_role" "authorizer" {
  count = var.enable_custom_authorizer ? 1 : 0
  name  = "${var.api_name}-authorizer-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "lambda.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "authorizer" {
  count = var.enable_custom_authorizer ? 1 : 0
  name  = "${var.api_name}-authorizer-policy"
  role  = aws_iam_role.authorizer[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "logs:CreateLogStream",
        "logs:PutLogEvents"
      ]
      Resource = [
        aws_cloudwatch_log_group.authorizer[0].arn,
        "${aws_cloudwatch_log_group.authorizer[0].arn}:*"
      ]
    }]
  })
}

resource "aws_lambda_function" "authorizer" {
  count            = var.enable_custom_authorizer ? 1 : 0
  function_name    = "${var.api_name}-authorizer"
  role             = aws_iam_role.authorizer[0].arn
  runtime          = "nodejs16.x"
  handler          = "index.handler"
  filename         = data.archive_file.authorizer[0].output_path
  source_code_hash = data.archive_file.authorizer[0].output_base64sha256

  tags = local.tags
}

resource "aws_iam_role" "authorizer_invocation" {
  count = local.is_rest && var.enable_custom_authorizer ? 1 : 0
  name  = "${var.api_name}-authorizer-invocation-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect    = "Allow"
      Principal = { Service = "apigateway.amazonaws.com" }
      Action    = "sts:AssumeRole"
    }]
  })

  tags = local.tags
}

resource "aws_iam_role_policy" "authorizer_invocation" {
  count = local.is_rest && var.enable_custom_authorizer ? 1 : 0
  name  = "${var.api_name}-authorizer-invocation-policy"
  role  = aws_iam_role.authorizer_invocation[0].id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect   = "Allow"
      Action   = "lambda:InvokeFunction"
      Resource = aws_lambda_function.authorizer[0].arn
    }]
  })
}

###############################################################################
# HTTP API (API Gateway v2)
###############################################################################

resource "aws_apigatewayv2_api" "http" {
  count         = local.is_http ? 1 : 0
  name          = var.api_name
  description   = "HTTP API managed by Terraform"
  protocol_type = "HTTP"

  tags = local.tags
}

resource "aws_apigatewayv2_integration" "http_default" {
  count                  = local.is_http && length(var.http_routes) > 0 ? 1 : 0
  api_id                 = aws_apigatewayv2_api.http[0].id
  integration_type       = "AWS_PROXY"
  integration_method     = "POST"
  integration_uri        = aws_lambda_function.backend[0].invoke_arn
  payload_format_version = "2.0"
}

resource "aws_apigatewayv2_route" "http" {
  for_each = toset(local.is_http ? var.http_routes : [])

  api_id               = aws_apigatewayv2_api.http[0].id
  route_key            = each.value
  target               = "integrations/${aws_apigatewayv2_integration.http_default[0].id}"
  authorization_type   = var.enable_custom_authorizer ? "CUSTOM" : "NONE"
  authorizer_id        = var.enable_custom_authorizer ? aws_apigatewayv2_authorizer.http[0].id : null
}

resource "aws_apigatewayv2_authorizer" "http" {
  count = local.is_http && var.enable_custom_authorizer ? 1 : 0

  api_id                            = aws_apigatewayv2_api.http[0].id
  authorizer_type                   = "REQUEST"
  name                              = "${var.api_name}-authorizer"
  authorizer_uri                    = aws_lambda_function.authorizer[0].invoke_arn
  authorizer_payload_format_version = "2.0"
  enable_simple_responses           = false
  identity_sources                  = ["$request.header.Authorization"]
}

resource "aws_apigatewayv2_stage" "http" {
  count       = local.is_http ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  name        = local.stage_name
  auto_deploy = true

  tags = local.tags
}

resource "aws_apigatewayv2_vpc_link" "http" {
  count              = local.is_http && local.create_network ? 1 : 0
  name               = "${var.api_name}-vpc-link"
  security_group_ids = [aws_security_group.vpc_link[0].id]
  subnet_ids         = aws_subnet.private[*].id

  tags = local.tags
}

resource "aws_lambda_permission" "backend_http" {
  count         = local.is_http && local.create_backend ? 1 : 0
  statement_id  = "AllowHTTPAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.backend[0].function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.http[0].execution_arn}/*/*"
}

resource "aws_lambda_permission" "authorizer_http" {
  count         = local.is_http && var.enable_custom_authorizer ? 1 : 0
  statement_id  = "AllowHTTPAPIGatewayInvokeAuthorizer"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer[0].function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_apigatewayv2_api.http[0].execution_arn}/authorizers/${aws_apigatewayv2_authorizer.http[0].id}"
}

###############################################################################
# REST API (API Gateway v1)
###############################################################################

data "aws_iam_policy_document" "rest_policy" {
  count = local.is_rest && var.enable_ip_restriction ? 1 : 0

  statement {
    sid       = "AllowInvokeFromAllowedRanges"
    effect    = "Allow"
    actions   = ["execute-api:Invoke"]
    resources = ["execute-api:/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }
  }

  statement {
    sid       = "DenyInvokeOutsideAllowedRanges"
    effect    = "Deny"
    actions   = ["execute-api:Invoke"]
    resources = ["execute-api:/*"]

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    condition {
      test     = "NotIpAddress"
      variable = "aws:SourceIp"
      values   = var.allowed_ip_ranges
    }
  }
}

resource "aws_api_gateway_rest_api" "rest" {
  count       = local.is_rest ? 1 : 0
  name        = var.api_name
  description = "REST API managed by Terraform"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  policy = var.enable_ip_restriction ? data.aws_iam_policy_document.rest_policy[0].json : null

  tags = local.tags
}

resource "aws_api_gateway_resource" "rest" {
  for_each = local.is_rest ? var.rest_resources : {}

  rest_api_id = aws_api_gateway_rest_api.rest[0].id
  parent_id = (
    each.value.parent_path == null
    ? aws_api_gateway_rest_api.rest[0].root_resource_id
    : aws_api_gateway_resource.rest[each.value.parent_path].id
  )
  path_part = each.value.path_part
}

resource "aws_api_gateway_method" "rest" {
  for_each = local.is_rest ? var.rest_methods : {}

  rest_api_id        = aws_api_gateway_rest_api.rest[0].id
  resource_id        = aws_api_gateway_resource.rest[each.value.resource_key].id
  http_method        = each.value.http_method
  authorization      = each.value.authorization
  authorizer_id      = each.value.authorization == "CUSTOM" ? aws_api_gateway_authorizer.rest[0].id : null
  request_parameters = each.value.request_parameters
}

resource "aws_api_gateway_integration" "rest" {
  for_each = local.is_rest ? var.rest_methods : {}

  rest_api_id             = aws_api_gateway_rest_api.rest[0].id
  resource_id             = aws_api_gateway_resource.rest[each.value.resource_key].id
  http_method             = aws_api_gateway_method.rest[each.key].http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.backend[0].invoke_arn
}

resource "aws_api_gateway_authorizer" "rest" {
  count = local.is_rest && var.enable_custom_authorizer ? 1 : 0

  name                   = "${var.api_name}-authorizer"
  rest_api_id            = aws_api_gateway_rest_api.rest[0].id
  authorizer_uri         = aws_lambda_function.authorizer[0].invoke_arn
  authorizer_credentials = aws_iam_role.authorizer_invocation[0].arn
  type                   = "TOKEN"
  identity_source        = var.authorizer_identity_source
}

resource "aws_api_gateway_deployment" "rest" {
  count       = local.is_rest ? 1 : 0
  rest_api_id = aws_api_gateway_rest_api.rest[0].id

  triggers = {
    redeployment = sha1(jsonencode([
      aws_api_gateway_resource.rest,
      aws_api_gateway_method.rest,
      aws_api_gateway_integration.rest,
    ]))
  }

  lifecycle {
    create_before_destroy = true
  }
}

resource "aws_api_gateway_stage" "rest" {
  count         = local.is_rest ? 1 : 0
  deployment_id = aws_api_gateway_deployment.rest[0].id
  rest_api_id   = aws_api_gateway_rest_api.rest[0].id
  stage_name    = local.stage_name

  tags = local.tags
}

resource "aws_api_gateway_usage_plan" "rest" {
  count = local.is_rest ? 1 : 0
  name  = "${var.api_name}-usage-plan"

  api_stages {
    api_id = aws_api_gateway_rest_api.rest[0].id
    stage  = aws_api_gateway_stage.rest[0].stage_name
  }

  quota_settings {
    limit  = var.usage_plan_quota_limit
    period = var.usage_plan_quota_period
  }

  throttle_settings {
    rate_limit  = var.usage_plan_rate_limit
    burst_limit = var.usage_plan_burst_limit
  }

  tags = local.tags
}

resource "aws_api_gateway_api_key" "rest" {
  count       = local.is_rest ? 1 : 0
  name        = "${var.api_name}-key"
  description = "API key for the ${var.api_name} usage plan"
  enabled     = true

  tags = local.tags
}

resource "aws_api_gateway_usage_plan_key" "rest" {
  count         = local.is_rest ? 1 : 0
  key_id        = aws_api_gateway_api_key.rest[0].id
  key_type      = "API_KEY"
  usage_plan_id = aws_api_gateway_usage_plan.rest[0].id
}

resource "aws_ssm_parameter" "api_key" {
  count       = local.is_rest ? 1 : 0
  name        = "/${var.api_name}/${var.environment}/api-key"
  description = "API key for the ${var.api_name} REST API usage plan"
  type        = "SecureString"
  value       = aws_api_gateway_api_key.rest[0].value

  tags = local.tags
}

resource "aws_lambda_permission" "backend_rest" {
  count         = local.is_rest && local.create_backend ? 1 : 0
  statement_id  = "AllowRESTAPIGatewayInvoke"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.backend[0].function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.rest[0].execution_arn}/*/*"
}

resource "aws_lambda_permission" "authorizer_rest" {
  count         = local.is_rest && var.enable_custom_authorizer ? 1 : 0
  statement_id  = "AllowRESTAPIGatewayInvokeAuthorizer"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.authorizer[0].function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.rest[0].execution_arn}/authorizers/${aws_api_gateway_authorizer.rest[0].id}"
}

###############################################################################
# REST API VPC link infrastructure (internal ALB + NLB)
###############################################################################

resource "aws_lb" "alb" {
  count              = local.is_rest && local.create_network ? 1 : 0
  name               = substr("${var.api_name}-alb", 0, 32)
  internal           = true
  load_balancer_type = "application"
  security_groups    = [aws_security_group.alb[0].id]
  subnets            = aws_subnet.private[*].id

  tags = merge(local.tags, { Name = "${var.api_name}-alb" })
}

resource "aws_lb" "nlb" {
  count              = local.is_rest && local.create_network ? 1 : 0
  name               = substr("${var.api_name}-nlb", 0, 32)
  internal           = true
  load_balancer_type = "network"
  subnets            = aws_subnet.private[*].id

  tags = merge(local.tags, { Name = "${var.api_name}-nlb" })
}

resource "aws_lb_target_group" "nlb" {
  count       = local.is_rest && local.create_network ? 1 : 0
  name        = substr("${var.api_name}-nlb-tg", 0, 32)
  port        = var.nlb_target_port
  protocol    = "TCP"
  target_type = "alb"
  vpc_id      = aws_vpc.main[0].id

  health_check {
    enabled             = true
    protocol            = "HTTPS"
    port                = "traffic-port"
    path                = var.health_check_path
    healthy_threshold   = 3
    unhealthy_threshold = 3
    interval            = 30
    timeout             = 10
    matcher             = "200-399"
  }

  tags = merge(local.tags, { Name = "${var.api_name}-nlb-tg" })
}

resource "aws_lb_target_group_attachment" "nlb" {
  count            = local.is_rest && local.create_network ? 1 : 0
  target_group_arn = aws_lb_target_group.nlb[0].arn
  target_id        = aws_lb.alb[0].id
  port             = var.nlb_target_port
}

resource "aws_lb_listener" "nlb" {
  count             = local.is_rest && local.create_network ? 1 : 0
  load_balancer_arn = aws_lb.nlb[0].arn
  port              = var.nlb_target_port
  protocol          = "TCP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.nlb[0].arn
  }

  tags = local.tags
}

resource "aws_api_gateway_vpc_link" "rest" {
  count       = local.is_rest && local.create_network ? 1 : 0
  name        = "${var.api_name}-vpc-link"
  target_arns = [aws_lb.nlb[0].arn]

  tags = local.tags
}

###############################################################################
# Custom domains, regional ACM certificates and Route 53 alias records
###############################################################################

resource "aws_route53_zone" "this" {
  count = var.enable_custom_domain ? 1 : 0
  name  = var.hosted_zone_name

  tags = local.tags
}

resource "aws_acm_certificate" "this" {
  count             = var.enable_custom_domain ? 1 : 0
  domain_name       = var.domain_name
  validation_method = "DNS"

  lifecycle {
    create_before_destroy = true
  }

  tags = local.tags
}

resource "aws_route53_record" "cert_validation" {
  for_each = var.enable_custom_domain ? {
    for dvo in aws_acm_certificate.this[0].domain_validation_options : dvo.domain_name => {
      name   = dvo.resource_record_name
      type   = dvo.resource_record_type
      record = dvo.resource_record_value
    }
  } : {}

  zone_id = aws_route53_zone.this[0].zone_id
  name    = each.value.name
  type    = each.value.type
  records = [each.value.record]
  ttl     = 60
}

resource "aws_acm_certificate_validation" "this" {
  count                   = var.enable_custom_domain ? 1 : 0
  certificate_arn         = aws_acm_certificate.this[0].arn
  validation_record_fqdns = [for record in aws_route53_record.cert_validation : record.fqdn]
}

resource "aws_apigatewayv2_domain_name" "http" {
  count       = local.is_http && var.enable_custom_domain ? 1 : 0
  domain_name = var.domain_name

  domain_name_configuration {
    certificate_arn = aws_acm_certificate_validation.this[0].certificate_arn
    endpoint_type   = "REGIONAL"
    security_policy = "TLS_1_2"
  }

  tags = local.tags
}

resource "aws_apigatewayv2_api_mapping" "http" {
  count       = local.is_http && var.enable_custom_domain ? 1 : 0
  api_id      = aws_apigatewayv2_api.http[0].id
  domain_name = aws_apigatewayv2_domain_name.http[0].id
  stage       = aws_apigatewayv2_stage.http[0].id
}

resource "aws_route53_record" "http_alias" {
  count   = local.is_http && var.enable_custom_domain ? 1 : 0
  zone_id = aws_route53_zone.this[0].zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].target_domain_name
    zone_id                = aws_apigatewayv2_domain_name.http[0].domain_name_configuration[0].hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_api_gateway_domain_name" "rest" {
  count                    = local.is_rest && var.enable_custom_domain ? 1 : 0
  domain_name              = var.domain_name
  regional_certificate_arn = aws_acm_certificate_validation.this[0].certificate_arn
  security_policy          = "TLS_1_2"

  endpoint_configuration {
    types = ["REGIONAL"]
  }

  tags = local.tags
}

resource "aws_api_gateway_base_path_mapping" "rest" {
  count       = local.is_rest && var.enable_custom_domain ? 1 : 0
  api_id      = aws_api_gateway_rest_api.rest[0].id
  stage_name  = aws_api_gateway_stage.rest[0].stage_name
  domain_name = aws_api_gateway_domain_name.rest[0].domain_name
}

resource "aws_route53_record" "rest_alias" {
  count   = local.is_rest && var.enable_custom_domain ? 1 : 0
  zone_id = aws_route53_zone.this[0].zone_id
  name    = var.domain_name
  type    = "A"

  alias {
    name                   = aws_api_gateway_domain_name.rest[0].regional_domain_name
    zone_id                = aws_api_gateway_domain_name.rest[0].regional_zone_id
    evaluate_target_health = false
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "trail_name" {
  description = "Name of the CloudTrail trail."
  type        = string
  default     = "cloudtrail"
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default     = {}
}

# --- S3 -------------------------------------------------------------------
variable "s3_bucket_name" {
  description = "Name of the S3 bucket for CloudTrail logs. If empty, a name is generated dynamically."
  type        = string
  default     = ""
}

variable "s3_force_destroy" {
  description = "Whether to force destroy the S3 bucket even when it contains objects."
  type        = bool
  default     = true
}

variable "s3_versioning" {
  description = "Whether to enable versioning on the CloudTrail S3 bucket."
  type        = bool
  default     = false
}

variable "s3_key_prefix" {
  description = "Optional S3 key prefix for CloudTrail log delivery."
  type        = string
  default     = ""
}

# --- KMS ------------------------------------------------------------------
variable "kms_key_deletion_window_in_days" {
  description = "Number of days before the CloudTrail KMS key is deleted."
  type        = number
  default     = 30
}

variable "kms_key_alias_prefix" {
  description = "Prefix used for the CloudTrail KMS key alias."
  type        = string
  default     = "alias/cloudtrail"
}

variable "kms_key_policy_role_arn" {
  description = "Optional IAM role ARN granted permission to decrypt CloudTrail logs with the KMS key."
  type        = string
  default     = ""
}

# --- CloudWatch Logs ------------------------------------------------------
variable "cloudwatch_log_retention_days" {
  description = "Retention in days for the CloudTrail CloudWatch log group."
  type        = number
  default     = 90
}

# --- CloudTrail -----------------------------------------------------------
variable "enable_log_file_validation" {
  description = "Whether CloudTrail validates the integrity of log files."
  type        = bool
  default     = true
}

variable "include_global_service_events" {
  description = "Whether to include global service events in the trail."
  type        = bool
  default     = true
}

variable "is_multi_region_trail" {
  description = "Whether the trail applies to all regions."
  type        = bool
  default     = true
}

variable "enable_logging" {
  description = "Whether logging is enabled for the trail."
  type        = bool
  default     = true
}

variable "is_organization_trail" {
  description = "Whether the trail is an organization trail."
  type        = bool
  default     = false
}

variable "event_selector_read_write_type" {
  description = "Read/write type for the CloudTrail event selector (All, ReadOnly, WriteOnly)."
  type        = string
  default     = "All"
}

variable "event_selector_include_management_events" {
  description = "Whether the event selector includes management events."
  type        = bool
  default     = true
}

variable "data_resource_selectors" {
  description = "List of data resource selectors for the CloudTrail event selector."
  type = list(object({
    type   = string
    values = list(string)
  }))
  default = []
}

variable "insight_selectors" {
  description = "List of insight types to enable on the trail."
  type        = list(string)
  default     = []
}

# --- SNS ------------------------------------------------------------------
variable "sns_create_topic" {
  description = "Whether to create a dedicated SNS topic for CloudTrail notifications."
  type        = bool
  default     = false
}

variable "sns_topic_arn" {
  description = "Existing SNS topic ARN used when no SNS topic is created."
  type        = string
  default     = ""
}

###############################################################################
# Data sources
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

resource "random_string" "suffix" {
  length  = 8
  special = false
  upper   = false
  lower   = true
  numeric = true
}

###############################################################################
# Locals
###############################################################################

locals {
  account_id = data.aws_caller_identity.current.account_id
  region     = data.aws_region.current.name
  partition  = data.aws_partition.current.partition

  trail_arn = "arn:${local.partition}:cloudtrail:${local.region}:${local.account_id}:trail/${var.trail_name}"

  s3_bucket_name = var.s3_bucket_name != "" ? var.s3_bucket_name : "aws-cloudtrail-logs-${local.account_id}-${local.region}-${random_string.suffix.result}"

  cloudwatch_log_group_name = "/aws/cloudtrail/${var.trail_name}"

  kms_key_alias = "${var.kms_key_alias_prefix}-${var.trail_name}"

  created_sns_topic_name  = try(aws_sns_topic.cloudtrail[0].name, null)
  existing_sns_topic_name = var.sns_topic_arn != "" ? element(reverse(split(":", var.sns_topic_arn)), 0) : null
  sns_topic_name          = var.sns_create_topic ? local.created_sns_topic_name : local.existing_sns_topic_name

  common_tags = merge(
    {
      ManagedBy = "terraform"
      Service   = "cloudtrail"
    },
    var.tags
  )
}

###############################################################################
# KMS key for CloudTrail log encryption
###############################################################################

data "aws_iam_policy_document" "kms" {
  statement {
    sid    = "EnableRootAccountAccess"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowCloudTrailToEncryptLogs"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]

    condition {
      test     = "StringLike"
      variable = "kms:EncryptionContext:aws:cloudtrail:arn"
      values   = ["arn:${local.partition}:cloudtrail:*:${local.account_id}:trail/*"]
    }
  }

  statement {
    sid    = "AllowCloudWatchLogsToUseKey"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["logs.${local.region}.amazonaws.com"]
    }

    actions = [
      "kms:Encrypt*",
      "kms:Decrypt*",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowS3BucketEncryption"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = [
      "kms:GenerateDataKey*",
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }

  dynamic "statement" {
    for_each = var.kms_key_policy_role_arn != "" ? [var.kms_key_policy_role_arn] : []

    content {
      sid    = "AllowProvidedRoleToDecryptLogs"
      effect = "Allow"

      principals {
        type        = "AWS"
        identifiers = [statement.value]
      }

      actions = [
        "kms:Decrypt",
        "kms:DescribeKey",
      ]

      resources = ["*"]
    }
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "KMS key used to encrypt CloudTrail logs"
  deletion_window_in_days = var.kms_key_deletion_window_in_days
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.kms.json
  tags                    = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "cloudtrail" {
  name          = local.kms_key_alias
  target_key_id = aws_kms_key.cloudtrail.key_id
}

###############################################################################
# S3 bucket for CloudTrail log storage
###############################################################################

resource "aws_s3_bucket" "cloudtrail" {
  bucket        = local.s3_bucket_name
  force_destroy = var.s3_force_destroy
  tags          = local.common_tags
}

resource "aws_s3_bucket_public_access_block" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id

  versioning_configuration {
    status = var.s3_versioning ? "Enabled" : "Suspended"
  }
}

data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid    = "AWSCloudTrailAclCheck"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.cloudtrail.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }

  statement {
    sid    = "AWSCloudTrailWrite"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.cloudtrail.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail" {
  bucket = aws_s3_bucket.cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json
}

###############################################################################
# CloudWatch Log Group + IAM role for CloudTrail log ingestion
###############################################################################

resource "aws_cloudwatch_log_group" "cloudtrail" {
  name              = local.cloudwatch_log_group_name
  retention_in_days = var.cloudwatch_log_retention_days
  tags              = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch_assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "cloudtrail_cloudwatch" {
  name               = "${var.trail_name}-cloudwatch-logs-role"
  assume_role_policy = data.aws_iam_policy_document.cloudtrail_cloudwatch_assume.json
  tags               = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_cloudwatch" {
  statement {
    sid    = "AllowCloudTrailToWriteToCloudWatchLogs"
    effect = "Allow"

    actions = [
      "logs:CreateLogStream",
      "logs:PutLogEvents",
    ]

    resources = ["${aws_cloudwatch_log_group.cloudtrail.arn}:*"]
  }
}

resource "aws_iam_role_policy" "cloudtrail_cloudwatch" {
  name   = "${var.trail_name}-cloudwatch-logs-policy"
  role   = aws_iam_role.cloudtrail_cloudwatch.id
  policy = data.aws_iam_policy_document.cloudtrail_cloudwatch.json
}

###############################################################################
# Optional SNS topic for CloudTrail notifications
###############################################################################

resource "aws_sns_topic" "cloudtrail" {
  count = var.sns_create_topic ? 1 : 0

  name = "${var.trail_name}-notifications"
  tags = local.common_tags
}

data "aws_iam_policy_document" "cloudtrail_sns" {
  count = var.sns_create_topic ? 1 : 0

  statement {
    sid    = "AllowCloudTrailToPublish"
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    actions   = ["sns:Publish"]
    resources = [aws_sns_topic.cloudtrail[0].arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceArn"
      values   = [local.trail_arn]
    }
  }
}

resource "aws_sns_topic_policy" "cloudtrail" {
  count = var.sns_create_topic ? 1 : 0

  arn    = aws_sns_topic.cloudtrail[0].arn
  policy = data.aws_iam_policy_document.cloudtrail_sns[0].json
}

###############################################################################
# CloudTrail trail
###############################################################################

resource "aws_cloudtrail" "this" {
  name                          = var.trail_name
  s3_bucket_name                = aws_s3_bucket.cloudtrail.id
  s3_key_prefix                 = var.s3_key_prefix != "" ? var.s3_key_prefix : null
  include_global_service_events = var.include_global_service_events
  is_multi_region_trail         = var.is_multi_region_trail
  enable_logging                = var.enable_logging
  enable_log_file_validation    = var.enable_log_file_validation
  is_organization_trail         = var.is_organization_trail
  kms_key_id                    = aws_kms_key.cloudtrail.arn
  cloud_watch_logs_group_arn    = "${aws_cloudwatch_log_group.cloudtrail.arn}:*"
  cloud_watch_logs_role_arn     = aws_iam_role.cloudtrail_cloudwatch.arn
  sns_topic_name                = local.sns_topic_name
  tags                          = local.common_tags

  event_selector {
    read_write_type           = var.event_selector_read_write_type
    include_management_events = var.event_selector_include_management_events

    dynamic "data_resource" {
      for_each = var.data_resource_selectors

      content {
        type   = data_resource.value.type
        values = data_resource.value.values
      }
    }
  }

  dynamic "insight_selector" {
    for_each = var.insight_selectors

    content {
      insight_type = insight_selector.value
    }
  }

  depends_on = [
    aws_s3_bucket_policy.cloudtrail,
    aws_cloudwatch_log_group.cloudtrail,
    aws_iam_role_policy.cloudtrail_cloudwatch,
    aws_sns_topic_policy.cloudtrail,
  ]
}

###############################################################################
# Outputs
###############################################################################

output "trail_arn" {
  description = "ARN of the CloudTrail trail."
  value       = aws_cloudtrail.this.arn
}

output "s3_bucket_name" {
  description = "Name of the CloudTrail S3 log bucket."
  value       = aws_s3_bucket.cloudtrail.id
}

output "s3_bucket_arn" {
  description = "ARN of the CloudTrail S3 log bucket."
  value       = aws_s3_bucket.cloudtrail.arn
}

output "kms_key_arn" {
  description = "ARN of the KMS key used for CloudTrail encryption."
  value       = aws_kms_key.cloudtrail.arn
}

output "kms_key_alias" {
  description = "Alias of the KMS key used for CloudTrail encryption."
  value       = aws_kms_alias.cloudtrail.name
}

output "cloudwatch_log_group_name" {
  description = "Name of the CloudTrail CloudWatch log group."
  value       = aws_cloudwatch_log_group.cloudtrail.name
}

output "cloudwatch_logs_role_arn" {
  description = "ARN of the IAM role used by CloudTrail to write to CloudWatch Logs."
  value       = aws_iam_role.cloudtrail_cloudwatch.arn
}

output "sns_topic_arn" {
  description = "ARN of the SNS topic associated with the trail (created or provided)."
  value       = var.sns_create_topic ? aws_sns_topic.cloudtrail[0].arn : var.sns_topic_arn
}

variable "cluster_name" {
  description = "Name of the EKS cluster; used to derive IAM resource names and tag conditions."
  type        = string
  default     = "legion"
}

###############################################################################
# Data sources (static / well-known lookups only)
###############################################################################

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  partition               = data.aws_partition.current.partition
  managed_policy_arn_base = "arn:${local.partition}:iam::aws:policy"

  cluster_name            = var.cluster_name
  cluster_role_name       = "tf-${local.cluster_name}"
  node_role_name          = "tf-${local.cluster_name}-node"
  autoscaling_policy_name = "eks-worker-autoscaling-${local.cluster_name}"

  tags = {
    Terraform   = "true"
    ClusterName = local.cluster_name
  }
}

###############################################################################
# Assume role trust policies
###############################################################################

data "aws_iam_policy_document" "eks_cluster_assume_role_policy" {
  statement {
    sid     = "EKSClusterAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["eks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "eks_node_assume_role_policy" {
  statement {
    sid     = "EKSNodeAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["ec2.amazonaws.com"]
    }
  }
}

###############################################################################
# EKS control plane (master) role
###############################################################################

resource "aws_iam_role" "eks_cluster" {
  name               = local.cluster_role_name
  description        = "EKS control plane role for the ${local.cluster_name} cluster."
  assume_role_policy = data.aws_iam_policy_document.eks_cluster_assume_role_policy.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "eks_cluster_amazon_eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "${local.managed_policy_arn_base}/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_cluster_amazon_eks_service_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "${local.managed_policy_arn_base}/AmazonEKSServicePolicy"
}

###############################################################################
# EKS worker node role
###############################################################################

resource "aws_iam_role" "eks_node" {
  name               = local.node_role_name
  description        = "EKS worker node role for the ${local.cluster_name} cluster."
  assume_role_policy = data.aws_iam_policy_document.eks_node_assume_role_policy.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "eks_node_amazon_eks_worker_node_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "${local.managed_policy_arn_base}/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_amazon_eks_cni_policy" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "${local.managed_policy_arn_base}/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_node_amazon_ec2_container_registry_read_only" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "${local.managed_policy_arn_base}/AmazonEC2ContainerRegistryReadOnly"
}

###############################################################################
# Cluster Autoscaler custom policy for the worker node role
###############################################################################

data "aws_iam_policy_document" "eks_worker_autoscaling" {
  statement {
    sid    = "AllowGlobalAutoscalingDescribe"
    effect = "Allow"

    actions = [
      "autoscaling:DescribeAutoScalingGroups",
      "autoscaling:DescribeAutoScalingInstances",
      "autoscaling:DescribeLaunchConfigurations",
      "autoscaling:DescribeTags",
      "ec2:DescribeLaunchTemplateVersions",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowAutoscalingCapacityModificationOnOwnedCluster"
    effect = "Allow"

    actions = [
      "autoscaling:SetDesiredCapacity",
      "autoscaling:TerminateInstanceInAutoScalingGroup",
      "autoscaling:UpdateAutoScalingGroup",
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/kubernetes.io/cluster/${local.cluster_name}"
      values   = ["owned"]
    }

    condition {
      test     = "StringEquals"
      variable = "autoscaling:ResourceTag/k8s.io/cluster-autoscaler/enabled"
      values   = ["true"]
    }
  }
}

resource "aws_iam_policy" "eks_worker_autoscaling" {
  name        = local.autoscaling_policy_name
  description = "Cluster Autoscaler permissions for the ${local.cluster_name} EKS worker node role."
  policy      = data.aws_iam_policy_document.eks_worker_autoscaling.json

  tags = local.tags
}

resource "aws_iam_role_policy_attachment" "eks_node_autoscaling" {
  role       = aws_iam_role.eks_node.name
  policy_arn = aws_iam_policy.eks_worker_autoscaling.arn
}

###############################################################################
# EC2 instance profile for the worker nodes
###############################################################################

resource "aws_iam_instance_profile" "eks_node" {
  name = local.node_role_name
  role = aws_iam_role.eks_node.name

  tags = local.tags
}

###############################################################################
# Outputs
###############################################################################

output "eks_cluster_role_arn" {
  description = "ARN of the EKS control plane IAM role."
  value       = aws_iam_role.eks_cluster.arn
}

output "eks_node_role_arn" {
  description = "ARN of the EKS worker node IAM role."
  value       = aws_iam_role.eks_node.arn
}

output "eks_node_instance_profile_name" {
  description = "Name of the EC2 instance profile associated with the EKS worker node role."
  value       = aws_iam_instance_profile.eks_node.name
}

output "eks_node_instance_profile_arn" {
  description = "ARN of the EC2 instance profile associated with the EKS worker node role."
  value       = aws_iam_instance_profile.eks_node.arn
}

output "eks_worker_autoscaling_policy_arn" {
  description = "ARN of the custom Cluster Autoscaler IAM policy attached to the worker node role."
  value       = aws_iam_policy.eks_worker_autoscaling.arn
}

variable "namespace" {
  type        = string
  description = "Namespace for the CloudPosse label (typically the organization or OU)."
  default     = "acme"
}

variable "environment" {
  type        = string
  description = "Environment identifier for the CloudPosse label."
  default     = "ue2"
}

variable "name" {
  type        = string
  description = "Base name for the IAM access management framework."
  default     = "iam"
}

variable "attributes" {
  type        = list(string)
  description = "Additional attributes appended to the CloudPosse label."
  default     = []
}

variable "tags" {
  type        = map(string)
  description = "Additional tags applied to taggable IAM resources."
  default     = {}
}

variable "admin_users" {
  type        = list(string)
  description = "IAM user names that should be members of the admin group."
  default     = []
}

variable "non_admin_users" {
  type        = list(string)
  description = "IAM user names that should be members of the non-admin group."
  default     = []
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id

  # ARN template for the calling user's own IAM user; ${aws:username} is an IAM
  # policy variable and must remain un-interpolated in the generated JSON.
  own_user_arn = "arn:${local.partition}:iam::${local.account_id}:user/$${aws:username}"

  admin_users     = distinct(var.admin_users)
  non_admin_users = distinct(var.non_admin_users)
  all_users       = distinct(concat(local.admin_users, local.non_admin_users))
}

module "label" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = var.attributes
  tags        = var.tags

  label_order = ["namespace", "environment", "name", "attributes"]
}

module "label_admin" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["admin"])
  tags        = var.tags

  label_order = ["namespace", "environment", "name", "attributes"]
}

module "label_non_admin" {
  source  = "cloudposse/label/null"
  version = "0.25.0"

  namespace   = var.namespace
  environment = var.environment
  name        = var.name
  attributes  = concat(var.attributes, ["non-admin"])
  tags        = var.tags

  label_order = ["namespace", "environment", "name", "attributes"]
}

resource "aws_iam_user" "this" {
  for_each = toset(local.all_users)

  name = each.value
  path = "/"
  tags = module.label.tags
}

resource "aws_iam_group" "admin" {
  name = module.label_admin.id
  path = "/"
}

resource "aws_iam_group" "non_admin" {
  name = module.label_non_admin.id
  path = "/"
}

resource "aws_iam_group_membership" "admin" {
  count = length(local.admin_users) > 0 ? 1 : 0

  name  = "${module.label_admin.id}-membership"
  group = aws_iam_group.admin.name
  users = [for user in local.admin_users : aws_iam_user.this[user].name]
}

resource "aws_iam_group_membership" "non_admin" {
  count = length(local.non_admin_users) > 0 ? 1 : 0

  name  = "${module.label_non_admin.id}-membership"
  group = aws_iam_group.non_admin.name
  users = [for user in local.non_admin_users : aws_iam_user.this[user].name]
}

data "aws_iam_policy_document" "self_management" {
  statement {
    sid    = "AllowListAccountInformation"
    effect = "Allow"

    actions = [
      "iam:GetAccountPasswordPolicy",
      "iam:ListVirtualMFADevices",
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowManageOwnVirtualMFADevices"
    effect = "Allow"

    actions = [
      "iam:CreateVirtualMFADevice",
      "iam:DeleteVirtualMFADevice",
    ]

    resources = [
      "arn:${local.partition}:iam::${local.account_id}:mfa/*",
    ]
  }

  statement {
    sid    = "AllowManageOwnMFA"
    effect = "Allow"

    actions = [
      "iam:EnableMFADevice",
      "iam:ListMFADevices",
      "iam:ResyncMFADevice",
    ]

    resources = [local.own_user_arn]
  }

  statement {
    sid       = "AllowDeactivateOwnMFADeviceWithMFA"
    effect    = "Allow"
    actions   = ["iam:DeactivateMFADevice"]
    resources = [local.own_user_arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }

  statement {
    sid    = "AllowManageOwnAccessKeys"
    effect = "Allow"

    actions = [
      "iam:CreateAccessKey",
      "iam:DeleteAccessKey",
      "iam:ListAccessKeys",
      "iam:UpdateAccessKey",
    ]

    resources = [local.own_user_arn]
  }

  statement {
    sid    = "AllowManageOwnPassword"
    effect = "Allow"

    actions = [
      "iam:ChangePassword",
      "iam:GetUser",
    ]

    resources = [local.own_user_arn]
  }
}

data "aws_iam_policy_document" "admin_assume_role" {
  statement {
    sid       = "AllowAssumeAdminRoleWithMFA"
    effect    = "Allow"
    actions   = ["sts:AssumeRole"]
    resources = [aws_iam_role.admin.arn]

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

data "aws_iam_policy_document" "admin_role_trust" {
  statement {
    sid     = "AllowAccountRootToAssumeRoleWithMFA"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    condition {
      test     = "Bool"
      variable = "aws:MultiFactorAuthPresent"
      values   = ["true"]
    }
  }
}

resource "aws_iam_role" "admin" {
  name                 = "${module.label_admin.id}-role"
  description          = "Administrative role that can only be assumed with MFA present."
  assume_role_policy   = data.aws_iam_policy_document.admin_role_trust.json
  max_session_duration = 3600
  tags                 = module.label_admin.tags
}

resource "aws_iam_role_policy_attachment" "admin_administrator_access" {
  role       = aws_iam_role.admin.name
  policy_arn = "arn:${local.partition}:iam::aws:policy/AdministratorAccess"
}

resource "aws_iam_policy" "self_management" {
  name        = "${module.label.id}-self-management"
  description = "Allows members to manage their own credentials, MFA devices, and view account MFA and password policies."
  policy      = data.aws_iam_policy_document.self_management.json
  tags        = module.label.tags
}

resource "aws_iam_policy" "assume_admin_role" {
  name        = "${module.label_admin.id}-assume-role"
  description = "Allows members of the admin group to assume the administrative role when MFA is present."
  policy      = data.aws_iam_policy_document.admin_assume_role.json
  tags        = module.label_admin.tags
}

resource "aws_iam_group_policy_attachment" "admin_self_management" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "non_admin_self_management" {
  group      = aws_iam_group.non_admin.name
  policy_arn = aws_iam_policy.self_management.arn
}

resource "aws_iam_group_policy_attachment" "admin_assume_role" {
  group      = aws_iam_group.admin.name
  policy_arn = aws_iam_policy.assume_admin_role.arn
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

###############################################################################
# Variables
###############################################################################

variable "create" {
  description = "Master toggle that controls whether this configuration creates any resources."
  type        = bool
  default     = true
}

variable "create_security_group" {
  description = "When true a brand new security group is created (with a fallback VPC when no vpc_id is supplied). When false, the ingress/egress rules are attached to existing_security_group_id."
  type        = bool
  default     = true
}

variable "existing_security_group_id" {
  description = "ID of the pre-existing security group used when create_security_group is false."
  type        = string
  default     = ""
}

variable "vpc_id" {
  description = "ID of the VPC the new security group is created in. When empty (and create_security_group is true) a fallback VPC is provisioned automatically."
  type        = string
  default     = ""
}

variable "fallback_vpc_cidr_block" {
  description = "CIDR block of the fallback VPC provisioned when no vpc_id is supplied."
  type        = string
  default     = "10.0.0.0/16"
}

variable "security_group_description" {
  description = "Description applied to the security group created by this configuration."
  type        = string
  default     = "Managed by Terraform"
}

###############################################################################
# Label module inputs
###############################################################################

variable "namespace" {
  description = "Namespace (e.g. organisation or project) folded into the label module attributes."
  type        = string
  default     = ""
}

variable "environment" {
  description = "Environment (e.g. dev, staging, prod) handed to the label module."
  type        = string
  default     = ""
}

variable "stage" {
  description = "Stage (e.g. use1) folded into the label module attributes."
  type        = string
  default     = ""
}

variable "name" {
  description = "Name of the workload handed to the label module."
  type        = string
  default     = "app"
}

variable "attributes" {
  description = "Additional attributes appended to the labels generated by the label module."
  type        = list(string)
  default     = []
}

variable "tags" {
  description = "Additional tags applied to every resource created by this configuration."
  type        = map(string)
  default     = {}
}

###############################################################################
# Security group rule inputs
###############################################################################

variable "ingress_rules" {
  description = <<-EOT
    Map of ingress rules. Every rule supports the following categorised sources:
      cidr_blocks               - list of IPv4 CIDR blocks
      ipv6_cidr_blocks          - list of IPv6 CIDR blocks
      self                      - allow the security group to reference itself
      source_security_group_ids - list of source security group IDs
      prefix_list_ids           - list of managed prefix list IDs. When left empty
                                  the prefix list created by this configuration is
                                  used automatically.
  EOT
  type = map(object({
    description               = optional(string)
    from_port                 = optional(number, 0)
    to_port                   = optional(number, 0)
    protocol                  = optional(string, "-1")
    cidr_blocks               = optional(list(string), [])
    ipv6_cidr_blocks          = optional(list(string), [])
    self                      = optional(bool, false)
    source_security_group_ids = optional(list(string), [])
    prefix_list_ids           = optional(list(string), [])
  }))
  default = {}
}

variable "egress_rules" {
  description = <<-EOT
    Map of egress rules. Every rule supports the following categorised sources:
      cidr_blocks               - list of IPv4 CIDR blocks
      ipv6_cidr_blocks          - list of IPv6 CIDR blocks
      self                      - allow the security group to reference itself
      source_security_group_ids - list of destination security group IDs
      prefix_list_ids           - list of managed prefix list IDs. When left empty
                                  the prefix list created by this configuration is
                                  used automatically.
  EOT
  type = map(object({
    description               = optional(string)
    from_port                 = optional(number, 0)
    to_port                   = optional(number, 0)
    protocol                  = optional(string, "-1")
    cidr_blocks               = optional(list(string), [])
    ipv6_cidr_blocks          = optional(list(string), [])
    self                      = optional(bool, false)
    source_security_group_ids = optional(list(string), [])
    prefix_list_ids           = optional(list(string), [])
  }))
  default = {}
}

###############################################################################
# Managed prefix list inputs
###############################################################################

variable "create_prefix_list" {
  description = "Whether a managed prefix list should be created. Ignored when prefix_list_ids is not empty."
  type        = bool
  default     = false
}

variable "prefix_list_ids" {
  description = "IDs of pre-existing managed prefix lists. When empty and create_prefix_list is true, a prefix list is created."
  type        = list(string)
  default     = []
}

variable "prefix_list_address_family" {
  description = "Address family of the managed prefix list (IPv4 or IPv6)."
  type        = string
  default     = "IPv4"

  validation {
    condition     = contains(["IPv4", "IPv6"], var.prefix_list_address_family)
    error_message = "prefix_list_address_family must be either IPv4 or IPv6."
  }
}

variable "prefix_list_max_entries" {
  description = "Maximum number of entries the managed prefix list supports."
  type        = number
  default     = 5
}

variable "prefix_list_entries" {
  description = "Map of entries added to the managed prefix list (keys are arbitrary unique names)."
  type = map(object({
    cidr        = string
    description = optional(string)
  }))
  default = {}
}

###############################################################################
# Locals
###############################################################################

locals {
  enabled = var.create

  create_security_group = local.enabled && var.create_security_group

  # A fallback VPC is only provisioned when a brand new security group is
  # requested and the caller did not supply an existing VPC.
  create_fallback_vpc = local.create_security_group && length(var.vpc_id) == 0

  fallback_vpc_name = "${module.security_group_label.id}-vpc"

  vpc_id = local.create_fallback_vpc ? join("", aws_vpc.fallback[*].id) : var.vpc_id

  security_group_id = local.create_security_group ? join("", aws_security_group.this[*].id) : var.existing_security_group_id

  # Managed prefix list handling: create one only when explicitly requested and
  # no pre-existing prefix list IDs were supplied.
  create_prefix_list        = local.enabled && var.create_prefix_list && length(var.prefix_list_ids) == 0
  managed_prefix_list_ids   = local.create_prefix_list ? aws_ec2_managed_prefix_list.this[*].id : []
  effective_prefix_list_ids = length(var.prefix_list_ids) > 0 ? var.prefix_list_ids : local.managed_prefix_list_ids

  # The referenced label module does not accept namespace/stage/tags, so those
  # values are folded into the attributes list and tags are merged locally.
  security_group_attributes = concat(
    compact([var.namespace, var.stage]),
    ["sg"],
    var.attributes
  )

  prefix_list_attributes = concat(
    compact([var.namespace, var.stage]),
    ["prefix-list"],
    var.attributes
  )

  security_group_tags = merge(
    var.tags,
    { Name = module.security_group_label.id }
  )

  prefix_list_tags = merge(
    var.tags,
    { Name = module.prefix_list_label.id }
  )

  # AWS only accepts a single source security group per rule, therefore every
  # source security group ID becomes its own rule statement.
  ingress_rule_sources = {
    for name, rule in var.ingress_rules :
    name => (rule.self || length(rule.source_security_group_ids) == 0) ? [""] : rule.source_security_group_ids
  }

  egress_rule_sources = {
    for name, rule in var.egress_rules :
    name => (rule.self || length(rule.source_security_group_ids) == 0) ? [""] : rule.source_security_group_ids
  }

  ingress_rule_statements = {
    for statement in flatten([
      for name, rule in var.ingress_rules : [
        for idx, source_sg in local.ingress_rule_sources[name] : {
          key                      = source_sg == "" ? name : "${name}-${idx}"
          description              = rule.description
          from_port                = rule.from_port
          to_port                  = rule.to_port
          protocol                 = rule.protocol
          cidr_blocks              = rule.cidr_blocks
          ipv6_cidr_blocks         = rule.ipv6_cidr_blocks
          self                     = rule.self
          source_security_group_id = source_sg == "" ? null : source_sg
          prefix_list_ids          = length(rule.prefix_list_ids) > 0 ? rule.prefix_list_ids : local.effective_prefix_list_ids
        }
      ]
    ]) : statement.key => statement
  }

  egress_rule_statements = {
    for statement in flatten([
      for name, rule in var.egress_rules : [
        for idx, source_sg in local.egress_rule_sources[name] : {
          key                      = source_sg == "" ? name : "${name}-${idx}"
          description              = rule.description
          from_port                = rule.from_port
          to_port                  = rule.to_port
          protocol                 = rule.protocol
          cidr_blocks              = rule.cidr_blocks
          ipv6_cidr_blocks         = rule.ipv6_cidr_blocks
          self                     = rule.self
          source_security_group_id = source_sg == "" ? null : source_sg
          prefix_list_ids          = length(rule.prefix_list_ids) > 0 ? rule.prefix_list_ids : local.effective_prefix_list_ids
        }
      ]
    ]) : statement.key => statement
  }
}

###############################################################################
# Labels
###############################################################################

module "security_group_label" {
  source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"

  environment = var.environment
  name        = var.name
  attributes  = local.security_group_attributes
}

module "prefix_list_label" {
  source = "git::https://github.com/sohanyadav/terraform-aws-labels.git?ref=v1.0.0"

  environment = var.environment
  name        = var.name
  attributes  = local.prefix_list_attributes
}

###############################################################################
# Fallback VPC
###############################################################################

resource "aws_vpc" "fallback" {
  count = local.create_fallback_vpc ? 1 : 0

  cidr_block           = var.fallback_vpc_cidr_block
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.security_group_tags, { Name = local.fallback_vpc_name })
}

###############################################################################
# Managed prefix list
###############################################################################

resource "aws_ec2_managed_prefix_list" "this" {
  count = local.create_prefix_list ? 1 : 0

  name           = module.prefix_list_label.id
  address_family = var.prefix_list_address_family
  max_entries    = var.prefix_list_max_entries

  dynamic "entry" {
    for_each = var.prefix_list_entries
    content {
      cidr        = entry.value.cidr
      description = entry.value.description
    }
  }

  tags = local.prefix_list_tags
}

###############################################################################
# Security group (created only when create_security_group is true)
###############################################################################

resource "aws_security_group" "this" {
  count = local.create_security_group ? 1 : 0

  name        = module.security_group_label.id
  description = var.security_group_description
  vpc_id      = local.vpc_id

  tags = local.security_group_tags
}

###############################################################################
# Ingress rules (attached to the new or the existing security group)
###############################################################################

resource "aws_security_group_rule" "ingress" {
  for_each = local.ingress_rule_statements

  type              = "ingress"
  security_group_id = local.security_group_id

  description              = each.value.description
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  cidr_blocks              = each.value.cidr_blocks
  ipv6_cidr_blocks         = each.value.ipv6_cidr_blocks
  self                     = each.value.self
  source_security_group_id = each.value.source_security_group_id
  prefix_list_ids          = each.value.prefix_list_ids
}

###############################################################################
# Egress rules (attached to the new or the existing security group)
###############################################################################

resource "aws_security_group_rule" "egress" {
  for_each = local.egress_rule_statements

  type              = "egress"
  security_group_id = local.security_group_id

  description              = each.value.description
  from_port                = each.value.from_port
  to_port                  = each.value.to_port
  protocol                 = each.value.protocol
  cidr_blocks              = each.value.cidr_blocks
  ipv6_cidr_blocks         = each.value.ipv6_cidr_blocks
  self                     = each.value.self
  source_security_group_id = each.value.source_security_group_id
  prefix_list_ids          = each.value.prefix_list_ids
}

###############################################################################
# Outputs
###############################################################################

output "security_group_id" {
  description = "ID of the security group used by this configuration (created or existing)."
  value       = local.security_group_id
}

output "security_group_name" {
  description = "Name of the security group created by this configuration."
  value       = local.create_security_group ? module.security_group_label.id : null
}

output "security_group_arn" {
  description = "ARN of the security group created by this configuration."
  value       = local.create_security_group ? join("", aws_security_group.this[*].arn) : null
}

output "vpc_id" {
  description = "ID of the VPC hosting the security group."
  value       = local.vpc_id
}

output "fallback_vpc_id" {
  description = "ID of the fallback VPC provisioned by this configuration, if any."
  value       = join("", aws_vpc.fallback[*].id)
}

output "managed_prefix_list_id" {
  description = "ID of the managed prefix list created by this configuration, if any."
  value       = join("", aws_ec2_managed_prefix_list.this[*].id)
}

output "effective_prefix_list_ids" {
  description = "Managed prefix list IDs applied to rules that did not specify one explicitly."
  value       = local.effective_prefix_list_ids
}

terraform {
  required_version = ">= 1.4"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "5.74.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "4.0.5"
    }
    local = {
      source  = "hashicorp/local"
      version = "2.4.1"
    }
  }
}

###############################################################################
# Locals
###############################################################################

locals {
  cluster_name              = "demo-eks"
  aws_region                = "us-east-1"
  kubernetes_version        = "1.30"
  managed_policy_arn_prefix = "arn:aws:iam::aws:policy"

  azs = slice(data.aws_availability_zones.available.names, 0, 3)

  common_tags = {
    "kubernetes.io/cluster/${local.cluster_name}" = "owned"
    Project                                       = "demo-eks"
    ManagedBy                                     = "Terraform"
  }
}

###############################################################################
# Data sources (static / well-known lookups only)
###############################################################################

data "aws_availability_zones" "available" {
  state = "available"
}

# Well-known public EKS-optimized Amazon Linux 2 AMI id, resolved via SSM.
# The region is supplied by the configured provider, so no region argument is
# set here (aws_ssm_parameter does not accept one).
data "aws_ssm_parameter" "eks_ami" {
  name = "/aws/service/eks/optimized-ami/${local.kubernetes_version}/amazon-linux-2/recommended/image_id"
}

###############################################################################
# VPC
###############################################################################

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-vpc"
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-igw"
  })
}

###############################################################################
# Public subnet + NAT gateway
###############################################################################

resource "aws_subnet" "public" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, 0)
  availability_zone       = local.azs[0]
  map_public_ip_on_launch = false

  tags = merge(local.common_tags, {
    Name                     = "${local.cluster_name}-public"
    "kubernetes.io/role/elb" = "1"
  })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-public-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-nat-eip"
  })
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  depends_on = [aws_internet_gateway.main]

  # Bound the NAT create, which polls the gateway to reach `available`.
  timeouts {
    create = "3m"
    update = "3m"
    delete = "3m"
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-nat"
  })
}

###############################################################################
# Private subnets (one per availability zone)
###############################################################################

resource "aws_subnet" "private" {
  count             = 3
  vpc_id            = aws_vpc.main.id
  cidr_block        = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index + 1)
  availability_zone = local.azs[count.index]

  tags = merge(local.common_tags, {
    Name                              = "${local.cluster_name}-private-${count.index + 1}"
    "kubernetes.io/role/internal-elb" = "1"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-private-rt"
  })
}

resource "aws_route_table_association" "private" {
  count          = 3
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

###############################################################################
# KMS key for EKS secrets encryption
###############################################################################

resource "aws_kms_key" "eks" {
  description             = "Customer managed key used to encrypt ${local.cluster_name} Kubernetes secrets"
  deletion_window_in_days = 7
  enable_key_rotation     = true

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-kms"
  })
}

###############################################################################
# EKS cluster IAM role (eksClusterRole)
###############################################################################

resource "aws_iam_role" "eks_cluster" {
  name        = "eksClusterRole"
  description = "IAM role assumed by the ${local.cluster_name} EKS control plane"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "eks.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  tags = merge(local.common_tags, {
    Name = "eksClusterRole"
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "${local.managed_policy_arn_prefix}/AmazonEKSClusterPolicy"
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller" {
  role       = aws_iam_role.eks_cluster.name
  policy_arn = "${local.managed_policy_arn_prefix}/AmazonEKSVPCResourceController"
}

resource "aws_iam_role_policy" "eks_cluster_kms" {
  name = "eks-cluster-kms"
  role = aws_iam_role.eks_cluster.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Action = [
        "kms:Encrypt",
        "kms:Decrypt",
        "kms:DescribeKey",
        "kms:GenerateDataKey",
        "kms:GenerateDataKeyWithoutPlaintext",
        "kms:CreateGrant",
        "kms:ListGrants",
        "kms:RevokeGrant"
      ]
      Resource = aws_kms_key.eks.arn
    }]
  })
}

###############################################################################
# EKS cluster (private-only API endpoint, KMS encrypted secrets)
###############################################################################

resource "aws_eks_cluster" "main" {
  name     = local.cluster_name
  role_arn = aws_iam_role.eks_cluster.arn
  version  = local.kubernetes_version

  vpc_config {
    subnet_ids              = aws_subnet.private[*].id
    endpoint_private_access = true
    endpoint_public_access  = false
  }

  encryption_config {
    resources = ["secrets"]

    provider {
      key_arn = aws_kms_key.eks.arn
    }
  }

  # Skip the create-time self-managed add-on bootstrap. The unmanaged worker
  # nodes bootstrap themselves via /etc/eks/bootstrap.sh, so this sub-operation
  # is unnecessary and is a likely create-path stall on the emulator.
  bootstrap_self_managed_addons = false

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller,
    aws_iam_role_policy.eks_cluster_kms,
  ]

  # Bound on the provider waiter for control-plane activation. (Inert as a
  # remedy for the emulator hang, retained as a deterministic guardrail.)
  timeouts {
    create = "3m"
    update = "3m"
    delete = "3m"
  }

  tags = local.common_tags
}

###############################################################################
# Worker node security group
#
# All rules are scoped to the VPC CIDR instead of reading the EKS control
# plane's computed cluster security group. This keeps the required two-way
# node <-> control-plane traffic (443 and 1025-65535) inside the same VPC while
# letting the node SG depend only on the VPC, so the data-plane path no longer
# waits on control-plane activation.
#
# Every ingress member and every egress member carries the same attribute
# shape (description, from_port, to_port, protocol, plus self or cidr_blocks)
# because ingress/egress are sets of objects that must unify.
###############################################################################

resource "aws_security_group" "node" {
  name        = "${local.cluster_name}-node-sg"
  description = "Security group for the ${local.cluster_name} worker nodes"
  vpc_id      = aws_vpc.main.id

  # Unrestricted communication between nodes.
  ingress {
    description = "Allow nodes to communicate with each other"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    self        = true
  }

  # Control plane -> node bootstrapping / kubelet (scoped to the VPC CIDR).
  ingress {
    description = "Allow control-plane traffic to the kubelet API from within the VPC"
    from_port   = 1025
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  ingress {
    description = "Allow control-plane traffic to pods serving on port 443 from within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  # Outbound only within the VPC CIDR.
  egress {
    description = "Allow outbound traffic within the VPC CIDR only"
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow nodes to reach the cluster API server within the VPC"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Allow nodes to reach the control plane kubelet range within the VPC"
    from_port   = 1025
    to_port     = 65535
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-node-sg"
  })
}

###############################################################################
# Worker node IAM role + instance profile (eks-demo-node)
###############################################################################

resource "aws_iam_role" "eks_node" {
  name        = "eks-demo-node"
  description = "IAM role for the ${local.cluster_name} unmanaged worker nodes"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [{
      Effect = "Allow"
      Principal = {
        Service = "ec2.amazonaws.com"
      }
      Action = "sts:AssumeRole"
    }]
  })

  tags = merge(local.common_tags, {
    Name = "eks-demo-node"
  })
}

resource "aws_iam_role_policy_attachment" "eks_node_worker" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "${local.managed_policy_arn_prefix}/AmazonEKSWorkerNodePolicy"
}

resource "aws_iam_role_policy_attachment" "eks_node_cni" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "${local.managed_policy_arn_prefix}/AmazonEKS_CNI_Policy"
}

resource "aws_iam_role_policy_attachment" "eks_node_ecr" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "${local.managed_policy_arn_prefix}/AmazonEC2ContainerRegistryReadOnly"
}

resource "aws_iam_role_policy_attachment" "eks_node_ssm" {
  role       = aws_iam_role.eks_node.name
  policy_arn = "${local.managed_policy_arn_prefix}/AmazonSSMManagedInstanceCore"
}

resource "aws_iam_instance_profile" "eks_node" {
  name = "eks-demo-node"
  role = aws_iam_role.eks_node.name

  tags = merge(local.common_tags, {
    Name = "eks-demo-node"
  })
}

###############################################################################
# SSH key pair for the worker nodes
###############################################################################

resource "tls_private_key" "eks" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "local_file" "eks_pem" {
  content         = tls_private_key.eks.private_key_pem
  filename        = pathexpand("~/.ssh/eks-aws.pem")
  file_permission = "0600"
}

resource "aws_key_pair" "eks" {
  key_name   = "eks_kp"
  public_key = tls_private_key.eks.public_key_openssh

  tags = merge(local.common_tags, {
    Name = "eks_kp"
  })
}

###############################################################################
# Worker node launch template
###############################################################################

resource "aws_launch_template" "eks_node" {
  name_prefix   = "${local.cluster_name}-node-"
  description   = "Launch template for the ${local.cluster_name} worker nodes"
  image_id      = data.aws_ssm_parameter.eks_ami.value
  instance_type = "t3.medium"
  key_name      = aws_key_pair.eks.key_name

  vpc_security_group_ids = [aws_security_group.node.id]

  iam_instance_profile {
    name = aws_iam_instance_profile.eks_node.name
  }

  # IMDSv2 required, hop limit 2 so containers can reach the metadata service.
  metadata_options {
    http_endpoint               = "enabled"
    http_tokens                 = "required"
    http_put_response_hop_limit = 2
    instance_metadata_tags      = "enabled"
  }

  block_device_mappings {
    device_name = "/dev/xvda"

    ebs {
      volume_size = 30
      volume_type = "gp2"
      encrypted   = true
    }
  }

  # Bootstrap the node into the cluster and signal the CloudFormation stack.
  # Endpoint/CA are resolved at instance runtime by bootstrap.sh (using the
  # cluster name and region) rather than read from the cluster's computed
  # attributes, so this resource does not block on control-plane activation.
  user_data = base64encode(<<-EOT
    #!/bin/bash
    set -o xtrace
    /etc/eks/bootstrap.sh ${local.cluster_name} \
      --region ${local.aws_region}
    /opt/aws/bin/cfn-signal --exit-code $? \
      --stack eks-cluster-stack \
      --resource NodeGroup \
      --region ${local.aws_region}
  EOT
  )

  tag_specifications {
    resource_type = "instance"

    tags = merge(local.common_tags, {
      Name = "${local.cluster_name}-node"
    })
  }

  tag_specifications {
    resource_type = "volume"

    tags = merge(local.common_tags, {
      Name = "${local.cluster_name}-node-volume"
    })
  }

  tags = merge(local.common_tags, {
    Name = "${local.cluster_name}-node-lt"
  })
}

# Allow the launch template to settle before the CloudFormation stack consumes it.
# Uses the core terraform_data resource (no external provider download required).
# The delay is invoked through an explicit shell and capped with `timeout` so
# this apply-time step can never become an unbounded tail.
resource "terraform_data" "eks_launch_template_delay" {
  triggers_replace = aws_launch_template.eks_node.id

  provisioner "local-exec" {
    interpreter = ["/bin/bash", "-c"]
    command     = "timeout 60 bash -c 'sleep 30'"
  }
}

###############################################################################
# CloudFormation managed Auto Scaling Group (eks-cluster-stack)
###############################################################################

resource "aws_cloudformation_stack" "eks_cluster" {
  name = "eks-cluster-stack"

  template_body = jsonencode({
    AWSTemplateFormatVersion = "2010-09-09"
    Description              = "Auto Scaling Group for the ${local.cluster_name} worker nodes"

    Parameters = {
      LaunchTemplateId = {
        Type        = "String"
        Description = "ID of the worker node launch template"
      }
      LaunchTemplateVersion = {
        Type        = "String"
        Description = "Version of the worker node launch template"
      }
      SubnetIds = {
        Type        = "CommaDelimitedList"
        Description = "Private subnets for the worker nodes"
      }
    }

    Resources = {
      NodeGroup = {
        Type = "AWS::AutoScaling::AutoScalingGroup"

        Properties = {
          AutoScalingGroupName = "${local.cluster_name}-node-asg"
          LaunchTemplate = {
            LaunchTemplateId = { Ref = "LaunchTemplateId" }
            Version          = { Ref = "LaunchTemplateVersion" }
          }
          MinSize           = "1"
          DesiredCapacity   = "3"
          MaxSize           = "4"
          VPCZoneIdentifier = { Ref = "SubnetIds" }
        }

        UpdatePolicy = {
          AutoScalingRollingUpdate = {
            MaxBatchSize          = 1
            MinInstancesInService = 3
            PauseTime             = "PT5M"
          }
        }
      }
    }

    Outputs = {
      AutoScalingGroupId = {
        Description = "ID of the worker node Auto Scaling Group"
        Value       = { Ref = "NodeGroup" }
      }
    }
  })

  parameters = {
    LaunchTemplateId      = aws_launch_template.eks_node.id
    LaunchTemplateVersion = tostring(aws_launch_template.eks_node.latest_version)
    SubnetIds             = join(",", aws_subnet.private[*].id)
  }

  depends_on = [terraform_data.eks_launch_template_delay]

  # Single, explicit, short timeout control (the schema-documented nested
  # block). The legacy timeout_in_minutes attribute is intentionally omitted so
  # there is exactly one governing bound and no conflicting precedence. No
  # CreationPolicy/signal wait is present.
  timeouts {
    create = "5m"
    update = "5m"
    delete = "5m"
  }

  tags = merge(local.common_tags, {
    Name = "eks-cluster-stack"
  })
}

###############################################################################
# Outputs
###############################################################################

output "node_instance_role_arn" {
  description = "ARN of the worker node IAM instance role (eks-demo-node)"
  value       = aws_iam_role.eks_node.arn
}

output "node_security_group_id" {
  description = "ID of the worker node security group"
  value       = aws_security_group.node.id
}

output "autoscaling_group_id" {
  description = "ID of the Auto Scaling Group created by the eks-cluster-stack CloudFormation stack"
  value       = aws_cloudformation_stack.eks_cluster.outputs["AutoScalingGroupId"]
}

provider "aws" {
  alias  = "replica"
  region = "us-west-2"
}

###############################################################################
# Data sources (static / provider-level lookups only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  primary_region = "us-east-1"
  replica_region = "us-west-2"

  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition

  state_bucket_name   = "eks-terraform-state-${local.account_id}-${local.primary_region}"
  replica_bucket_name = "eks-terraform-state-replica-${local.account_id}-${local.replica_region}"

  # Names may not change without recreating buckets / keys
  primary_key_alias = "alias/eks-terraform-state-primary"
  replica_key_alias = "alias/eks-terraform-state-replica"

  # Provided map of EKS stack names -> region the stack lives in.
  # A DynamoDB lock table, an IAM policy and a generated backend.tf are
  # produced for every entry in this map.
  eks_stacks = {
    "eks-dev"     = { region = "us-east-1" }
    "eks-staging" = { region = "us-east-1" }
    "eks-prod"    = { region = "us-west-2" }
  }

  # Standardised state-management label set applied to every taggable resource.
  common_tags = {
    ManagedBy   = "Terraform"
    Project     = "eks-terraform-state"
    Purpose     = "remote-state-management"
    Environment = "shared-services"
    Owner       = "platform-engineering"
    Compliance  = "internal"
  }
}

###############################################################################
# KMS - primary (source) key and replica (destination) key
###############################################################################

resource "aws_kms_key" "primary" {
  description             = "KMS key for EKS Terraform remote state encryption (${local.primary_region})"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  is_enabled              = true

  tags = merge(local.common_tags, {
    Name   = "eks-terraform-state-primary"
    Region = local.primary_region
    Role   = "primary-state-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "primary" {
  name          = local.primary_key_alias
  target_key_id = aws_kms_key.primary.key_id
}

resource "aws_kms_key" "replica" {
  provider = aws.replica

  description             = "KMS key for EKS Terraform remote state replica encryption (${local.replica_region})"
  deletion_window_in_days = 7
  enable_key_rotation     = true
  is_enabled              = true

  tags = merge(local.common_tags, {
    Name   = "eks-terraform-state-replica"
    Region = local.replica_region
    Role   = "replica-state-key"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica" {
  provider = aws.replica

  name          = local.replica_key_alias
  target_key_id = aws_kms_key.replica.key_id
}

###############################################################################
# Primary state bucket (us-east-1)
###############################################################################

resource "aws_s3_bucket" "state" {
  bucket = local.state_bucket_name

  tags = merge(local.common_tags, {
    Name   = local.state_bucket_name
    Region = local.primary_region
    Role   = "primary-state-bucket"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "state" {
  bucket = aws_s3_bucket.state.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "state" {
  bucket = aws_s3_bucket.state.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "state" {
  bucket = aws_s3_bucket.state.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "state_bucket_policy" {
  statement {
    sid    = "DenyNonSecureTransport"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.state.arn,
      "${aws_s3_bucket.state.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "state" {
  bucket = aws_s3_bucket.state.id
  policy = data.aws_iam_policy_document.state_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.state]
}

###############################################################################
# Replica state bucket (us-west-2)
###############################################################################

resource "aws_s3_bucket" "replica" {
  provider = aws.replica
  bucket   = local.replica_bucket_name

  tags = merge(local.common_tags, {
    Name   = local.replica_bucket_name
    Region = local.replica_region
    Role   = "replica-state-bucket"
  })

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    object_ownership = "BucketOwnerEnforced"
  }
}

resource "aws_s3_bucket_versioning" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.replica.arn
      sse_algorithm     = "aws:kms"
    }

    bucket_key_enabled = true
  }
}

data "aws_iam_policy_document" "replica_bucket_policy" {
  statement {
    sid    = "DenyNonSecureTransport"
    effect = "Deny"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.replica.arn,
      "${aws_s3_bucket.replica.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }
}

resource "aws_s3_bucket_policy" "replica" {
  provider = aws.replica
  bucket   = aws_s3_bucket.replica.id
  policy   = data.aws_iam_policy_document.replica_bucket_policy.json

  depends_on = [aws_s3_bucket_public_access_block.replica]
}

###############################################################################
# IAM role for S3 cross-region replication
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceToAssume"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "eks-tf-state-replication-${local.account_id}"
  description        = "Role assumed by S3 to replicate EKS Terraform state to ${local.replica_region}"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = merge(local.common_tags, {
    Name = "eks-tf-state-replication"
    Role = "s3-cross-region-replication"
  })
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketMetadataRead"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
      "s3:GetBucketAcl",
    ]

    resources = [aws_s3_bucket.state.arn]
  }

  statement {
    sid    = "SourceObjectRead"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
      "s3:GetObjectVersion",
      "s3:GetObjectLegalHold",
      "s3:GetObjectRetention",
    ]

    resources = ["${aws_s3_bucket.state.arn}/*"]
  }

  statement {
    sid    = "ReplicaObjectWrite"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
      "s3:ObjectOwnerOverrideToBucketOwner",
    ]

    resources = ["${aws_s3_bucket.replica.arn}/*"]
  }

  statement {
    sid       = "DecryptSourceObjectsWithPrimaryKey"
    effect    = "Allow"
    actions   = ["kms:Decrypt", "kms:DescribeKey"]
    resources = [aws_kms_key.primary.arn]
  }

  statement {
    sid    = "EncryptReplicaObjectsWithReplicaKey"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.replica.arn]
  }
}

resource "aws_iam_policy" "replication" {
  name        = "eks-tf-state-replication-policy"
  description = "Least-privilege policy allowing S3 to replicate KMS-encrypted EKS Terraform state"
  policy      = data.aws_iam_policy_document.replication.json

  tags = merge(local.common_tags, {
    Name = "eks-tf-state-replication-policy"
    Role = "s3-cross-region-replication"
  })
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

###############################################################################
# Cross-region replication configuration
###############################################################################

resource "aws_s3_bucket_replication_configuration" "state" {
  bucket = aws_s3_bucket.state.id
  role   = aws_iam_role.replication.arn

  rule {
    id     = "eks-terraform-state-cross-region-replication"
    status = "Enabled"

    filter {}

    delete_marker_replication {
      status = "Disabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.replica.arn
      storage_class = "STANDARD"
      account       = local.account_id

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.replica.arn
      }
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.state,
    aws_s3_bucket_versioning.replica,
    aws_iam_role_policy_attachment.replication,
  ]
}

###############################################################################
# Per-stack DynamoDB state locking tables
###############################################################################

resource "aws_dynamodb_table" "state_lock" {
  for_each = local.eks_stacks

  name         = "eks-terraform-locks-${each.key}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "LockID"

  attribute {
    name = "LockID"
    type = "S"
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.primary.arn
  }

  point_in_time_recovery {
    enabled = true
  }

  tags = merge(local.common_tags, {
    Name   = "eks-terraform-locks-${each.key}"
    Stack  = each.key
    Region = each.value.region
    Role   = "state-locking-table"
  })

  lifecycle {
    prevent_destroy = true
  }
}

###############################################################################
# Per-stack IAM policies (DynamoDB lock table + state bucket prefix + KMS)
###############################################################################

data "aws_iam_policy_document" "stack_state_access" {
  for_each = local.eks_stacks

  statement {
    sid    = "StackStateLocking"
    effect = "Allow"

    actions = [
      "dynamodb:GetItem",
      "dynamodb:PutItem",
      "dynamodb:DeleteItem",
      "dynamodb:UpdateItem",
      "dynamodb:DescribeTable",
      "dynamodb:Query",
      "dynamodb:Scan",
    ]

    resources = [aws_dynamodb_table.state_lock[each.key].arn]
  }

  statement {
    sid    = "StackStateBucketList"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:GetBucketLocation",
      "s3:GetBucketVersioning",
    ]

    resources = [aws_s3_bucket.state.arn]

    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values = [
        "${each.key}/",
        "${each.key}/*",
      ]
    }
  }

  statement {
    sid    = "StackStateObjectAccess"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:AbortMultipartUpload",
      "s3:ListMultipartUploadParts",
    ]

    resources = ["${aws_s3_bucket.state.arn}/${each.key}/*"]
  }

  statement {
    sid    = "StackStateKeyUsage"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
      "kms:ReEncryptFrom",
      "kms:ReEncryptTo",
    ]

    resources = [aws_kms_key.primary.arn]
  }
}

resource "aws_iam_policy" "stack_state_access" {
  for_each = local.eks_stacks

  name        = "eks-stack-${each.key}-state-access"
  description = "Terraform remote state access for the ${each.key} EKS stack (${each.value.region})"
  policy      = data.aws_iam_policy_document.stack_state_access[each.key].json

  tags = merge(local.common_tags, {
    Name   = "eks-stack-${each.key}-state-access"
    Stack  = each.key
    Region = each.value.region
    Role   = "stack-state-access-policy"
  })
}

###############################################################################
# Generated backend.tf files for every stack
###############################################################################

resource "local_file" "backend" {
  for_each = local.eks_stacks

  filename = "${path.module}/eks-stacks/${each.key}/backend.tf"

  content = <<-EOT
    # ---------------------------------------------------------------------------
    # Managed by Terraform - do not edit manually.
    # Remote state backend for the ${each.key} EKS stack (${each.value.region}).
    # ---------------------------------------------------------------------------

    terraform {
      backend "s3" {
        bucket         = "${aws_s3_bucket.state.id}"
        key            = "${each.key}/terraform.tfstate"
        region         = "${local.primary_region}"
        dynamodb_table = "${aws_dynamodb_table.state_lock[each.key].name}"
        kms_key_id     = "${aws_kms_key.primary.arn}"
        encrypt        = true
      }
    }
  EOT

  file_permission = "0644"
}

terraform {
  required_version = ">= 1.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
    random = {
      source  = "hashicorp/random"
      version = ">= 3.0"
    }
  }
}

data "aws_region" "current" {}

data "aws_partition" "current" {}

data "aws_caller_identity" "current" {}

resource "random_pet" "this" {
  length    = 2
  separator = "-"
}

locals {
  name       = random_pet.this.id
  region     = data.aws_region.current.region
  partition  = data.aws_partition.current.partition
  account_id = data.aws_caller_identity.current.account_id

  sqs_integration_uri = "arn:${local.partition}:apigateway:${local.region}:sqs:path/${local.account_id}/${aws_sqs_queue.this.name}"

  access_log_group_name = "/aws/apigateway/${local.name}"

  access_log_format = jsonencode({
    requestId      = "$context.requestId"
    ip             = "$context.identity.sourceIp"
    requestTime    = "$context.requestTime"
    routeKey       = "$context.routeKey"
    status         = "$context.status"
    protocol       = "$context.protocol"
    responseLength = "$context.responseLength"
    errorMessage   = "$context.error.message"
  })
}

resource "aws_kms_key" "this" {
  description             = "Customer managed key used to encrypt the ${local.name} WebSocket message queue"
  enable_key_rotation     = true
  deletion_window_in_days = 7

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "this" {
  name          = "alias/${local.name}-sqs"
  target_key_id = aws_kms_key.this.key_id
}

resource "aws_sqs_queue" "this" {
  name                              = local.name
  kms_master_key_id                 = aws_kms_key.this.arn
  kms_data_key_reuse_period_seconds = 300

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_cloudwatch_log_group" "access" {
  name              = local.access_log_group_name
  retention_in_days = 1

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_iam_role" "apigw" {
  name = "${local.name}-apigw"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ApiGatewayAssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "apigateway.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy" "apigw" {
  name = "${local.name}-apigw"
  role = aws_iam_role.apigw.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "SendMessagesToQueue"
        Effect = "Allow"
        Action = [
          "sqs:SendMessage",
          "sqs:GetQueueAttributes",
          "sqs:GetQueueUrl"
        ]
        Resource = aws_sqs_queue.this.arn
      },
      {
        Sid    = "UseQueueEncryptionKey"
        Effect = "Allow"
        Action = [
          "kms:GenerateDataKey",
          "kms:Decrypt"
        ]
        Resource = aws_kms_key.this.arn
      },
      {
        Sid    = "WriteApiAccessLogs"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:DescribeLogStreams",
          "logs:PutLogEvents"
        ]
        Resource = [
          aws_cloudwatch_log_group.access.arn,
          "${aws_cloudwatch_log_group.access.arn}:*"
        ]
      }
    ]
  })
}

resource "aws_apigatewayv2_api" "this" {
  name                       = local.name
  protocol_type              = "WEBSOCKET"
  route_selection_expression = "$request.body.action"
}

resource "aws_apigatewayv2_integration" "connect" {
  api_id           = aws_apigatewayv2_api.this.id
  integration_type = "MOCK"

  request_templates = {
    "application/json" = "{\"statusCode\": 200}"
  }
}

resource "aws_apigatewayv2_integration_response" "connect" {
  api_id                   = aws_apigatewayv2_api.this.id
  integration_id           = aws_apigatewayv2_integration.connect.id
  integration_response_key = "/200/"

  response_templates = {
    "application/json" = "{\"statusCode\": 200}"
  }
}

resource "aws_apigatewayv2_integration" "default" {
  api_id             = aws_apigatewayv2_api.this.id
  integration_type   = "AWS"
  integration_method = "POST"
  integration_uri    = local.sqs_integration_uri
  credentials_arn    = aws_iam_role.apigw.arn

  passthrough_behavior = "NEVER"

  request_parameters = {
    "integration.request.querystring.Action" = "'SendMessage'"
  }

  request_templates = {
    "application/json" = "MessageBody=$util.urlEncode($input.body)"
  }
}

resource "aws_apigatewayv2_integration_response" "default" {
  api_id                   = aws_apigatewayv2_api.this.id
  integration_id           = aws_apigatewayv2_integration.default.id
  integration_response_key = "/200/"

  response_templates = {
    "application/json" = "$input.body"
  }
}

resource "aws_apigatewayv2_integration" "disconnect" {
  api_id             = aws_apigatewayv2_api.this.id
  integration_type   = "AWS"
  integration_method = "POST"
  integration_uri    = local.sqs_integration_uri
  credentials_arn    = aws_iam_role.apigw.arn

  request_parameters = {
    "integration.request.querystring.Action"      = "'SendMessage'"
    "integration.request.querystring.MessageBody" = "'Client disconnected'"
  }
}

resource "aws_apigatewayv2_route" "connect" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$connect"
  target    = "integrations/${aws_apigatewayv2_integration.connect.id}"
}

resource "aws_apigatewayv2_route" "disconnect" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$disconnect"
  target    = "integrations/${aws_apigatewayv2_integration.disconnect.id}"
}

resource "aws_apigatewayv2_route" "default" {
  api_id    = aws_apigatewayv2_api.this.id
  route_key = "$default"
  target    = "integrations/${aws_apigatewayv2_integration.default.id}"
}

resource "aws_apigatewayv2_route_response" "connect" {
  api_id             = aws_apigatewayv2_api.this.id
  route_id           = aws_apigatewayv2_route.connect.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_route_response" "default" {
  api_id             = aws_apigatewayv2_api.this.id
  route_id           = aws_apigatewayv2_route.default.id
  route_response_key = "$default"
}

resource "aws_apigatewayv2_stage" "dev" {
  api_id      = aws_apigatewayv2_api.this.id
  name        = "dev"
  auto_deploy = true

  access_log_settings {
    destination_arn = aws_cloudwatch_log_group.access.arn
    format          = local.access_log_format
  }

  depends_on = [
    aws_apigatewayv2_route.connect,
    aws_apigatewayv2_route.disconnect,
    aws_apigatewayv2_route.default,
  ]
}

output "websocket_endpoint" {
  description = "Full WebSocket endpoint URL including the stage name"
  value       = aws_apigatewayv2_stage.dev.invoke_url
}

###############################################################################
# Variables
###############################################################################

variable "primary_bucket_name" {
  description = "Base name of the primary S3 bucket. The AWS account ID is appended for global uniqueness."
  type        = string
  default     = "example1"
}

variable "secondary_bucket_name" {
  description = "Base name of the secondary S3 bucket. The AWS account ID is appended for global uniqueness."
  type        = string
  default     = "example2"
}

variable "mrap_name" {
  description = "Name of the S3 Multi-Region Access Point."
  type        = string
  default     = "example-mrap"
}

variable "primary_region" {
  description = "Region for the primary S3 bucket."
  type        = string
  default     = "us-east-1"
}

variable "secondary_region" {
  description = "Region for the secondary S3 bucket and the Multi-Region Access Point control plane."
  type        = string
  default     = "us-west-2"
}

###############################################################################
# Providers (regional aliases required for the multi-region resources)
###############################################################################

provider "aws" {
  alias  = "us_east_1"
  region = var.primary_region
}

provider "aws" {
  alias  = "us_west_2"
  region = var.secondary_region
}

###############################################################################
# Data sources (static provider metadata only)
###############################################################################

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

###############################################################################
# Locals
###############################################################################

locals {
  account_id       = data.aws_caller_identity.current.account_id
  partition        = data.aws_partition.current.partition
  primary_bucket   = "${var.primary_bucket_name}-${local.account_id}"
  secondary_bucket = "${var.secondary_bucket_name}-${local.account_id}"
}

###############################################################################
# Primary KMS key (us-east-1)
###############################################################################

resource "aws_kms_key" "primary" {
  provider                = aws.us_east_1
  description             = "Customer managed key for S3 bucket ${local.primary_bucket}"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = {
    Name = local.primary_bucket
  }
}

resource "aws_kms_alias" "primary" {
  provider      = aws.us_east_1
  name          = "alias/${local.primary_bucket}"
  target_key_id = aws_kms_key.primary.key_id
}

###############################################################################
# Secondary KMS key (us-west-2)
###############################################################################

resource "aws_kms_key" "secondary" {
  provider                = aws.us_west_2
  description             = "Customer managed key for S3 bucket ${local.secondary_bucket}"
  enable_key_rotation     = true
  deletion_window_in_days = 30

  tags = {
    Name = local.secondary_bucket
  }
}

resource "aws_kms_alias" "secondary" {
  provider      = aws.us_west_2
  name          = "alias/${local.secondary_bucket}"
  target_key_id = aws_kms_key.secondary.key_id
}

###############################################################################
# Primary S3 bucket (us-east-1)
###############################################################################

resource "aws_s3_bucket" "primary" {
  provider = aws.us_east_1
  bucket   = local.primary_bucket

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "primary" {
  provider = aws.us_east_1
  bucket   = aws_s3_bucket.primary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "primary" {
  provider   = aws.us_east_1
  bucket     = aws_s3_bucket.primary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.primary]
}

resource "aws_s3_bucket_versioning" "primary" {
  provider = aws.us_east_1
  bucket   = aws_s3_bucket.primary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "primary" {
  provider = aws.us_east_1
  bucket   = aws_s3_bucket.primary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "primary" {
  provider = aws.us_east_1
  bucket   = aws_s3_bucket.primary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.primary.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

###############################################################################
# Secondary S3 bucket (us-west-2)
###############################################################################

resource "aws_s3_bucket" "secondary" {
  provider = aws.us_west_2
  bucket   = local.secondary_bucket

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_ownership_controls" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  rule {
    object_ownership = "BucketOwnerPreferred"
  }
}

resource "aws_s3_bucket_acl" "secondary" {
  provider   = aws.us_west_2
  bucket     = aws_s3_bucket.secondary.id
  acl        = "private"
  depends_on = [aws_s3_bucket_ownership_controls.secondary]
}

resource "aws_s3_bucket_versioning" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_public_access_block" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "secondary" {
  provider = aws.us_west_2
  bucket   = aws_s3_bucket.secondary.id

  rule {
    apply_server_side_encryption_by_default {
      kms_master_key_id = aws_kms_key.secondary.arn
      sse_algorithm     = "aws:kms"
    }
    bucket_key_enabled = true
  }
}

###############################################################################
# Replication IAM role (assumable by S3)
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    effect = "Allow"

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }

    actions = ["sts:AssumeRole"]
  }
}

resource "aws_iam_role" "replication" {
  provider           = aws.us_east_1
  name               = "s3-replication-${local.primary_bucket}"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json
}

data "aws_iam_policy_document" "replication" {
  statement {
    sid    = "SourceBucketReadPermissions"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:ListBucket",
    ]

    resources = [aws_s3_bucket.primary.arn]
  }

  statement {
    sid    = "SourceObjectReadPermissions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = ["${aws_s3_bucket.primary.arn}/*"]
  }

  statement {
    sid    = "DestinationObjectReplicationPermissions"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = ["${aws_s3_bucket.secondary.arn}/*"]
  }

  statement {
    sid    = "SourceKMSDecryptPermissions"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.primary.arn]
  }

  statement {
    sid    = "DestinationKMSEncryptPermissions"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey",
    ]

    resources = [aws_kms_key.secondary.arn]
  }
}

resource "aws_iam_role_policy" "replication" {
  provider = aws.us_east_1
  name     = "s3-replication-policy"
  role     = aws_iam_role.replication.id
  policy   = data.aws_iam_policy_document.replication.json
}

###############################################################################
# Cross-region replication (primary -> secondary)
###############################################################################

resource "aws_s3_bucket_replication_configuration" "primary" {
  provider = aws.us_east_1

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
  ]

  role   = aws_iam_role.replication.arn
  bucket = aws_s3_bucket.primary.id

  rule {
    id     = "replicate-kms-objects"
    status = "Enabled"

    filter {
      prefix = ""
    }

    delete_marker_replication {
      status = "Enabled"
    }

    source_selection_criteria {
      sse_kms_encrypted_objects {
        status = "Enabled"
      }
    }

    destination {
      bucket        = aws_s3_bucket.secondary.arn
      storage_class = "STANDARD"

      encryption_configuration {
        replica_kms_key_id = aws_kms_key.secondary.arn
      }

      replication_time {
        status = "Enabled"

        time {
          minutes = 15
        }
      }

      metrics {
        status = "Enabled"

        event_threshold {
          minutes = 15
        }
      }
    }
  }
}

###############################################################################
# Multi-Region Access Point (control plane in us-west-2)
###############################################################################

resource "aws_s3control_multi_region_access_point" "example" {
  provider = aws.us_west_2

  details {
    name = var.mrap_name

    region {
      bucket = aws_s3_bucket.primary.id
    }

    region {
      bucket = aws_s3_bucket.secondary.id
    }
  }

  depends_on = [
    aws_s3_bucket_versioning.primary,
    aws_s3_bucket_versioning.secondary,
  ]
}

data "aws_iam_policy_document" "mrap" {
  statement {
    sid    = "AllowOwningAccountGetAndPut"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions = [
      "s3:GetObject",
      "s3:PutObject",
    ]

    resources = [
      "arn:${local.partition}:s3::${local.account_id}:accesspoint/${aws_s3control_multi_region_access_point.example.alias}/object/*",
    ]
  }
}

resource "aws_s3control_multi_region_access_point_policy" "example" {
  provider = aws.us_west_2

  details {
    name   = aws_s3control_multi_region_access_point.example.details[0].name
    policy = data.aws_iam_policy_document.mrap.json
  }
}

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

locals {
  lambda_assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = "sts:AssumeRole"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })

  lambda_log_group_arn = "arn:aws:logs:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:log-group:/aws/lambda/*"
}

# ---------------------------------------------------------------------------
# Customer managed policy shared by both Lambda automation roles: CloudWatch
# Logs write permissions.
# ---------------------------------------------------------------------------
resource "aws_iam_policy" "lambda_logging" {
  name        = "lambda_logging"
  description = "Grants AWS Lambda functions permission to write logs to CloudWatch Logs."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CreateLogGroup"
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup"
        ]
        Resource = local.lambda_log_group_arn
      },
      {
        Sid    = "WriteLogStreams"
        Effect = "Allow"
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "${local.lambda_log_group_arn}:*"
      }
    ]
  })

  tags = {
    Name = "lambda_logging"
  }
}

# ---------------------------------------------------------------------------
# Role: create_ddb_backup_role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "create_ddb_backup_role" {
  name        = "create_ddb_backup_role"
  description = "Lambda execution role that creates DynamoDB backups."

  assume_role_policy = local.lambda_assume_role_policy

  tags = {
    Name = "create_ddb_backup_role"
  }
}

resource "aws_iam_policy" "create_ddb_backup_policy" {
  name        = "create_ddb_backup_policy"
  description = "Allows creation of DynamoDB table backups."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "CreateBackups"
        Effect = "Allow"
        Action = [
          "dynamodb:CreateBackup",
          "dynamodb:DescribeBackup",
          "dynamodb:DescribeTable",
          "dynamodb:ListTables"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "create_ddb_backup_policy"
  }
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_attach" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.create_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "create_ddb_backup_logging_attach" {
  role       = aws_iam_role.create_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# ---------------------------------------------------------------------------
# Role: remove_ddb_backup_role
# ---------------------------------------------------------------------------
resource "aws_iam_role" "remove_ddb_backup_role" {
  name        = "remove_ddb_backup_role"
  description = "Lambda execution role that lists and deletes DynamoDB backups."

  assume_role_policy = local.lambda_assume_role_policy

  tags = {
    Name = "remove_ddb_backup_role"
  }
}

resource "aws_iam_policy" "remove_ddb_backup_policy" {
  name        = "remove_ddb_backup_policy"
  description = "Allows listing and deletion of DynamoDB table backups."

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "ListAndDeleteBackups"
        Effect = "Allow"
        Action = [
          "dynamodb:ListBackups",
          "dynamodb:DescribeBackup",
          "dynamodb:DeleteBackup"
        ]
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "remove_ddb_backup_policy"
  }
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_attach" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.remove_ddb_backup_policy.arn
}

resource "aws_iam_role_policy_attachment" "remove_ddb_backup_logging_attach" {
  role       = aws_iam_role.remove_ddb_backup_role.name
  policy_arn = aws_iam_policy.lambda_logging.arn
}

# ---------------------------------------------------------------------------
# Outputs
# ---------------------------------------------------------------------------
output "create_ddb_backup_role_name" {
  description = "Name of the DynamoDB backup creation Lambda execution role."
  value       = aws_iam_role.create_ddb_backup_role.name
}

output "create_ddb_backup_role_arn" {
  description = "ARN of the DynamoDB backup creation Lambda execution role."
  value       = aws_iam_role.create_ddb_backup_role.arn
}

output "remove_ddb_backup_role_name" {
  description = "Name of the DynamoDB backup removal Lambda execution role."
  value       = aws_iam_role.remove_ddb_backup_role.name
}

output "remove_ddb_backup_role_arn" {
  description = "ARN of the DynamoDB backup removal Lambda execution role."
  value       = aws_iam_role.remove_ddb_backup_role.arn
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0, < 6.0.0"
    }
  }
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name          = "projectvpc"
  vpc_cidr          = "10.0.0.0/16"
  public_subnet_cidr  = "10.0.1.0/24"
  private_subnet_cidr = "10.0.2.0/24"
  public_subnet_az    = data.aws_availability_zones.available.names[0]
  private_subnet_az   = data.aws_availability_zones.available.names[1]

  common_tags = {
    Name      = local.vpc_name
    Project   = local.vpc_name
    ManagedBy = "Terraform"
  }
}

resource "aws_vpc" "main" {
  cidr_block           = local.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(local.common_tags, {
    Name = local.vpc_name
  })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-igw"
  })
}

resource "aws_subnet" "public" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.public_subnet_cidr
  availability_zone = local.public_subnet_az

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-public-subnet"
    Tier = "public"
  })
}

resource "aws_subnet" "private" {
  vpc_id            = aws_vpc.main.id
  cidr_block        = local.private_subnet_cidr
  availability_zone = local.private_subnet_az

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-private-subnet"
    Tier = "private"
  })
}

resource "aws_eip" "nat" {
  domain = "vpc"

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat-eip"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_nat_gateway" "main" {
  allocation_id = aws_eip.nat.id
  subnet_id     = aws_subnet.public.id

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-nat-gateway"
  })

  depends_on = [aws_internet_gateway.main]
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-public-rt"
  })
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id

  route {
    cidr_block     = "0.0.0.0/0"
    nat_gateway_id = aws_nat_gateway.main.id
  }

  tags = merge(local.common_tags, {
    Name = "${local.vpc_name}-private-rt"
  })
}

resource "aws_route_table_association" "public" {
  subnet_id      = aws_subnet.public.id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  subnet_id      = aws_subnet.private.id
  route_table_id = aws_route_table.private.id
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

data "aws_caller_identity" "current" {}

data "aws_region" "current" {}

data "aws_partition" "current" {}

locals {
  bucket_name = "endpoint-backup-${data.aws_caller_identity.current.account_id}"

  account_root_arn = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
}

###############################################################################
# Customer Managed KMS Key
###############################################################################

data "aws_iam_policy_document" "endpoint_backup_kms" {
  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowEndpointBackupKeyUsage"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_user.endpoint_backup.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

resource "aws_kms_key" "endpoint_backup" {
  description             = "Customer managed key for the endpoint backup bucket"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.endpoint_backup_kms.json

  tags = {
    Name = "endpoint-backup"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "endpoint_backup" {
  name          = "alias/endpoint-backup"
  target_key_id = aws_kms_key.endpoint_backup.key_id
}

###############################################################################
# S3 Bucket
###############################################################################

resource "aws_s3_bucket" "endpoint_backup" {
  bucket = local.bucket_name

  tags = {
    Name        = local.bucket_name
    Description = "Secure endpoint backup bucket"
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.endpoint_backup.arn
    }

    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_accelerate_configuration" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  status = "Suspended"
}

resource "aws_s3_bucket_versioning" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id

  versioning_configuration {
    status = "Enabled"
  }
}

###############################################################################
# S3 Bucket Policy
###############################################################################

data "aws_iam_policy_document" "endpoint_backup_bucket" {
  statement {
    sid    = "DenyInsecureTransport"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid    = "DenyTLSVersionLessThan12"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = ["s3:*"]

    resources = [
      aws_s3_bucket.endpoint_backup.arn,
      "${aws_s3_bucket.endpoint_backup.arn}/*",
    ]

    condition {
      test     = "NumericLessThan"
      variable = "s3:TlsVersion"
      values   = ["1.2"]
    }
  }

  statement {
    sid    = "DenyComplianceModeRetentionOver90Days"
    effect = "Deny"

    principals {
      type        = "*"
      identifiers = ["*"]
    }

    actions = [
      "s3:PutObject",
      "s3:PutObjectRetention",
    ]

    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:object-lock-mode"
      values   = ["COMPLIANCE"]
    }

    condition {
      test     = "NumericGreaterThan"
      variable = "s3:object-lock-remaining-retention-days"
      values   = ["90"]
    }
  }
}

resource "aws_s3_bucket_policy" "endpoint_backup" {
  bucket = aws_s3_bucket.endpoint_backup.id
  policy = data.aws_iam_policy_document.endpoint_backup_bucket.json

  depends_on = [aws_s3_bucket_public_access_block.endpoint_backup]
}

###############################################################################
# IAM User
###############################################################################

resource "aws_iam_user" "endpoint_backup" {
  name = "endpoint-backup"

  tags = {
    Name = "endpoint-backup"
  }
}

###############################################################################
# Customer-managed IAM Policy
###############################################################################

data "aws_iam_policy_document" "endpoint_backup_user" {
  statement {
    sid    = "ListBucket"
    effect = "Allow"

    actions = [
      "s3:ListBucket",
      "s3:ListBucketVersions",
      "s3:GetBucketLocation",
    ]

    resources = [aws_s3_bucket.endpoint_backup.arn]
  }

  statement {
    sid    = "ObjectReadWriteDelete"
    effect = "Allow"

    actions = [
      "s3:GetObject",
      "s3:GetObjectVersion",
      "s3:PutObject",
      "s3:DeleteObject",
      "s3:DeleteObjectVersion",
    ]

    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
  }

  statement {
    sid    = "ObjectRetention"
    effect = "Allow"

    actions = [
      "s3:GetObjectRetention",
      "s3:PutObjectRetention",
      "s3:GetObjectLegalHold",
      "s3:PutObjectLegalHold",
    ]

    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
  }

  statement {
    sid    = "ObjectRestore"
    effect = "Allow"

    actions = [
      "s3:RestoreObject",
    ]

    resources = ["${aws_s3_bucket.endpoint_backup.arn}/*"]
  }

  statement {
    sid    = "KmsDataKeyAccess"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:GenerateDataKey",
      "kms:DescribeKey",
    ]

    resources = [aws_kms_key.endpoint_backup.arn]
  }
}

resource "aws_iam_policy" "endpoint_backup_bucket_read_write" {
  name        = "endpoint-backup-bucket-read-write-access"
  description = "Read, write, delete, version, retention and restore access to the endpoint backup bucket plus data key access on the endpoint backup customer managed KMS key."
  policy      = data.aws_iam_policy_document.endpoint_backup_user.json

  tags = {
    Name = "endpoint-backup-bucket-read-write-access"
  }
}

resource "aws_iam_user_policy_attachment" "endpoint_backup" {
  user       = aws_iam_user.endpoint_backup.name
  policy_arn = aws_iam_policy.endpoint_backup_bucket_read_write.arn
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
  partition  = data.aws_partition.current.partition
  env        = "dev"
}

###############################################################################
# Provider aliases for the non-default regions.
# The default (injected) provider is used for the primary source region
# (us-east-1) and for the global IAM resources.
###############################################################################

provider "aws" {
  alias  = "source2"
  region = "us-west-2"
}

provider "aws" {
  alias  = "replica1"
  region = "eu-west-1"
}

provider "aws" {
  alias  = "replica2"
  region = "ap-southeast-1"
}

###############################################################################
# KMS key policies
#   - source keys: replication role may decrypt
#   - replica keys: replication role may (re)encrypt
###############################################################################

data "aws_iam_policy_document" "source_kms_policy" {
  statement {
    sid    = "EnableRootAccountControl"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowReplicationRoleToDecrypt"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

data "aws_iam_policy_document" "replica_kms_policy" {
  statement {
    sid    = "EnableRootAccountControl"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["arn:${local.partition}:iam::${local.account_id}:root"]
    }

    actions   = ["kms:*"]
    resources = ["*"]
  }

  statement {
    sid    = "AllowReplicationRoleToEncrypt"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.replication.arn]
    }

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]

    resources = ["*"]
  }
}

###############################################################################
# Customer managed KMS keys (one per region) + aliases
###############################################################################

resource "aws_kms_key" "source1" {
  description             = "SSE-KMS customer managed key for source log buckets in us-east-1"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.source_kms_policy.json

  tags = {
    Env = local.env
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "source1" {
  name          = "alias/sourcekey1"
  target_key_id = aws_kms_key.source1.key_id
}

resource "aws_kms_key" "source2" {
  provider                = aws.source2
  description             = "SSE-KMS customer managed key for source log buckets in us-west-2"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.source_kms_policy.json

  tags = {
    Env = local.env
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "source2" {
  provider      = aws.source2
  name          = "alias/sourcekey2"
  target_key_id = aws_kms_key.source2.key_id
}

resource "aws_kms_key" "replica1" {
  provider                = aws.replica1
  description             = "SSE-KMS customer managed key for replica log buckets in eu-west-1"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.replica_kms_policy.json

  tags = {
    Env = local.env
  }

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_kms_alias" "replica1" {
  provider      = aws.replica1
  name          = "alias/replicakey1"
  target_key_id = aws_kms_key.replica1.key_id
}

resource "aws_kms_key" "replica2" {
  provider                = aws.replica2
  description             = "SSE-KMS customer managed key for replica log buckets in ap-southeast-1"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.replica_kms_policy.json

  tags = {
