  name          = "alias/replicakey2"
  target_key_id = aws_kms_key.replica2.key_id
}

###############################################################################
# IAM role assumed by S3 plus least-privilege replication policy
###############################################################################

data "aws_iam_policy_document" "replication_assume_role" {
  statement {
    sid     = "AllowS3ServiceToAssumeRole"
    effect  = "Allow"
    actions = ["sts:AssumeRole"]

    principals {
      type        = "Service"
      identifiers = ["s3.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "replication" {
  name               = "s3-cross-region-replication-role"
  assume_role_policy = data.aws_iam_policy_document.replication_assume_role.json

  tags = {
    Env = local.env
  }
}

data "aws_iam_policy_document" "replication_policy" {
  statement {
    sid    = "ReadSourceBucketConfigurations"
    effect = "Allow"

    actions = [
      "s3:GetReplicationConfiguration",
      "s3:GetBucketVersioning",
      "s3:ListBucket",
    ]

    resources = [
      aws_s3_bucket.log1a.arn,
      aws_s3_bucket.log1b.arn,
      aws_s3_bucket.log2a.arn,
      aws_s3_bucket.log2b.arn,
    ]
  }

  statement {
    sid    = "ReadSourceObjectVersions"
    effect = "Allow"

    actions = [
      "s3:GetObjectVersionForReplication",
      "s3:GetObjectVersion",
      "s3:GetObjectVersionAcl",
      "s3:GetObjectVersionTagging",
    ]

    resources = [
      "${aws_s3_bucket.log1a.arn}/*",
      "${aws_s3_bucket.log1b.arn}/*",
      "${aws_s3_bucket.log2a.arn}/*",
      "${aws_s3_bucket.log2b.arn}/*",
    ]
  }

  statement {
    sid    = "ReplicateObjectsIntoReplicaBuckets"
    effect = "Allow"

    actions = [
      "s3:ReplicateObject",
      "s3:ReplicateDelete",
      "s3:ReplicateTags",
    ]

    resources = [
      "${aws_s3_bucket.log1a_replica1.arn}/*",
      "${aws_s3_bucket.log1b_replica1.arn}/*",
      "${aws_s3_bucket.log2a_replica1.arn}/*",
      "${aws_s3_bucket.log2b_replica1.arn}/*",
      "${aws_s3_bucket.log1a_replica2.arn}/*",
      "${aws_s3_bucket.log1b_replica2.arn}/*",
      "${aws_s3_bucket.log2a_replica2.arn}/*",
      "${aws_s3_bucket.log2b_replica2.arn}/*",
    ]
  }

  statement {
    sid    = "DecryptSourceObjectsWithSourceKeys"
    effect = "Allow"

    actions = [
      "kms:Decrypt",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.source1.arn,
      aws_kms_key.source2.arn,
    ]
  }

  statement {
    sid    = "EncryptReplicaObjectsWithReplicaKeys"
    effect = "Allow"

    actions = [
      "kms:Encrypt",
      "kms:GenerateDataKey*",
      "kms:ReEncrypt*",
      "kms:DescribeKey",
    ]

    resources = [
      aws_kms_key.replica1.arn,
      aws_kms_key.replica2.arn,
    ]
  }
}

resource "aws_iam_policy" "replication" {
  name        = "s3-cross-region-replication-policy"
  description = "Least privilege permissions for S3 cross-region replication of Env=dev log buckets"
  policy      = data.aws_iam_policy_document.replication_policy.json

  tags = {
    Env = local.env
  }
}

resource "aws_iam_role_policy_attachment" "replication" {
  role       = aws_iam_role.replication.name
  policy_arn = aws_iam_policy.replication.arn
}

